SpeakStone_BookTexts = {
    ["a_treatise_on_military_ranks_html_body_h1_aligncentera_treatise_on"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">A TREATISE ON MILITARY RANKS</H1><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRankAlliance\" align=\"left\"/><BR/>\n<P align=\"right\">What follows are</P>\n<P align=\"right\">the military ranks</P>\n<P align=\"right\">of the Alliance,</P>\n<P align=\"right\">proceeded by such</P>\n<P align=\"right\">information as is</P>\n<P align=\"right\">known for the races</P>\n<P align=\"right\">of the Horde.  Each</P>\n<P align=\"right\">is presented in two</P>\n<P align=\"right\">sections, the officers and then the enlisted, with the ranks of each listed in descending order from highest to lowest. Long live the Alliance!</P>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<H1 align=\"center\">OFFICER RANKS OF THE ALLIANCE</H1><BR/>\n<P align=\"center\">Part 1</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>\n<P align=\"right\">Grand Marshal</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>\n<P align=\"right\">Field Marshal</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>\n<P align=\"right\">Marshal</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>\n<P align=\"right\">Commander</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>\n<P align=\"right\">Lieutenant Commander</P><BR/><BR/>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<H1 align=\"center\">OFFICER RANKS OF THE ALLIANCE</H1><BR/>\n<P align=\"center\">Part 2</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">Knight-Champion</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">Knight-Captain</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">Knight-Lieutenant</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">Knight</P><BR/><BR/>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<H1 align=\"center\">ENLISTED RANKS OF THE ALLIANCE</H1><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank05\" align=\"left\"/><BR/>\n<P align=\"right\">Sergeant Major</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank04\" align=\"left\"/><BR/>\n<P align=\"right\">Master Sergeant</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank03\" align=\"left\"/><BR/>\n<P align=\"right\">Sergeant</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank02\" align=\"left\"/><BR/>\n<P align=\"right\">Corporal</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank01\" align=\"left\"/><BR/>\n<P align=\"right\">Private</P><BR/><BR/>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<H1 align=\"center\">OFFICER RANKS OF THE HORDE</H1><BR/>\n<P align=\"center\">Part 1</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>\n<P align=\"right\">High Warlord</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>\n<P align=\"right\">Warlord</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>\n<P align=\"right\">General</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>\n<P align=\"right\">Lieutenant General</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>\n<P align=\"right\">Champion</P><BR/><BR/>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<H1 align=\"center\">OFFICER RANKS OF THE HORDE</H1><BR/>\n<P align=\"center\">Part 2</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">Centurion</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">Legionnaire</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">Blood Guard</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">Stone Guard</P><BR/><BR/>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<H1 align=\"center\">ENLISTED RANKS OF THE HORDE</H1><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank05\" align=\"left\"/><BR/>\n<P align=\"right\">First Sergeant</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank04\" align=\"left\"/><BR/>\n<P align=\"right\">Senior Sergeant</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank03\" align=\"left\"/><BR/>\n<P align=\"right\">Sergeant</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank02\" align=\"left\"/><BR/>\n<P align=\"right\">Grunt</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank01\" align=\"left\"/><BR/>\n<P align=\"right\">Scout</P><BR/><BR/>\n</BODY>\n</HTML>" },
    ["admiral_barean_westwind_admiral_barean_westwind_grand_admiral_of"] = { "Admiral Barean Westwind\nGrand Admiral of the Scarlet Fleet \nCitizen of Kul'Tiras\nLost off the Frozen Coast of Northrend" },
    ["admiral_barean_westwind_admiral_barean_westwindbgrand_admiral_of_the"] = { "Admiral Barean Westwind$BGrand Admiral of the Scarlet Fleet$BCitizen of Kul'Tiras$BLost off the Frozen Coast of Northrend" },
    ["aftermath_of_the_second_war_the_devastating_second_war_against_the"] = { "The devastating Second War against the orcish horde left the Alliance of Lordaeron in a state of shock and disarray. The bloodthirsty orcs, led by the mighty warchief, Orgrim Doomhammer, not only smashed their way through the dwarf-held lands of Khaz Modan, but had razed many of Lordaeron's central provinces as well. The unrelenting orcs even succeeded in ravaging the$Belves' remote kingdom of Quel'Thalas before their rampage was finally stopped.", "The Alliance armies led by Sir Anduin Lothar, Uther the Lightbringer, and Admiral Daelin Proudmoore pushed the orcs south into the shattered land of Azeroth - the first kingdom to fall before the orcs' ruthless onslaught.$B$BThe Alliance forces under Sir Lothar managed to push Doomhammer's clans out of Lordaeron and back into the orc-controlled lands of Azeroth. Lothar's forces surrounded the orcs' volcanic citadel of Blackrock Spire and laid siege to their defenses.", "In a last-ditch effort, Doomhammer and his lieutenants staged a daring charge from the Spire and clashed with Lothar's paladins in the center of the Burning Steppes. Doomhammer and Lothar squared off in a titanic battle that left both mighty combatants battered and drained. Though Doomhammer narrowly succeeded in vanquishing Lothar, the great hero's death did not have the effect the warchief had hoped for.", "Turalyon, Lothar's most trusted lieutenant, took up Lothar's bloodstained shield and rallied his grief-stricken brethren for a vicious counterattack. Under the ragged standards of both Lordaeron and Azeroth, Turalyon's troops slaughtered the bulk of Doomhammer's remaining forces in a glorious, but terrible rout.", "There was nothing left for the ragged, scattered orc survivors but to flee to the last standing bastion of orcish power - the dark portal.$B$BTuralyon and his warriors chased the remaining orcs through the festering Swamp of Sorrows and into the corrupted Blasted Lands where the dark portal stood. There, at the foot of the colossal portal, the broken horde and the rugged Alliance clashed in what would be the last, bloodiest battle of the Second War.", "Outnumbered and driven mad by the curse of their bloodlust, the orcs inevitably fell before the wrath of the Alliance. Doomhammer was taken prisoner and escorted to Lordaeron while his broken clans were rounded up and hauled north - back to Lordaeron." },
    ["ancient_highborne_tome_the_defiance_of_farondis_queen_azsharas"] = { "THE DEFIANCE OF FARONDIS\n\nQueen Azshara's pact with the demon lord Sargeras went mostly uncontested by her subjects. One of the few that dared to defy her was Prince Farondis.\n\nAs one of the queen's trusted advisors, Farondis was in regular contact with the Highborne of Zin-Azshari, but his palace in Azsuna was several leagues away from the elven capital. As such, he was able to witness Sargeras' influence on the Highborne court without falling sway to the demons' temptation." },
    ["ancient_highborne_tome_the_fate_of_azsuna_azshara_wasted"] = { "THE FATE OF AZSUNA\n\nAzshara wasted no time in punishing Farondis and his people. In a frightening display of arcane power, she destroyed the Tidestone of Golganneth, and in doing so, released a wave of dark energy over all of Azsuna and its inhabitants.\n\nSince that day, the elves of Azsuna have been unable to experience the release of death. Their spirits - our spirits - wander the land indefinitely... all because of our prince's unwise allegiances." },
    ["ancient_highborne_tome_the_wrath_of_the_queen_farondis"] = { "THE WRATH OF THE QUEEN\n\nFarondis' plan was bold, but simple: destroy the Well of Eternity in Zin-Azshari. Doing so would close the portal to Sargeras' realm and stem the tide of evil before it even started. In order to accomplish this task, he would use the power of an artifact stored deep within Nar'thalas Academy: The Tidestone of Golganneth.\n\nUnfortunately, the queen's influence in Farondis' palace was already deep-seated. Vandros, a young noble in Farondis' court, caught word of Farondis' plans to defy the Queen, and reported the insurrection to Queen Azshara herself." },
    ["ancient_tidesage_scroll_house_stormsong_laid_claim_to_the"] = { "House Stormsong laid claim to the most fertile valley in the northern reaches .$B$BIt took our lord's name as tribute for our gifts.$B$BWe were home." },
    ["ancient_tidesage_scroll_stormsong_was_the_first_to_hear"] = { "Stormsong was the first to hear them.$B$BNot the crashing waves at the surface -- gentle whispers, imperceptible to all but him.$B$BThey guided his mind ever deeper, revealing untold truths of the powers within him.$B$BWe would never be the same." },
    ["ancient_tidesage_scroll_the_depths_guidance_became_clear_they"] = { "The depths' guidance became clear; they guided us home. A new home.$B$BThe land was rich and could provide for endless generations.$B$BWe guided others to us, sending our sages to ensure safe passage." },
    ["arathor_and_the_troll_wars_as_the_high_elves_fought_for"] = { "As the high elves fought for their lives against the trolls' fierce onslaught, the scattered, nomadic humans of Lordaeron fought to consolidate their own tribal lands. The tribes of early humanity raided each other's settlements with little heed for racial unification or honor.", "Yet one tribe, known as the Arathi, saw that the trolls were becoming too great a threat to ignore. The Arathi wished to bring all of the tribes under its rule so that they could provide a unified front against the troll warbands.", "Over the course of six years, the cunning Arathi outmaneuvered and outfought the rival tribes. After every victory, the Arathi offered peace and equality to the conquered people; thus, they won the loyalty of those they had beaten. Eventually the Arathi tribe came to include many disparate tribes, and the ranks of its army grew vast.", "Confident that they could hold their own against the troll warbands or even the reclusive elves if need be, the Arathi warlords decided to construct a mighty fortress city in the southern regions of Lordaeron. The city-state, named Strom, became the capital of the Arathi nation, Arathor. As Arathor prospered, humans from all over the vast continent traveled south to the protection and safety of Strom.", "United under one banner, the human tribes developed a strong, optimistic culture. Thoradin, the king of Arathor, knew that the mysterious elves in the northlands were under constant siege by the trolls, but refused to risk the safety of his people in defense of reclusive strangers. Many months passed as rumors of the elves' supposed defeat trickled down from the north. It was only when weary ambassadors from Quel'Thalas reached Strom that Thoradin realized how great the troll threat truly was.", "The elves informed Thoradin that the troll armies were vast and that once the trolls had destroyed Quel'Thalas, they would move on to attack the southlands. The desperate elves, in dire need of military aid, hastily agreed to teach certain select humans to wield magic in exchange for their help against the warbands.", "Thoradin, distrustful of any magic, agreed to aid the elves out of necessity. Almost immediately, elven sorcerers arrived in Arathor and began to instruct a group of humans in the ways of magic.", "The elves found that although humans were innately clumsy in their handling of magic, they possessed a startling natural affinity for it. One hundred men were taught the very basics of the elves' magical secrets: no more than was absolutely necessary to combat the trolls. Convinced that their human students were ready to aid in the struggle, the elves left Strom and traveled north alongside the mighty armies of King Thoradin.", "The united elf and human armies clashed against the overwhelming troll warbands at the foot of the Alterac Mountains. The battle lasted for many days, but the unflagging armies of Arathor never tired or gave an inch of ground before the troll onslaught. The elven lords deemed that the time had come to release the powers of their magic upon the enemy.", "The hundred human magi and a multitude of elven sorcerers called down the fury of the heavens and set the troll armies ablaze. The elemental fires prevented the trolls from regenerating their wounds and burned their tortured forms from the inside out.", "As the troll armies broke and attempted to flee, Thoradin's armies ran them down and slaughtered every last one of their soldiers. The trolls would never fully recover from their defeat, and history would never see the trolls rise as one nation again. Assured that Quel'Thalas was saved from destruction, the elves made a pledge of loyalty and friendship to the nation of Arathor and to the bloodline of its king, Thoradin. Humans and elves would nurture peaceful relations for ages to come. $B" },
    ["archavons_log_it_appears_archavon_has_been_keeping"] = { "<It appears Archavon has been keeping a journal. It appears to be written in multiple languages. A tally has been kept on the cover. >$B$BHorde:   $B  Keep Defended: $4024w$B  Keep Captured: $4022w$B$BAlliance:$B  Keep Defended: $4025w$B  Keep Captured: $4023w$B$BDay 10$BThe Makers are gone.  I have been left to watch.$B                -ARCHAVON$B", "Day 10500: $BThe halls are quiet.  Empty. $B$BI thought the Makers want me to watch the hall, but they never specifically said, ï¿½Archavon, watch the hall... Maybe it's okay if I watch outside too?  It would probably be less boring outside.  It's decided - I am now responsible for watching the hall AND the outside.  I shall take on my new responsibility next month.$B                -ARCHAVON$B$BDay 20120:$BThe outside is much more open than the hall.  There are convenient cliffs and mountains bordering it.  I'm now confident that the Makers meant for me to watch this too.  I hope they don't notice that I've only been in the hall for the first decade.$B                -ARCHAVON$B", "Day 1051213:$BI invented a new game today too, it's called \"Kick the Revenant.\"  I made it from the front of the keep to the main road today.  Before next year, I'm going to try to land it over the river.$B                -ARCHAVON$B$BDay 2145617:$BSome little green people came today.  I have added them to my watching responsibilities.$B                -ARCHAVON$B$BDay 2145657:$BThe little green people have built extra buildings here now.  More buildings seems good.  I think I will speak to them this week and thank them.$B                -ARCHAVON$B$BDay 214566:$BI thanked one of the little green people today for the extra buildings.  He told me that he'd be bringing more people for me to watch soon - lots of them.$B$BI'm excited to have more things to watch.$B                -ARCHAVON$B", "Day 214586:$BThe little green people brought a lot of others, pointed them at each other, and then they all started fighting!$B$BI have trimmed my watching responsibilities back to the hall for safety, but I brought a lot of their baubles with me so that it can maybe be less boring this time.$B                -ARCHAVON$B$BDay 214620:$BThings have gotten much worse.  I am not sure what the Makers want me to do.  I'm trying to stay in my hall, but the violent people come in after me several times a day.  They take my baubles.$B                -ARCHAVON$B$B", "Day 214701:$BMy brothers are back!  It turns out they were sleeping in other closed off halls.$B$BI'm a little mad that they left me alone to do all the watching, but I shared my shinier baubles with them anyway because I'm tired of being alone and attacked all the time.$B                -ARCHAVON$B$BDay 214760:$BThe violent little people have started attacking my brothers, which is sad.  They leave me alone mostly now though, which is not sad.$B$BI think they want the shiny baubles I gave away.  I feel guilty.$B                -ARCHAVON$B" },
    ["archavons_log_old_it_appears_archavon_has_been_keeping"] = { "<It appears Archavon has been keeping a journal. It appears to be written in multiple languages. A tally has been kept on the cover. >\n\nHorde:   \n  Keep Defended: $4024w\n  Keep Captured: $4022w\n\nAlliance:\n  Keep Defended: $4025w\n  Keep Captured: $4023w\n\nDay 10\nThe Makers are gone.  I have been left to watch.\n                -ARCHAVON", "Day 10500: \nThe halls are quiet.  Empty. \n\nI thought the Makers wanted me to watch the hall, but they never specifically said, \"Archavon, watch the hall...\" Maybe it's okay if I watch outside too?  It would probably be less boring outside.  It's decided - I am now responsible for watching the hall AND the outside.  I shall take on my new responsibility next month.\n                -ARCHAVON\n\nDay 20120:\nThe outside is much more open than the hall.  There are convenient cliffs and mountains bordering it.  I'm now confident that the Makers meant for me to watch this too.  I hope they don't notice that I've only been in the hall for the first decade.\n                -ARCHAVON", "Day 1051213:\nI invented a new game today too, it's called \"Kick the Revenant.\"  I made it from the front of the keep to the main road today.  Before next year, I'm going to try to land it over the river.\n                -ARCHAVON\n\nDay 2145617:\nSome little green people came today.  I have added them to my watching responsibilities.\n                -ARCHAVON\n\nDay 2145657:\nThe little green people have built extra buildings here now.  More buildings seems good.  I think I will speak to them this week and thank them.\n                -ARCHAVON\n\nDay 2145666:\nI thanked one of the little green people today for the extra buildings.  He told me that he'd be bringing more people for me to watch soon - lots of them.\n\nI'm excited to have more things to watch.\n                -ARCHAVON", "Day 2145866:\nThe little green people brought a lot of others, pointed them at each other, and then they all started fighting!\n\nI have trimmed my watching responsibilities back to the hall for safety, but I brought a lot of their baubles with me so that it can maybe be less boring this time.\n                -ARCHAVON\n\nDay 2146240:\nThings have gotten much worse.  I am not sure what the Makers want me to do.  I'm trying to stay in my hall, but the violent people come in after me several times a day.  They take my baubles.\n                -ARCHAVON", "Day 2147021:\nMy brothers are back!  It turns out they were sleeping in other closed off halls.\n\nI'm a little mad that they left me alone to do all the watching, but I shared my shinier baubles with them anyway because I'm tired of being alone and attacked all the time.\n                -ARCHAVON\n\nDay 2147060:\nThe violent little people have started attacking my brothers, which is sad.  They leave me alone mostly now though, which is not sad.\n\nI think they want the shiny baubles I gave away.  I feel guilty.\n                -ARCHAVON" },
    ["archmage_antonidas_archmage_antonidas_grand_magus_of_the"] = { "Archmage Antonidas, Grand Magus of the Kirin Tor$B$BThe great city of Dalaran stands once again - a testament to the tenacity and will of its greatest son.$B$BYour sacrifices will not have been in vain, dearest friend.$B$B$BWith Love and Honor,$B$BJaina Proudmoore" },
    ["archmage_khadgar_of_the_kirin_tor_archmage_khadgar_of_the_kirin_tor"] = { "Archmage Khadgar of the Kirin Tor\n\nFormer apprentice of Medivh. Supreme Commander of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.\n\nNever did one so selflessly delve into the dark heart of magic and warfare. We wish you well, bold wanderer. Wherever you are.\n\n- Antonidas - Archmage of Dalaran" },
    ["archmage_khadgar_of_the_kirin_tor_archmage_khadgar_of_the_kirin_torbbformer"] = { "Archmage Khadgar of the Kirin Tor$B$BFormer apprentice of Medivh. Supreme Commander of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.$B$BNever did one so selflessly delve into the dark heart of magic and warfare. We wish you well, bold wanderer. Wherever you are.$B$B- Antonidas - Archmage of Dalaran" },
    ["arellas_fireleaf_arellas_fireleaf_high_wizard_of_the"] = { "Arellas Fireleaf\nHigh Wizard of the Scarlet Crusade \nCitizen of Quel'Thalas  \nLocked in eternal combat with the Necromancer Diesalven" },
    ["arellas_fireleaf_arellas_fireleafbhigh_wizard_of_the_scarlet"] = { "Arellas Fireleaf$BHigh Wizard of the Scarlet Crusade$BCitizen of Quel'Thalas$BLocked in eternal combat with the Necromancer Diesalven" },
    ["bloodstained_fortune_dont_despair_your_special_ogre_is"] = { "Don't despair. Your special ogre is out there somewhere." },
    ["bloodstained_fortune_drunkenness_is_next_to_godliness"] = { "Drunkenness is next to godliness." },
    ["bloodstained_fortune_let_sleeping_gronn_lie"] = { "Let sleeping gronn lie." },
    ["bloodstained_fortune_lucky_numbers_13_9_17_4"] = { "Lucky Numbers: 13 9 17 4 n" },
    ["bloodstained_fortune_put_up_your_sword_your_maul"] = { "Put up your sword, your maul, and your lance. The crystals have told us to give peace a chance." },
    ["bloodstained_fortune_seek_a_higher_path_in_life"] = { "Seek a higher path in life. That way, you can avoid low-lifes." },
    ["bloodstained_fortune_sorry_you_werent_a_winner_this"] = { "Sorry, you weren't a winner this time. Please play again." },
    ["bloodstained_fortune_the_meaning_of_life_is_the"] = { "The meaning of life is... (The rest of this message has been accidentally eaten.)" },
    ["bloodstained_fortune_think_positive_a_large_gut_to"] = { "Think positive! A large gut to one is a pair of love handles to another." },
    ["bloodstained_fortune_this_message_was_brought_to_you"] = { "This message was brought to you by the Ogri'la Exploitation Committee. Made in Gadgetzan." },
    ["bloodstained_fortune_two_heads_are_better_than_one"] = { "Two heads are better than one! Then you'll always have a friend." },
    ["bloodstained_fortune_warning_the_giblet_was_not_safe"] = { "Warning: The giblet was not safe for human consumption." },
    ["bloodstained_fortune_when_all_else_fails_its_time"] = { "When all else fails, it's time to bail." },
    ["bloodstained_fortune_wisdom_comes_in_many_shapes_but"] = { "Wisdom comes in many shapes, but always flows from the crystals." },
    ["bloodstained_fortune_you_are_special_no_matter_what"] = { "You are special, no matter what your friends, relatives, associates, random strangers, or your conscience may tell you." },
    ["bloodstained_fortune_you_have_been_chosen_by_the"] = { "You have been chosen by the great metal hand in the sky! Now get to work." },
    ["bloodstained_fortune_you_need_not_fear_with_a"] = { "You need not fear with a head full of beer!" },
    ["bloodstained_fortune_you_will_make_an_enemy_today"] = { "You will make an enemy today, and promptly kill it." },
    ["bloodstained_fortune_you_will_meet_someone_special_tomorrow"] = { "You will meet someone special tomorrow, so remember: you draw more friends with kindness than clubbing them to death." },
    ["bloodstained_fortune_your_inclination_for_dancing_brings_a"] = { "Your inclination for dancing brings a smile to everyone's face." },
    ["crystallized_note_to_whom_it_may_concernbbif_you"] = { "To Whom It May Concern:$B$BIf you are reading this note, then you are in one of two places:$B$B(1) On the southern peninsula of Azshara.$B$B(2) Inside the belly of a Cliff Giant.$B$BBoth equally undesirable. $B$BIt should be noted that I was the former at one time and as of the writing of this letter, the latter.", "Being inside the belly of a giant gives one time for reflection. $B$BAs my body crystallizes, I have come to the conclusion that perhaps there are enough heroes in this world. Should I somehow make it out of this predicament I am going to ring that orc's ghostly neck!$B$B- Windan Shay" },
    ["crystallized_note_what_was_i_thinking_perhaps_a"] = { "What was I thinking? Perhaps a better question would be: What am I doing writing a note while I'm sitting captive inside the stomach of a giant? Both good questions that I have no immediate answer for... Admittedly, mine was not a mission of good will. I came in search of Azsharite, a unique crystal to southern Azshara. Oh the riches I would have had! Bah! Now look at me...", "Should any manner of intelligent life find this note, they must ask themselves something: \"Why in the hell are they romping around with violent thirty foot tall giants?\"\n\n- Mook" },
    ["danath_trollbane_danath_trollbane_militia_commander_of_stromgardetactical"] = { "Danath Trollbane\n\nMilitia Commander of Stromgarde.Tactical Advisor to General Turalyon, Force Commander of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.\n\nWe honor your memory, nephew, and your sacrifice. Since the founding of our glorious empire, the path to valor has always been drenched with the blood of heroes.\n\n- Thoras Trollbane, Lord of Stromgarde" },
    ["danath_trollbane_danath_trollbanebbmilitia_commander_of_stromgardetactical_advisor"] = { "Danath Trollbane$B$BMilitia Commander of Stromgarde.Tactical Advisor to General Turalyon, Force Commander of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.$B$BWe honor your memory, nephew, and your sacrifice. Since the founding of our glorious empire, the path to valor has always been drenched with the blood of heroes.$B$B- Thoras Trollbane, Lord of Stromgarde" },
    ["dark_keeper_nameplate_bethek_stormbrowbbbetheks_wanderings_take_him_deep"] = { "Bethek Stormbrow$B$BBethek's wanderings take him deep within Blackrock.  The secrets of the mountain beckon him.$B$BMay his spirit never falter." },
    ["dark_keeper_nameplate_ofgut_stonefist_those_fallen_before_dark"] = { "Ofgut Stonefist Those fallen before Dark Keeper Ofgut's hammer cannot be counted. The soldiers of the West Garrison bow in awe as he passes.  For who among them can look into the eyes of Ofgut and see the secrets the dark key whispers?" },
    ["dark_keeper_nameplate_pelver_deepstompbbdark_keeper_pelver_is_our"] = { "Pelver Deepstomp$B$BDark Keeper Pelver is our most honored disciple.  He has borne the key for longer than any, and it has cost him dearly.  When he is called for his burden, he is guarded in the Domicile.$B$BHis sacrifice is cherished, and he will remain in our hearts for many years... after the darkness takes him." },
    ["dark_keeper_nameplate_uggel_hammerhand_uggel_is_a_skilled"] = { "Uggel Hammerhand\n\nUggel is a skilled and solemn chiseler, and when not burdened with the dark key, his hands shape great works in the Hall of Crafting." },
    ["dark_keeper_nameplate_vorfalk_irongourdbbvorfalk_works_the_store_room"] = { "Vorfalk Irongourd$B$BVorfalk works the store room of the Grim Guzzler, and his sacrifice to the Dark Keepers runs deep.$B$BMay his spirit hold strong." },
    ["dark_keeper_nameplate_zimrel_darktoothbbwhen_the_madness_of_the"] = { "Zimrel Darktooth$B$BWhen the madness of the dark key takes hold of Zimrel, only the screams of the dying can soothe him.$B$BFor his sacrifice, he will always have a bench above the arena.  May our blood sports temper the rage in his heart." },
    ["decoded_twilight_text_for_immediate_dissemination_to_all_twilight"] = { "For immediate dissemination to all Twilight Hammer members.$B$BGiven the current state of affairs in Silithus, all distribution of True Believer texts are to be made under the escort of no less than four armed Twilight Hammer personnel.$B$BAny members found in violation of this new policy will be summarily punished.$B$B-Twilight Lord D'Sak" },
    ["decoded_twilight_text_for_immediate_dissemination_to_all_twilights"] = { "For immediate dissemination to all Twilight's Hammer members.$B$BThe search for the traitor, Ortell, is progressing at a most satisfactory pace.  Our scouts have narrowed his location to a network of caverns in Westfall.$B$BOrtell's betrayal shall not be forgiven and his escape presents a great security risk to our organization.$B$BAny individual found to be withholding information on Ortell's whereabouts will be duly punished.$B$B-Twilight Lord Everun", "Abyssal Templars$B$BAs an initiate you are permitted to establish contact with Abyssal Templars for routine rituals. Remember to always don the proper garb when utilizing wind stones to avoid activating our defensive enchantments.$B$BShould an unforeseen emergency arise with no overseers present, you are granted permission to summon an Abyssal Templar.$B$BFor details on the summoning rituals involved, refer to last month's True Believer.", "Abyssal Dukes$B$BOnly acolytes in possession of a medallion of station are permitted to establish contact with the  Abyssal Dukes. Medallions of station are only to be used by the individuals to whom they were originally issued.$B$BMembers of the Twilight's Hammer involved in unapproved communication with Abyssal Dukes or unauthorized use of medallions of station will be disciplined with by myself personally.", "The High Council of Abyssal Lords$B$BOnly Twilight Lords are permitted to contact Prince Skaldrenox, High Marshal Whirlaxis, Baron Kazum or Lord Skwol.$B$BUnder no circumstances are any low ranking members of the Twilight's Hammer allowed to initiate communication with the High Council.  Any outsiders found using a wind stone in this manner will be reduced to ashes on the spot." },
    ["decoded_twilight_text_how_do_we_know_they_love"] = { "How Do We Know They Love Us?$B$BSome may wonder how the Old Gods and their minions can love us. Do they not kill us? Do they not cause pain and suffering to all? How could beings so bent on malevolence know love in their hearts?$B$BThere is a simple answer to this question. So simple it need not be uttered?", "Faith. Faith is the wellspring from which the joy of servitude showers us. Faith will keep us warm on the coldest Silithus nights. Faith will keep us in our Lords' good graces when the Ending Days arrive.$B$BFaith will save us." },
    ["decoded_twilight_text_state_of_the_cult_volume_127bbit"] = { "State of the Cult, Volume 127$B$BIt is truly a happy day!  We have been tested in Silithus, and we have passed!$B$BReports of the destruction of our northernmost camp may challenge the hearts of the unfaithful, but this slaughter should not be seen as tragedy. No!", "The spilling of our blood by one of the Abyssal High Council is a blessing! We must envy our fallen comrades, for their spirits now reside in the belly of a most righteous beast!$B$BPraise to the Old Gods! Praise to their servants! Praise to the Twilight's Hammer!" },
    ["decoded_twilight_text_state_of_the_cult_volume_233bbopportunity"] = { "State of the Cult, Volume 233$B$BOpportunity knocks yet again, my brothers and sisters! The Cenarion Circle, a vile cult of nature lovers, now sends agents against us. They must want to stop us from summoning red luring stones. We cannot allow it!$B$BThe red stones are critical to our new allies. We mustn't let the Cenarion Circle's lapdogs succeed. Stand firm, my faithful friends. Stand firm!" },
    ["decoded_twilight_text_the_state_of_the_cult_volume"] = { "The State of the Cult, Volume 92$B$BIt is with a joyous heart that I greet you, my brethren, for the state of our cult could not be more grand. We are legion, and our goals grow ever closer to fruition.$B$BNew recruits continue to gather. The sing praise to our lords in Darkshore, they bow in jubilant reverie within the Searing Gorge, they embrace our masters' servant, Aku'mai, in Blackfathom Deeps. Indeed, my brothers and sisters, soon a swarm of the faithful will blanket all of Azeroth!" },
    ["diabolical_plans_diathorus_i_trust_that_this_letter"] = { "Diathorus,\n\nI trust that this letter will eventually make its way to you.  These demons are mindless.  All they think about is their nails, their whips or goring something with their head spikes.  And I dare not use one of the infernals lest it be burned to ashes!\n\nSadly, I long for the days when we could use the orcs.  At least they had half a brain and could follow orders.  Perhaps there is an opportunity to take some new thralls from nearby?", "The reports of the night elves assisting the draenei are true.  They're attempting to setup a new base of operations at Forest Song to the north near Satyrnaar.  We should confer on combining our forces for an attack before the next full moon of this pathetic world.  If we crush them now they will never gain a toehold on our doorstep!\n\nRegards,\n\nGorgannon\n\np.s. - Stop using up all of the blood ink on love letters to my lashers!  Night elf virgins are in short supply these days." },
    ["dorgar_stoenbrow_dorgar_stoenbrow_warrior_of_the_scarlet"] = { "Dorgar Stoenbrow\n\nWarrior of the Scarlet Crusade \n\nLord of the Red Caverns \n\nLast seen in the Mountains of Alterac" },
    ["dorgar_stoenbrow_dorgar_stoenbrowbwarrior_of_the_scarlet_crusadeblord"] = { "Dorgar Stoenbrow$BWarrior of the Scarlet Crusade$BLord of the Red Caverns$BLast seen in the Mountains of Alterac" },
    ["dusty_journal_leafing_through_the_books_crumbling_pages"] = { "Leafing through the book's crumbling pages reveals nothing more than descriptions of life on the Valgan farm. The changing of seasons, planting and harvesting of crops are noted, along with the births and deaths of children.$B$BThe entries end abruptly with a short description of the plague. None of the children described could have been old enough to complete training as a knight, if any survived the plague at all." },
    ["dusty_journal_the_first_half_of_the_journal"] = { "The first half of the journal seems to be nothing more than the ledger for Mr. Cooper's business. Handwritten columns of figures note the production and sale of barrels to the inhabitants of Moonbrook and even a few clients in Stormwind itself.$B$BThe back half of the book seems to have been Mr. Cooper's journal, where he discusses leaving the family business to his younger brother. You find no mention of children." },
    ["empires_fall_aside_from_their_shadowy_origins_it"] = { "Aside from their shadowy origins, it is clear that the night elves came to power soon after their discovery of the Well of Eternity. Despite the trolls' attempts to keep them from expanding their territories, the night elves built up a mighty empire that expanded rapidly across primordial Kalimdor. Wielding fierce magics never before imagined by the superstitious trolls, the night elves had little trouble doing what the evil aqir could never do: topple the two greatest empires in the world.", "The night elves systematically dismantled the troll's defenses and supply chains. The trolls, unable to counter the elves' destructive magics, buckled under the onslaught. The night elves proved to be every bit as cunning and bloodthirsty as the savage trolls -- incurring the latter race's eternal hatred and disdain. The Gurubashi and Amani empires fragmented within only a few short years.", "Eventually, the night elves were burned by the arcane fires they had sought to control. Their reckless use of magic had lured the demonic Burning Legion to the world. The demons crushed much of the night elves' civilization. Though there are no records to indicate that the Legion attacked either troll civilization, it is likely that battles took place across the breadth of the continent.", "At the end of this terrible conflict -- known as the War of the Ancients -- the Well of Eternity imploded. The resulting shockwave shattered the greater landmass of Kalimdor. The center of the continent was blasted beneath the sea, leaving only a small group of broken, single continents.", "Thus, great chunks of both the Amani and Gurubashi Empires still exist in the present day lands of Quel'Thalas and Stranglethorn (respectively). The Azj'Aqir kingdoms of Azjol-Nerub and Ahn'Qiraj have also survived in present day Northrend and Tanaris (respectively).   $B$BBoth troll civilizations recoiled from the vast destruction of the primordial world they had known. The dauntless trolls rebuilt their ravaged cities and set about to reclaim some of their former power." },
    ["etched_note_mighty_warriors_defend_our_home_our"] = { "Mighty warriors defend our home. Our shamans guide our spirits and show us our ancestors' past. And our druids help us discover the Earthmother's will.$B$BBut you are one of our hunters, and our hunters learn many aspects of those roles and blend them together. You will find you represent the heart of our people--some of our tribe will look to you for guidance, some for protection. It is my duty to ensure you are prepared for that. Seek me out in Camp Narache.$B$B-Lanka Farshot, Hunter Trainer" },
    ["etched_note_this_anvil_is_the_property_of"] = { "This anvil is the property of Jordan Stilwell - Please do NOT use!$B$B- Jordan" },
    ["fellari_swiftarrow_fellari_swiftarrow_ranger_captain_of_the"] = { "Fellari Swiftarrow\nRanger Captain of the Scarlet Crusade\nCitizen of Quel'Thalas\nLost in the forests of Silverpine" },
    ["fellari_swiftarrow_fellari_swiftarrowbranger_captain_of_the_scarlet"] = { "Fellari Swiftarrow$BRanger Captain of the Scarlet Crusade$BCitizen of Quel'Thalas$BLost in the forests of Silverpine" },
    ["ferren_marcus_ferren_marcus_high_abbot_of_the"] = { "Ferren Marcus\n\nHigh Abbot of the Scarlet Monastery \n\nCitizen of Stratholme \n\nKilled defending the Scarlet Monastery at the First Summertide Assault" },
    ["ferren_marcus_ferren_marcusbhigh_abbot_of_the_scarlet"] = { "Ferren Marcus$BHigh Abbot of the Scarlet Monastery$BCitizen of Stratholme$BKilled defending the Scarlet Monastery at the First Summertide Assault" },
    ["general_turalyon_general_turalyon_former_lieutenant_to_lord"] = { "General Turalyon\n\nFormer Lieutenant to Lord Anduin Lothar. Knight of the Silver Hand. High General of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.\n\nEsarus thar no'Darador' - By Blood and Honor We Serve.\nYou were the right hand of justice and virtue, old friend. Your name will be honored in our halls always.\n\n- Lord Uther the Lightbringer - Knight of the Silver Hand" },
    ["general_turalyon_general_turalyonbbformer_lieutenant_to_lord_anduin"] = { "General Turalyon$B$BFormer Lieutenant to Lord Anduin Lothar. Knight of the Silver Hand. High General of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.$B$BEsarus thar no'Darador' - By Blood and Honor We Serve.$BYou were the right hand of justice and virtue, old friend. Your name will be honored in our halls always.$B$B- Lord Uther the Lightbringer - Knight of the Silver Hand" },
    ["general_turalyon_htmlbody_brbr_h1_aligncentergeneral_turalyonh1_img"] = { "<HTML><BODY>\n<BR/><BR/>\n<H1 align=\"center\">General Turalyon</H1>\n<IMG src=\"Interface\\Common\\spacer\" align=\"center\" width=\"1\" height=\"27\"/>\n<P>\nNone sacrificed more than the High General. May we always walk in his path, so we, too, might safeguard the innocent as he did. By Blood and Honor We Serve.\n</P> \n</BODY></HTML>" },
    ["green_hills_of_stranglethorn_html_body_br_br_h1_aligncenter"] = { "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align=\"center\">\nTHE GREEN HILLS OF STRANGLETHORN\n</H1>\n<BR/>\n<H3 align=\"center\">\nby Hemet Nesingwary\n</H3>\n</BODY>\n</HTML>", "Our first day went as well as one can expect first days to go.  Most of our time was preoccupied with making the necessary arrangements to establish a base camp.  I located an ideal setting by a freshwater river inlet.  Judging by the old, abandoned docks nearby, this site was inhabited sometime ago.  As for the original inhabitants, only time can tell that tale.", "For this expedition I have assembled Ajeck Rouack and Sir S. J Erlgadin, along with my trusted servant, Barnil Stonepot.  I fought alongside Ajeck's father's side in many battles in defense of the Alliance.  Seeing her grown is quite special.  Her father schooled her well in the ways of weaponry.  Her skills with a bow make me wonder if there is elven blood running through those veins.", "Sir S. J. Erlgadin comes from human aristocracy.  His father, Count Erlgadin, was renowned for his generosity.  It was the Count who lobbied for improved working conditions for the Stonemasons' Guild during the restoration of Stormwind after the Second Great War.", "In the years that followed, after Stormwind betrayed the Stonemasons' Guild, Sir Erlgadin grew bitter about the role of the nobles within the Kingdom.  He no longer wished to uphold the position that his father's bloodline had earned for him in the House of Nobles.$B$BBut I digress.  The purpose of this story is not to act as a political treatise or a biography.  This is the account of my experiences hunting big game in the green hills of Stranglethorn....", "We rose with the sun.  Barnil began to prepare the morning meal. I noticed Ajeck's attention was somewhat distracted.  The day's trek would be long and our hunt would bring us close to danger.  A lack of focus could easily lead to an errant mishap.  Yet Ajeck seemed unable to divert her gaze from Barnil who stood by the edge of the river rinsing out his mess kit.", "Just as I was about to question Ajeck's lack of interest in the day's hunting strategy, she reached for her quiver, drew an arrow and unleashed a shot right towards poor Barnil.  But it was not Barnil that Ajeck was shooting at.  For when Barnil stepped aside, mouth agape, a large river crocilisk floated to the surface with Ajeck's arrow perfectly placed between his two large eyes.", "We set out toward the west, through the thick overgrowth of the tangled jungle.  Moving with slow, deliberate steps we paced through thick foliage in search of prey.  The morning passed in frustrated silence.  Nothing was stirring in the Vale, not even a breeze.  By the afternoon, the expedition had grown restless.  Barnil no longer strode with the cautious steps of a predator tracking prey.  Rather he clumsily clomped along the path often stepping noisily on dried leaves or fallen branches.", "During one such misstep, Erlgadin laid a heavy hand on Barnil's shoulder.  Ajeck and I gave a casual glance, assuming the man was simply giving Barnil a much-needed scolding for his carelessness.  Erlgadin, however, gestured slowly with his head toward a nearby fallen tree.  Gazing back at us were two piercing black eyes just above a mouthful of razor sharp fangs.", "The beast was a male Stranglethorn Tiger.  Before I could cock my rifle, Erlgadin raised his crossbow and fired upon the beast.  The bolt missed its mark and caught the beast heavily in the left flank.  The tiger made a futile attempt to flee but its wound was too grave.  The beast stumbled for a few tragic seconds until Barnil finished the kill with a thrown axe.", "The kill brought about a festive mood amongst the expedition.  Barnil poured mead for all to enjoy.  But our festivities were short-lived.  As we were preparing the corpse for transport back to base camp we were all caught off guard by a horrendous growl.  In all my years I have never heard anything so blood curdling.", "On a rocky precipice above, silhouetted by the setting sun, I could make out the largest cat of prey I have ever laid eyes upon.  I was able to loose one clumsy volley with my rifle, but the cat held his ground.  He growled once again, this time louder than the first, and vanished.$B$BWe gathered our belongings and headed solemnly back to camp.", "I had promised the expedition that we would spend the next day hunting panthers, as their furs are in high demand throughout Azeroth.  It only makes sense that such demand should exist with all of the able-bodied hunters, trappers and fur-traders off giving their lives so valiantly in the name of the Alliance.", "Ajeck and Sir Erlgadin were anxious to learn how to hunt effectively with a Dwarven Rifle.  I had the two humans leave their primitive range weapons at base camp.  Barnil and I outfitted them with some of Ironforge's finest firearms.", "On this day we ventured to the south, following some fresh panther tracks.  Soon we reached a ravine spanned by a tremendous rope bridge.  I could not help but to think of Brann's descriptive writings of this region when I saw the engineering marvel.  So often it was assumed that the native Trolls were a primitive and uneducated race yet as I gazed upon the master craftsmanship of the bridge I was able to recognize the skill with which the Troll builders overcame the seemingly impossible feat.", "Before long, Ajeck tracked the panther to the southwest.  We walked quietly, guns at the ready, in anticipation of our prey.  A snapping of twigs from a nearby copse of trees drew our attention immediately.  Something was in there.  One stern glance at Barnil was enough to convey my thoughts.  Barnil slowly lowered his rifle.  This kill was not for us; it was for our Human companions.  Countless panthers had lost their lives in front of our smoking barrels.  This kill would be for the Humans.", "Both Ajeck and Sir Erlgadin stood poised, guns leveled at the bristling overgrowth at the base of the swaying trees.  The midday sun beat heavily upon us.  A slow trickle of perspiration trailed down from Elrgadin's temple as he pulled the pin back.  Upon the sound of the click, the thick flora parted and a large black panther -- a beautiful specimen -- darted out onto the plain.", "The Humans trained their sights on the panther as it ran along the edge of the tree line.  The barrels of their guns moved in perfect parallel tandem.  Barnil gave me an urging glance but I shook my head no.  This hunt was for the Humans, not Barnil or me.  Erlgadin fired a booming shot, missing the panther altogether.  Apparently he was unprepared for the violent kickback of the rifle blast.", "His gun tossed back violently in his arms.  The barrel swooped sideways and came up beneath Ajeck's rifle.  Ajeck had chosen that exact moment to pull her trigger.  The rifle, the aim now knocked clumsily toward the tree line, went off with a distinct boom.  A flock of birds screamed out of the canopy, scattering in every direction.  A plume of smoke rose from the tree.  We watched in awe as a tremendous branch fell squarely on the fleeing panther, breaking its back", "As the weeks passed our stockpile of panther and tiger skins grew immense.  I decided it was time for the expedition to shift our focus to a new challenge: Raptors.$B$BThe Humans, while appreciative of the training Barnil and I offered, decided to refrain from hunting with firearms.  Ajeck was much more comfortable with a finely strung bow and Sir Erlgadin never left camp without his sturdy crossbow.", "We set out at first light, heading south past the Tkashi Ruins.  Barnil voiced concern that we might encounter members of the Bloodscalp Tribe.  I reminded Barnil that the Bloodscalps were more concerned with destroying their tribal enemy, the Skullsplitters.  Needless to say, Barnil was not comforted in the least.  I, however, had a loaded rifle, a satchel full of gunpowder and three deadly hunters with me to ease any concerns of an unfriendly ambush.", "I've stood before a towering Infernal on the battlefield, the army of the Burning Legion advancing from all directions.  An unruly band of Trolls seems as harmless as a jackrabbit in the hills of Dun Morogh.$B$BWe passed the Tkashi Ruins without event, much to Barnil's relief.  The party proceeded to head westward, toward the Great Sea, skirting the Ruins of Zul'Kunda just to the south.  As we ascended the high sea bluffs we spotted our first Raptor.", "The beast never so much as detected our presence.  In fact, the only greeting he received from the expedition was a bullet between the eyes.$B$BSir Erlgadin let out a hearty *hurrah* as Ajeck nodded toward me with keen approval.  I sifted through my pack in search of my pipe, hoping to enjoy a celebratory smoke.  Barnil began to scurry up the hillside to retrieve the Raptor's corpse.  I stared at the fallen beast with the satisfaction that accompanies every big kill.", "But I could not bask in the glory of the kill for long.  For when I turned my eyes toward the horizon, several silhouettes appeared cresting the hill, just above poor Barnil.$B$B*Flee, Barnil!* I shouted.  Ajeck, Sir Erlgadin and myself loosed a volley of bullets, arrows and bolts over Barnil and toward the pursuing raptors.  One of us landed a kill amidst the confusion.", "Our hastily aimed shots were enough to buy Barnil's escape.  Barnil clamored back down the hill and rejoined the party. We scurried off into the jungle; a pack of ferocious Lashtail Raptors stalking our every move.  $B$BThe hunters were now the hunted.", "I led the party toward the sea, hoping the shoreline would provide refuge from the Raptors.  In our haste we had drifted too far north, to a precariously high elevation.  The mistake was made.  The fault was mine.  We stopped just short of a sheer cliff, the Raptors just a few paces behind.", "I stepped slowly forward, gun raised.  I had led these brave hunters to their death.  I would die defending them.  Lashtail Raptors are particularly fierce, known for their unrelenting blood-thirst.  They far outnumbered us.  But I would be damned if I let them kill me and my comrades without shedding some of their own blood first.", "Ajeck and Sir Erlgadin readied their weapons, flanking me on either side, our backs to the sea.  Barnil let out a defeated sigh and drew his axe.  The Lashtails were almost upon us.  Their steady stride had slowed.  They were stalking their prey now for they knew they had us trapped.", "And then something miraculous happened.  From off to our side we heard the distinct and terrifying roar of the great white tiger.  Despite their numbers, the Raptors turned and scattered in all directions.  We saw but a brief white flash as the tiger darted past us and pounced on one of the Raptors.  No command needed to be given.  All four members of our party knew it was time to run.", "We sprinted all the way back to base camp, never slowing.  Later that night we sat quietly around the campfire, knowing our lives had been saved by a bizarre twist of fate.  Such are the risks of the big game hunter.  We toy with fate by delivering it.  Yet each of us, at some point, will face fate's razor sharp teeth.  This Dwarf is just glad that moment did not come upon the green hills of Stranglethorn.$B$B--The End--" },
    ["green_hills_of_stranglethorn_the_green_hills_of_stranglethornbb_by"] = { "The Green Hills Of Stranglethorn$b$b              By Hemet Nesingwary", "Our first day went as well as one can expect first days to go. Most of our time was preoccupied with making the necessary arrangements to establish a base camp. I located an ideal setting by a freshwater river inlet. Judging by the old, abandoned docks nearby, this site was inhabited sometime ago. As for the original inhabitants, only time can tell that tale.", "For this expedition I have assembled Ajeck Rouack and Sir S. J. Erlgadin, along with my trusted servant, Barnil Stonepot. I fought alongside Ajeck's father's side in many battles in defense of the Alliance. Seeing her grown is quite special. Her father schooled her well in the ways of weaponry. Her skills with a bow makes me wonder if there is elven blood running through those veins.", "Sir S. J. Erlgadin comes from human aristocracy. His father, Count Erlgadin, was renowned for his generosity. It was the Count who lobbied for improved working conditions for the Stonemasons' Guild during the restoration of Stormwind after the second Great War.", "In the years that followed, after Stormwind betrayed the Stonemasons' Guild, Sir Erlgadin grew bitter about the role of the nobles within the Kingdom. He no longer wished to uphold the position that his father's bloodline had earned for him in the House of Nobles.$b$bBut I digress. The purpose of this story is not to act as a political treatise or a biography. This is the account of my experiences hunting big game in the green hills of Stranglethorn...", "We rose with the sun. Barnil began to prepare the morning meal. I noticed Ajeck's attention was somewhat distracted. The day's trek would be long and our hunt would bring us close to danger. A lack of focus could easily lead to an errant mishap. Yet Ajeck seemed unable to divert her gaze from Barnil who stood by the edge of the river rinsing out his mess kit.", "Just as I was about to question Ajeck's lack of interest in the day's hunting strategy, she reached for her quiver, drew an arrow and unleashed a shot right towards poor Barnil. But it was not Barnil that Ajeck was shooting at,. For when Barnil stepped aside, mouth agape, a large river crocolisk floated to the surface with Ajeck's arrow perfectly placed between his two large eyes.", "We set out towards the west, through the thick overgrowth of the tangled jungle. Moving with slow, deliberate steps we paced through thick foliage in the search of prey. The morning passed in frustrated silence. Nothing was stirring in the Vale, not even a breeze. By the afternoon, the expedition had grown restless. Barnil no longer strode with the cautious steps of a predator tracking prey. Rather he clumsily clomped along the path often stepping noisily on dried leaves or fallen branches.", "During one such misstep, Erlgadin laid a heavy hand on Barnil's shoulder. Ajeck and I gave a casual glance, assuming the man was simply giving Barnil a much-needed scolding for his carelessness. Erlgadin, however, gestured slowly with his head toward a nearby fallen tree. Gazing back at us were two piercing black eyes just as above a mouthful of razor sharp fangs.", "The beast was a male Stranglethorn Tiger. Before I could cock my rifle, Erlgadin raised his crossbow and fired upon the beast. The bolt missed its mark and caught the beast heavily in the left flank. The tiger made a futile attempt to flee but its wound was too grave. The beast stumbled for a few tragic seconds until Barnil finished the kill with a thrown axe.", "The kill brought about a festive mood amongst the expedition. Barnil poured mead for all to enjoy. But our festivities were short-lived. As we were preparing the corpse for transport back to base camp we were all caught off guard by a horrendous growl. In all my years I have never heard anything so blood curdling.", "On a rocky precipice above, silhouetted by the setting sun, I could make out the largest cat of prey I have ever laid eyes upon. I was able to loose one clumsy volley with my rifle, but the cat held his ground. He growled once again, this time louder than the first, and vanished.$b$bWe gathered our belongings and headed solemnly back to camp.", "I had promised the expedition that we would spend the next day hunting panthers, as their furs are in high demand throughout Azeroth. it only makes sense that such demand should exist with all of the able-bodied hunters, trappers and fur-traders off giving their lives so valiantly in the name of the Alliance.", "Ajeck and Sir Erlgadin were anxious to learn how to hunt effectively with a Dwarven Rifle. I had the two humans leave their primitive range weapons at base camp. Barnil and I outfitted them with some of Ironforge's finest firearms.", "On this day we ventured to the south, following some fresh panther tracks. Soon we reached a ravine spanned by a tremendous rope bridge. I could not help but to think of Brann's descriptive writings of this region when I saw the engineering marvel. So often it was assumed that the native Trolls were a primitive and uneducated race yet as I gazed upon the master craftsmanship of the bridge I was able to recognize the skill with which the Troll builders overcame the seemingly impossible feat.", "Before long, Ajeck tracked the panther to the southwest. We walked quietly, guns at the ready, in anticipation of our prey. A snapping of twigs from a nearby copse of trees drew our attention immediately. Something was in there. One stern glance at Barnil was enough to convey my thoughts. Barnil slowly lowered his rifle. This kill was not for us, it was for our Human companions. Countless panthers had lost their lives in front of our smoking barrels. This kill would be for the Humans.", "Both Ajeck and Sir Erlgadin stood poised, guns leveled at the bristling overgrowth at the base of the swaying trees. The midday sun beat heavily upon us. A slow trickle of perspiration trailed down from Erlgadin's temple as he pulled the pin back. Upon the sound of the click, the thick flora parted and a large black panther -- a beautiful specimen -- darted out onto the plain.", "The Humans trained their sights on the panther as it ran along the edge of the tree line. The barrels of their guns moved in perfect parallel tandem. Barnil gave me an urging glance but I shook my head no. This hunt was for the Humans, not Barnil or me. Erlgadin fired a booming shot, missing the panther altogether. Apparently he was unprepared for the violent kickback of the rifle blast.", "His gun tossed back violently in his arms. The barrel swooped sideways and came up beneath Ajeck's rifle. Ajeck had chosen that exact moment to pull her trigger. The rifle, the aim now knocked clumsily toward the tree line, went off with a distinct boom. A flock of birds screamed out the canopy, scattering in every direction. A plume of smoke rose from the tree. We watched in awe as a tremendous branch fell squarely on the fleeing panther, breaking its back.", "As the weeks passed our stockpile of panther and tiger skins grew immense. I decided it was time for the expedition to shift our focus to a new challenge: Raptors.$b$bThe Humans, while appreciative of the training Barnil and I offered, decided to refrain from hunting with firearms. Ajeck was much more comfortable with a finely strung bow and Sir Erlgadin never left camp without his sturdy crossbow.", "We set out at first light, heading south past the Tkashi Ruins. Barnil voiced concern that we might encounter members of the Bloodscalp Tribe. I reminded Barnil that the Bloodscalps were more concerned with destroying their tribal enemy, the Skullsplitters. Needless to say, Barnil was not comforted in the least. I, however, had a loaded rifle, a satchel full of gunpowder and three deadly hunters with me to ease any concerns of an unfriendly ambush.", "I've stood before a towering Infernal on the battlefield, the army of the Burning Legion advancing from all directions. An unruly band of Trolls seems as harmless as a jackrabbit in the hills of Dun Morogh.$b$bWe passed the Tkashi Ruins without event, much to Barnil's relief. The party proceeded to head westward, toward the Great Sea, skirting the Ruins of Zul'Kunda just to the south. As we ascended the high sea bluffs we spotted our first Raptor.", "The beast never so much as detected our presence. In fact, the only greeting he received from the expedition was a bullet between the eyes.$b$bSir Erlgadin let out a hearty *hurrah* as Ajeck nodded toward me with keen approval. I sifted through my pack in search of my pipe, hoping to enjoy a celebratory smoke. Barnil began to scurry up the hillside to retrieve the Raptor's corpse. I stared at the fallen beast with the satisfaction that accompanies every big kill.", "But I could not bask in for the glory of the kill for long. For when I turned my eyes toward the horizon, several silhouettes appeared cresting the hill, just above poor Barnil.$b$b*Flee, Barnil!* I shouted. Ajeck, Sir Erlgadin and myself loosed a volley of bullets, arrows and bolts over Barnil and toward the pursuing raptors. One of us landed a kill amidst the confusion.", "Our hastily aimed shots were enough to buy Barnil's escape. Barnil clamored back down the hill and rejoined the party. We scurried off into the jungle; a pack of ferocious Lashtail Raptors stalking our every move.$b$bThe hunters were now hunted.", "I led the party toward the sea, hoping the shoreline would provide refuge from the Raptors.  In our haste we had drifted too far north, to a precariously high elevation.  The mistake was made.  The fault was mine.  We stopped just short of a sheer cliff, the Raptors just a few paces behind.", "I stepped slowly forward, gun raised.  I had led these brave hunters to their death.  I would die defending them.  Lashtail Raptors are particularly fierce, known for their unrelenting blood-thirst.  They far outnumbered us.  But I would be damned if I let them kill me and my comrades without shedding some of their own blood first.", "Ajeck and Sir Erlgadin readied their weapons, flanking me on either side, our backs to the sea.  Barnil let out a defeated sigh and drew his axe.  The Lashtails were almost upon us.  Their steady stride had slowed.  They were stalking their prey now for they knew they had us trapped.", "And then something miraculous happened.  From off to our side we heard the distinct and terrifying roar of the great white tiger.  Despite their numbers, the Raptors turned and scattered in all directions.  We saw but a brief white flash as the tiger darted past us and pounced on one of the Raptors.  No command needed to be given.  All four members of our party knew it was time to run.", "We sprinted all the way back to base camp, never slowing.  Later that night we sat quietly around the campfire, knowing our lives had been saved by a bizarre twist of fate.  Such are the risks of the big game hunter.  We toy with fate by delivering it.  Yet each of us, at some point, will face fate's razor sharp teeth.  This Dwarf is just glad that moment did not come upon the green hills of Stranglethorn." },
    ["haipu_a_slicky_in_handbbis_worth_two"] = { "A slicky in hand$b$bIs worth two in the dooker$b$bSo says Chief Ee Ee!" },
    ["haipu_beware_the_jinyubbthey_are_a_bunch"] = { "Beware the jinyu$b$bThey are a bunch of dookers$b$bOok'em in the jerb." },
    ["harthal_truesight_fellari_swiftarrow_ranger_captain_of_the"] = { "Fellari Swiftarrow Ranger Captain of the Scarlet Crusade Citizen of Quel'Thalas Lost in the forests of Silverpine" },
    ["harthal_truesight_harthal_truesightblord_paladin_of_the_scarlet"] = { "Harthal Truesight$BLord Paladin of the Scarlet Crusade$BCitizen of Azeroth - Knight of the Silver Hand$BLast seen entering the cursed city of Stratholme" },
    ["here_lies_king_terenas_menethil_ii_here_lies_king_terenas_menethil_ii"] = { "Here lies King Terenas Menethil II -- Last True King of Lordaeron.$B$BGreat were his deeds -- long was his reign -- unthinkable was his death. $B$B         \"May the Father lie blameless for the deeds of the son. $B          May the bloodied crown stay lost and forgotten.\"$B" },
    ["holia_sunshield_holia_sunshield_defender_of_the_scarlet"] = { "Holia Sunshield\nDefender of the Scarlet Crusade\nKilled while slaying the Dreadlord Beltheris" },
    ["holia_sunshield_holia_sunshieldbdefender_of_the_scarlet_crusadebkilled"] = { "Holia Sunshield$BDefender of the Scarlet Crusade$BKilled while slaying the Dreadlord Beltheris" },
    ["horatio_montgomery_md_html_body_br_br_p_in"] = { "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\nIn memory of my dear mentor, Horatio M. Montgomery, M.D. Healer, Teacher, Friend.\n</P>\n<BR/>\n<H1 align=\"center\">\n50 BTFT - 25 ATFT\n</H1>\n<BR/>\n<P>\n\"The world is full of the sick and weary. It is our job, as healers, NAY, as men and women of medicine, to cleanse them ALL of the 'itis.'\"\n</P>\n<BR/>\n<P>\n- H.M.M., M.D., PhD, JD, Grandmaster Farmer, Dancer Extraordinaire, Friend to the Animals\n</P>\n<BR/>\n</BODY>\n</HTML>" },
    ["invar_onearm_invar_onearm_the_first_chief_assassin"] = { "Invar One-Arm\nThe first Chief Assassin of the Scarlet Crusade \nCitizen of Dalaran\nLast seen on the shores of Northrend" },
    ["invar_onearm_invar_onearmbthe_first_chief_assassin_of"] = { "Invar One-Arm$BThe first Chief Assassin of the Scarlet Crusade$BCitizen of Dalaran$BLast seen on the shores of Northrend" },
    ["item_a_bloodstained_envelope"] = { "My Emily, A few short days ago, we broke camp in this Light-forsaken place, operating under the King's orders to return home. My heart was light despite my bleak surroundings, for I knew that after the frigid trek to the shore and long, grueling voyage, I would find solace in your arms. We reached the shoreline today to find our ships, our means of return, nothing more than charred husks; we cannot leave, and have no choice but to press on into the heart of this abysmal wasteland. I have gone to the very end of the world to keep you safe, Emily... and now... I wish with all my being that I had remained in Lordaeron with you. Thoughts of you fill my every waking moment. You are my warmth in this frozen land, beloved, and no one can take that from me. Maxwell" },
    ["item_a_bloodstained_journal_page"] = { ". . .downward spiral of despair. First she mocks me and now she is engaged. The ungracious charlatan was pretending to love when truly she desired to hurt me all along. A black void lurks with in me now and it grows with each waking moment. The blood I shall spill pales in comparison to the tears I have shed. . ." },
    ["item_a_careworn_note"] = { "Dearest Amelia, Tonight I have seen things that will haunt me to the end of time. Stratholme is aflame... and we are responsible. Our Prince led us into the streets of the city tonight; he ordered us to break into the homes of the townspeople and... kill them in their sleep. They were plagued, claimed Lord Arthas, and had to be killed before they killed us. It was a slaughter. Hundreds died silently to the swords of those sworn to protect them. I could stand it no longer; I fled. Deserter I may be, but I could not commit such atrocities. In every home I could not help but see your face, or those of our children, upon the victims as they died. If standing against that means being a traitor, then so be it. I hope to find my way back to you in time, but the roads are unsafe. Give our children my love in my absence. James" },
    ["item_a_clue_to_sanders_treasure"] = { "Good work, matey! Now ye need to head due east. East up the bluffs, east to the road. Look for the ol' chimney ruins near the side of the road. There you'll find an old barrel with your next clue." },
    ["item_a_crumpled_missive"] = { "Heliana, I, Vargus, yet live, despite your wishes to the contrary. I despise traipsing about the countryside in this ridiculous armor. Our latest orders have us heading towards Andorhal after grain or some such nonsense. Why should I care about the food stores in Andorhal, of all places? This entire notion of being in the army is ludicrous. Rest assured, Aunt Heliana, that I will return for your inheritance; even if I become sorely wounded and am left without food, pure spite will drive me ever onward. Vargus" },
    ["item_a_dusty_unsent_letter"] = { "To the Honorable Headmaster Crillian,\n\nMy former Master, I write to you so that you might know what your apprentice has been doing of late. Paying heed to your advice, I sought to build my knowledge and wisdom through travel outside the gates of our beloved Stormwind. My journeys took me to many places but I have decided to take up residence here in the lovely town of Moonbrook. The surrounding fields of Westfall are most beautiful as the harvest approaches.", "Within just a few days of my visit I found myself tutoring the local children from the nearby farmlands. The lessons went so well that the town mayor commissioned me to run a school and construction has begun on a brand new schoolhouse! From Silverpine to Stormwind and now Moonbrook -- who would have guessed I would see so much of Azeroth!\n\nWarm regards,\n\nStalvan Mistmantle" },
    ["item_a_faded_journal_page"] = { ". . .most strange and uncontrollable feeling. Never have I felt the way I did today. Whilst assisting Giles with his history lesson, Tilloa was outside tending to the flower garden. After a few minutes she came inside and placed a scarlet begonia in my open palm and smiled at me in such a way that my heart felt as though it was trembling within my chest. . . ." },
    ["item_a_history_of_the_veiled_stair"] = { "Winding like a snake between the fertile lowlands of the Valley of Four Winds and the rolling steppes of Kun-Lai Summit, the Veiled Stair is truly a pandaren wonder.$b$bIt was hand-chiseled by pandaren slaves during the third mogu dynasty. To the best of our knowledge, this means the steps are over twelve thousand years old!$b$bThe grummles believe that it is very lucky for travellers to count the steps as they ascend. This may be true; but nobody has ever been able to agree on a definitive count.$b$bHow many do YOU see?" },
    ["item_a_letter_to_grelin_whitebeard"] = { "Grelin,\n\nMy time is short and many matters press on my time, and I hope that your investigation of the trolls will not be one of them. Therefore I will allow you to use my authority in dealing with the trolls in whatever fashion you deem necessary, more so if you are able to find an expedient solution.\n\nMagni Bronzebeard" },
    ["item_a_most_famous_bill_of_sale"] = { "On this site many generations ago stood Shen-zin's Sundries, a supplier well-liked by the local farmers. One day the first Pandaren explorer, Liu Lang, walked into the store with a most unusual shopping list, records of which have survived to this day:$b$b     One lantern$b     Three liters lamp oil$b     Four packages of dehydrated fruit$b     Two sacks of dried peas$b     Four haunches of salt pork$b     Twelve liters of fresh water$b     One basket of hardtack$b     One compass$b     One spyglass$b$bLiu Lang announced his intention to explore the world. Shen-Zin, humoring his client, suggested that Liu Lang should also bring an umbrella. He generously offered one for free.$b$bBeaming, a grateful Liu Lang told Shen-Zin, \"I shall name my sea turtle after you!\" He happily carted away his supplies, whistling as he headed toward the beach, trailed by dozens of curious onlookers." },
    ["item_a_mysterious_message"] = { "Blacknails--\n\nThe Sea awaits us. We need your supplies from the North. Strip everything: every railroad pike, every waterbucket. We need metal. A shipment is due from BB but long overdue. Come through for me, Blacknails. Send your supplies directly to the \"barn\" this time. No time to squander.\n\n--VanCleef" },
    ["item_a_proclamation_from_sire_denathrius"] = { "To the good people of Revendreth...\n\nIt is with optimism that I address you today... though these are challenging times.\n\nFirstly, I assure you that our holy mission to help the most violent and wicked souls atone for their sins, is and always will be, our utmost priority.\n\nOur rituals are effective -- our judgment, keen but fair. We venthyr remain committed to bringing eventual redemption to all who desire it. It is through your faithful work that even the most evil and prideful beings may ultimately be spared an eternity in the Maw.", "Unfortunately, of late the flow of such hubris-ridden souls has virtually ceased.  And as a result, Anima, our most precious resource, is in dwindling supply. \n\nEven we, the faithful who extract the anima, have not been spared the effects of this mysterious drought.\n\nYes, we still have our \"Old Reliables\" - our workhorses.  Yet I fear they will not be enough. \n\nWe are doing everything in our power to gather more anima, but - simply put, we must all - rich and poor alike - make sacrifices for the greater good.", "Therefore, I have decided to implement a strategy of conservation and rationing, which should keep the anima flowing to those most in need.  \n\nIn this manner, we will keep our people strong and our land healthy - despite the efforts of those who would use this crisis to further their own ends... \n\n... and rebel against the rightful structures of our society.", "Rest assured, we shall bring these miscreants to justice - with fairness and mercy, of course. I am, after all, nothing if not compassionate.\n\nMy loyal subjects, we are doing all that can be done to stimulate Anima production and fulfill Revendreth's honorable purpose. Remain devout and resolute - \n\n- and know that I will lead us all to a brighter future." },
    ["item_a_ragged_page"] = { "Samla, As we follow our Lord Arthas north, ever north, my heart grows heavy. While he once shined with the Light, I now sense a darkening of the young paladin's spirit. His zeal is shadowed by a brooding, over some nightmare in his soul that I cannot divine... We will soon make landfall in the frozen wastes. Although many of his men grow sick from the chill and from battles against putrid beasts, Arthas tells us that what he seeks in the ice will turn the tide of battle. But I took no comfort from his words, for after he said them... the grim smile planted on his curled lips chilled me deeper than any blizzard could. Pray for us, Samla, and pray for our world, Torgal" },
    ["item_a_short_note"] = { "Curgle,\n\nI have been eagerly awaiting your newest invention. I can't wait to begin using it to document my studies.\n\nPlease entrust it to my messenger.\n\nWith kindest regards,\n\nDaryn Lightwind" },
    ["item_a_smudged_document"] = { "Dear Pamela, Tomorrow we make our stand in Andorhal, and I fear this will be my last letter to you, my love. The undead are unfatigued and we, I fear, are only human. We cannot hold against them. But fret not, for although we are sure to perish, our hope stays strong. The Light will prevail! And, my dearest, I take comfort knowing that, as those dark terrors storm our walls and crash over us, my last thoughts will not be of death. I will think of you in my arms, and I will know peace at last. Christoph" },
    ["item_a_steamy_romance_novel"] = { "As Nahni glided up, the grizzled warrior gave her a hard stare.  \"I suppose you're here to collect the reward for killing those murlocs?\"$B$BHer eyes wandered down to the glowing broadsword at his side.  \"That depends on what the reward is, Marcus.\"  She twirled her hair playfully, pretending not to notice how he shifted uncomfortably in her presence.  \"I may not want it.\"", "Marcus stepped toward her, bristling with a mixture of fear and anger. \"The reward is not negotiable!\"  He paused for a moment while gathering his nerve, and pressed himself against her diminutive form.  Their lips met hotly, melting her frost armor spell in a torrent of sweltering vapor.$B$B\"So, is there another step to this quest?\" she teased, her eyes glittering with excitement.$B$B<This goes on for several hundred more pages, without advancing the plot.>" },
    ["item_a_steamy_romance_novel_blue_moon"] = { "Tail swooshing and hips swaying, the curvy figure walked purposefully across the lake toward the man resting by the shore; rising quickly as she approached, he appeared visibly happy to be in her presence.  Blue arms flowed over his shoulders as a smooth tail coiled seductively around his waist.  \"Why must I travel so far to be meeting man like you?\"  Her voice carried a strong, alluring accent.$B$BGrinning wildly, he gently pushed her away, openly staring as the light caught her features.$B$B\"Up here!\", she exclaimed in playful anger.$B$BWith a helpless shrug, he reached into his pack and pulled out a small pouch.  \"My wonderful Soola, I've brought you something.\"  Confidence wrapped his words like a steel blanket." },
    ["item_a_steamy_romance_novel_forbidden_love"] = { "Ah'tusa crept silently through the massive underground tunnel, nervously looking over her shoulder in anticipation of the fast moving tram.  \"Where is he...\" she muttered angrily, stopping suddenly as something moved behind her.  Her eyes narrowed dangerously as her dagger slid from its sheath.\n\nA husky voice echoed in the hollow chamber, \"I thought rogues liked to be behind their target.\"  She spun quickly, driving her blade into a shield of impenetrable force.  \"And I thought paladins were supposed to be chaste.\" she replied with a confident smirk.", "Leaning forward, she counted out loud until the invisible bubble dissipated with an audible pop.  \"Twelve seconds?  I know you have abilities that last longer than that.\"\n\nBony fingers worked effortlessly beneath his armor, unlatching his breastplate and exposing him to the cold air.  \"Don't worry my sweet Marcus, that's not a finishing move tonight... I'm just getting started.\"  He wrapped his arms around what remained of her waist, forcing an excited giggle as he nibbled at her neck vertebrae.\n\n<The rest of the book has several sections that are apparently worn out from repeated readings.>" },
    ["item_a_steamy_romance_novel_northern_exposure"] = { "The tiny gnome peered over the railing into the secluded Dalaran courtyard.$B$B\"The view from the balcony is amazing.  You have to come see!\"$B$BArmor legplates creaked as Marcus walked over, taking in a deep breath as he absently scratched his scruffy chin.$B$B\"The Hero's Welcome is no slouch.  And there's something in the room that might interest you.\"$B$BTavi bounded into the room, pausing only a moment before jumping onto the massive bed.  She turned to gaze at Marcus with her huge saucer-like eyes, narrowing them playfully and replacing her glowing smile with a diabolical grin.", "\"Interested in some more company?\" she purred as her hands weaved through a complex summoning ritual, stopping only when she felt the warmth of a new presence behind her.$B$BAll color drained from Marcus's face as he struggled to protest.  \"I... I don't think that's appropriate.\"$B$BConfused, Tavi turned to see what was wrong.  A hideous fel hound stood ready, drooling onto the floor as it stared intently at the half-armored paladin.$B$B\"No!  No that's not what I meant.\" she stammered as she dispelled the hungry demon.  \"I'm sorry, that's not really my specialization....\"", "Marcus took both her hands in one of his as he reassured her, \"It's fine.  What is your specialization?\"$B$BHer head snapped up, eyes burning with renewed life as shadowy energy channeled through her hands into Marcus, dropping him to his knees in agony.$B$B\"Affliction, actually.\"$B", "Gritting his teeth, Marcus gestured as light flashed over him, restoring his strength.$B$BTavi stared anxiously as he rose to his full height, engulfing her in his shadow.  He thrust his hand forward, sending a wave of righteous force through her.  Eyes rolled back as she wavered for several seconds before regaining consciousness.$B$B\"I've recently taken the path of... retribution.\"$B$BThe mischievous smirk returned to her face, \"Well then, this is going to be fun.\"$B$B<The remaining pages have a level 99 requirement to read.>" },
    ["item_a_torn_journal_page"] = { ". . .Giles, the boy, seems a bit rambunctious and will be a challenge to educate. However the elder daughter, Tilloa, seems exceptionally smart. I couldn't help but to notice her captivating beauty as well. She is on the cusp of womanhood now. Supposedly the Lord has arranged her marriage for next year. But I digress. This week I will accompany the family to their summer cottage near the Eastvale Logging Camp in Elwynn, close to the Red Ridge Mountains. I hope to write more while there." },
    ["item_a_torn_letter"] = { "Reuben, I write this letter knowing you may never see it; I simply can't remain idle, listening to the constant pounding against the Hearthglen walls. The undead are outside our village, unceasing in their assault, and we have been charged with defending the townsfolk until reinforcements arrive. My leg was broken in the last charge, and so I sit, useless, with my sword at my side should there be a breach in our defenses. There is no idle banter... only the sounds of fighting and death. The air is thick with fear. Prince Arthas is here, fighting on the front lines with the men. Were he not present we would have fallen long ago. His love for this land and its people is infectious; I gladly serve under him, and will to the end of my days. The fighting grows more intense; broken leg or not, I cannot sit here. Every sword is needed. I hope these words find you in happier times. Your friend, Leagrem" },
    ["item_a_treatise_on_military_ranks"] = { "A TREATISE ON MILITARY RANKS\n\nWhat follows are\n\nthe military ranks\n\nof the Alliance,\n\nproceeded by such\n\ninformation as is\n\nknown for the races\n\nof the Horde. Each\n\nis presented in two\n\nsections, the officers and then the enlisted, with the ranks of each listed in descending order from highest to lowest. Long live the Alliance!", "OFFICER RANKS OF THE ALLIANCE\n\nPart 1\n\nGrand Marshal\n\nField Marshal\n\nMarshal\n\nCommander\n\nLieutenant Commander", "OFFICER RANKS OF THE ALLIANCE\n\nPart 2\n\nKnight-Champion\n\nKnight-Captain\n\nKnight-Lieutenant\n\nKnight", "ENLISTED RANKS OF THE ALLIANCE\n\nSergeant Major\n\nMaster Sergeant\n\nSergeant\n\nCorporal\n\nPrivate", "OFFICER RANKS OF THE HORDE\n\nPart 1\n\nHigh Warlord\n\nWarlord\n\nGeneral\n\nLieutenant General\n\nChampion", "OFFICER RANKS OF THE HORDE\n\nPart 2\n\nCenturion\n\nLegionnaire\n\nBlood Guard\n\nStone Guard", "ENLISTED RANKS OF THE HORDE\n\nFirst Sergeant\n\nSenior Sergeant\n\nSergeant\n\nGrunt\n\nScout" },
    ["item_a_zombies_guide_to_proper_nutrition"] = { "Brrrraaaaaiiins. Braaaaaaaaaaaaaiiiiiiiinnnnnnnnns. BRRRRAAAAIIIIIIIIINNNSS!!!$B$B<This goes on for forty more pages.>" },
    ["item_abandoned_tablet"] = { "CURSE THE AMANI\nCURSE THE PRIESTS\nCURSE THE WARRIORS\nWE ARE ABANDONED\n\nTHE MASONS THE LABORERS\nWE ARE THE SACRIFICE\nTO ENSURE AMANI SAFETY\nWE ARE ABANDONED TO THE MIST\n\nNO GLORY AWAITS US\nONLY FANGS\nONLY DEATH", "WE DID NOT CHOOSE THIS FATE\nTHE MISTS CLOSED IN\nTHE PRIESTS KNEW\nTHE PRIESTS KEEP SECRETS\n\nWE WILL NOT SURVIVE\nI CARVE MY LAST WORDS\nI EXISTED\nI WAS BETRAYED\nFROM MY SWEAT AND SACRIFICE\nTHE PRIESTS LIVE AND I WILL NOT\n\n- TAN'ZEK THE ABANDONED" },
    ["item_account_of_the_raising_of_a_frost_wyrm"] = { "Account of the Raising of a Frost Wyrm$B$BThe hulking bones were nearly swallowed by the snow, but there was no mistaking the grim claw that jutted upward, twisted in solemn agony. The necromancers assembled without a word, forming a ring around the dragon's corpse. They stood still for a moment as the wind encircled them with gusts of snow. Then the ritual began.", "Spokes of unholy light emanated from the center of the frozen bones, cracking through the snow and ice until at last the immense remains were fully exposed. With a gesture from Grand Necrolord Antiok, the bones shuddered and lurched above the ground, rotating slowly into place.", "The necromancers' incantations swelled as they began forcing sentience into the creature's remains. Violent contortions racked the body as the wyrm's conscience fought against its corrupt reanimation. A thin shriek pierced the air and the beast was subdued. An icy glow ignited within its gaping ribs, spreading along its limbs and lending an eerie cognizance to the sockets of its eyes.", "The Grand Necrlord came forward, and spoke. \"The Lich King has seen fit to raise you to serve the Scourge. You will be our loftiest instrument of death, raining torment upon the villages of our enemies, feasting upon the living, and bearing our finest death knights.\"$B", "The frost wyrm regarded them and dipped its head slightly in accord. The conversion was complete. Rearing back, it flared its wings like a fan of knives across the sky.$B" },
    ["item_admiral_barean_westwind"] = { "Admiral Barean Westwind\nGrand Admiral of the Scarlet Fleet\nCitizen of Kul'Tiras\nLost off the Frozen Coast of Northrend" },
    ["item_admiral_proudmoores_orders"] = { "Official Orders For The Kul Tiras Fleet\n\nI, Admiral Proudmoore, shall lead the first landing upon the shores of Kalimdor.\n\nLieutenant Benedict will be second in command in my absence. All domestic Kul Tiras military matters will be handled by him. If I do not send word from Tiragarde Keep within 12 months time, Lieutenant Benedict will lead the second wave to hold the location.", "Meanwhile, I am sending Lieutenant Alverold on an exploratory mission around the continent of Kalimdor. His forces are to complete their mission and then join our forces at Tiragarde Keep.\n\nIt is anticipated that Lieutenant Alverold's mission will last quite some time. The new land seems vast and dangerous. But should any misfortune befall myself or Benedict, Alverold's troops will retake the Keep.\n\nWe will send wave after wave until that stronghold is ours!\n\n--Admiral Proudmoore" },
    ["item_admiral_taylor"] = { "In honor of Admiral Taylor\n\nAdmiral Taylor was a true hero of the Alliance. His numerous accomplishments on the battlefield serving his people will not be forgotten.\n\nHe bravely set out to establish a garrison stronghold among these spires to further the Draenor campaign, but was cut down by his own men before his time. \n\nMay he rest in peace." },
    ["item_aegwynn_and_the_dragon_hunt"] = { "As the politics and rivalries of the seven human nations waxed and waned, the line of Guardians kept its constant vigil against chaos. There were many Guardians over the years, but only one ever held the magical powers of Tirisfal at any given time. One of the last Guardians of the age distinguished herself as a mighty warrior against the shadow.", "Aegwynn, a fiery human girl, won the approbation of the Order and was given the mantle of Guardianship. Aegwynn vigorously worked to hunt down and eradicate demons wherever she found them, but she often questioned the authority of the male-dominated Council of Tirisfal.", "She believed that the ancient elves and the elderly men who presided over the council were too rigid in their thinking and not farsighted enough to put a decisive end to the conflict against chaos. Impatient with lengthy discussion and debate, she yearned to prove herself worthy to her peers and superiors, and as a result frequently chose valor over wisdom in crucial situations.", "As her mastery over the cosmic power of Tirisfal grew, Aegwynn became aware of a number of powerful demons that stalked the icy northern continent of Northrend. Traveling to the distant north, Aegwynn tracked the demons into the mountains. There, she found that the demons were hunting one of the last surviving dragonflights and draining the ancient creatures of their innate magic.", "The mighty dragons, who had fled from the ever-advancing march of mortal societies, found themselves too evenly matched against the dark magics of the Legion. Aegwynn confronted the demons, and with help from the noble dragons, eradicated them. Yet, as the last demon was banished from the mortal world, a great storm erupted throughout the north.", "An enormous dark visage appeared in the sky above Northrend. Sargeras, the demon king and lord of the Burning Legion, appeared before Aegwynn and bristled with hellish energy. He informed the young Guardian that the time of Tirisfal was about to come to an end and that the world would soon bow before the onslaught of the Legion.", "The proud Aegwynn, believing herself to be a match for the menacing god, unleashed her powers against Sargeras' avatar. With disconcerting ease, Aegwynn battered the demonlord with her powers and succeeded in killing his physical shell. Fearing that Sargeras' spirit would linger on, Aegwynn locked the ruined husk of his body within one of the ancient halls of Kalimdor that had been blasted to the bottom of the sea when the Well of Eternity collapsed.", "Aegwynn would never know that she had done exactly as Sargeras had planned. She had inadvertently sealed the fate of the mortal world, for Sargeras, at the time of his corporeal death, had transferred his spirit into Aegwynn's weakened body. Unbeknownst to the young Guardian, Sargeras would remain cloaked within the darkest recesses of her soul for many long years." },
    ["item_aftermath_of_the_second_war"] = { "The devastating Second War against the orcish horde left the Alliance of Lordaeron in a state of shock and disarray. The bloodthirsty orcs, led by the mighty warchief, Orgrim Doomhammer, not only smashed their way through the dwarf-held lands of Khaz Modan, but had razed many of Lordaeron's central provinces as well. The unrelenting orcs even succeeded in ravaging the\nelves' remote kingdom of Quel'Thalas before their rampage was finally stopped.", "The Alliance armies led by Sir Anduin Lothar, Uther the Lightbringer, and Admiral Daelin Proudmoore pushed the orcs south into the shattered land of Azeroth - the first kingdom to fall before the orcs' ruthless onslaught.\n\nThe Alliance forces under Sir Lothar managed to push Doomhammer's clans out of Lordaeron and back into the orc-controlled lands of Azeroth. Lothar's forces surrounded the orcs' volcanic citadel of Blackrock Spire and laid siege to their defenses.", "In a last-ditch effort, Doomhammer and his lieutenants staged a daring charge from the Spire and clashed with Lothar's paladins in the center of the Burning Steppes. Doomhammer and Lothar squared off in a titanic battle that left both mighty combatants battered and drained. Though Doomhammer narrowly succeeded in vanquishing Lothar, the great hero's death did not have the effect the warchief had hoped for.", "Turalyon, Lothar's most trusted lieutenant, took up Lothar's bloodstained shield and rallied his grief-stricken brethren for a vicious counterattack. Under the ragged standards of both Lordaeron and Azeroth, Turalyon's troops slaughtered the bulk of Doomhammer's remaining forces in a glorious, but terrible rout.", "There was nothing left for the ragged, scattered orc survivors but to flee to the last standing bastion of orcish power - the dark portal.\n\nTuralyon and his warriors chased the remaining orcs through the festering Swamp of Sorrows and into the corrupted Blasted Lands where the dark portal stood. There, at the foot of the colossal portal, the broken horde and the rugged Alliance clashed in what would be the last, bloodiest battle of the Second War.", "Outnumbered and driven mad by the curse of their bloodlust, the orcs inevitably fell before the wrath of the Alliance. Doomhammer was taken prisoner and escorted to Lordaeron while his broken clans were rounded up and hauled north - back to Lordaeron." },
    ["item_albrecks_findings"] = { "Greetings, learned Antonivich:\n\nI hope this letter finds you in Thrallmar, productive in your studies.  My trappings here in Spinebreaker are adequate for my own experiments, though at times I do wish to be back in the Undercity with a full range of implements and servants to aid me...\n\nAh, the laments of a corpse.\n\nPleasantries aside, I have some interesting news -- the blood that $N gathered from the fel orcs shows a concentration of demonic taints.  It is almost identical to the taint of the original fel orcs of Azeroth... the taint of Mannoroth.", "It is impossible for Mannoroth's influence to reach across to Outland -- the beast has been dead for years -- but I fear another Pit Lord may be at play here.  A Pit Lord of Mannoroth's power... one able to corrupt the indigenous orcs.\n\nI will continue my studies of Bleeding Hollow Blood, but I urge you to pursue the trail.  And, I fear, that trail may lead deep into Hellfire Citadel.\n\nScholarly Yours,\nApothecary Albreck" },
    ["item_alicias_poem"] = { "Do not stand at my grave and weep, I am not there, I do not sleep.\nI am in a thousand winds that blow, across Northrend's bright and shining snow.\nI am the gentle showers of rain, on Westfall's fields of golden grain.\nI am in the morning hush, of Stranglethorn's jungle, green and lush.\nI am in the drums loud and grand, the thunderous hooves across Nagrand.\nI am the stars warmly gleaming, over Darnassus softly dreaming.\nI am in the birds that sing, I am in each lovely thing.\nDo not stand at my grave and cry, I am not there. I do not die." },
    ["item_alliance_military_ranks"] = { "ALLIANCE MILITARY RANKS\n\nOFFICERS\n\nGrand Marshal\n\nField Marshal\n\nMarshal\n\nCommander\n\nLieutenant Commander\n\nKnight-Champion\n\nKnight-Captain\n\nKnight-Lieutenant\n\nKnight\n\nENLISTED\n\nSergeant Major\n\nMaster Sergeant\n\nSergeant\n\nCorporal\n\nPrivate" },
    ["item_altar_of_zanza"] = { "We call upon you, Zanza of Zuldazar.\n\nBless those that ask for your help, Loa Zanza. Bless those that would ally with the Zandalarian\npeople.\n\nAid us in this time of need. Aid us Loa. Give us the power to strike down our enemies. Give us the power to once more defeat the Blood God." },
    ["item_always_remember"] = { "Even by mogu standards, Emperor Lao-Fe was a monster among beasts. His favored punishment among pandaren slaves was to separate families. Slaves who displeased him would have their children sent to the Serpent's Spine, to suffer and die as fodder for the mantid swarms.$b$bThis was the fate that befell a young pandaren monk named Kang. Kang was so grief-stricken over the loss of his cub that he chose to wear all black. In a moment of clarity, he saw the mogu overlords for what they were: weak. They possessed dark magics and horrific weapons, but their empire was completely reliant on slave labor.", "The servant races were not permitted to carry weapons during the reign of the mogu, so Kang determined that the pandaren themselves would become the weapons. So it came to pass that pandaren monks began their training in the martial arts, and Kang became known as the Fist of First Dawn.$b$bHistory does not report if Kang and his son ever met again, but it was this father's love that sparked the rebellion that would change the face of Pandaria forever." },
    ["item_amber"] = { "Amber is the cornerstone of mantid society. They use this material in their architecture, their art, and their technology. $b$bMasters of sound, the mantid long ago found a way to use amber to extend the range of their acoustic casting. In this way they are able to communicate over vast distances. No army has successfully marched on mantid lands undetected, and even lone travellers are urged caution as their movements are no doubt being watched the moment they venture beyond the wall. $b$b The Empress and her council of Klaxxi safeguard the great trees of Townlong Steppes - the \"kypari\" they are called - as the only source of their precious amber. Legend has it that the kypari once flourished east of the wall, but the mogu cut them all down in their never-ending war against the mantid swarm." },
    ["item_an_exotic_cookbook"] = { "1. Get one or eight man\n2. Hit man hard\n3. Hit man more\n4. Put man in fire\n5. Eat man" },
    ["item_an_undelivered_letter"] = { "Dear Noble Sir,\n\nWord of your need for a tutor for your children has traveled to me here in Goldshire, where I take up temporary residence in the Lion's Pride Inn. Due to the unfortunate state of events in the region, I was forced to abandon my post as Headmaster of the Moonbrook Schoolhouse. Please accept my application to serve as tutor for your offspring. Headmaster Crillian of the Academy can speak to you of my abilities if necessary.", "I shall travel to meet you in person when the winter rains subside and the roads are suitable for travel once again.\n\nUntil then,\n\nStalvan Mistmantle of Silverpine" },
    ["item_an_unopened_tome_of_advice"] = { "Table of Contents$B$BChapter 1 - The Dead and You$B$BChapter 2 -  Maintaining a Ghoulish Figure: Seven Easy Exercises$B$BChapter 3 - Keeping the Chill Out: Choosing a Coordinated Coffin$B$BChapter 4 - Graveyard Guarantees: Fifty Sure Signs of Love$B$B<The tome is in pristine condition and appears to be completely unread>" },
    ["item_ancient_dragonforged_blades"] = { "Rare indeed are the 'prismatic' blades forged by the combined will of the five dragonflights. Among the greatest of these blades were the sister swords of Quel'Serrar and Quel'Delar.\nIn her wisdom, the dragon queen Alexstrasza gifted one of the blades to each of the elven peoples of Azeroth. Quel'Serrar was to be borne by a valiant kaldorei warrior, while Quel'Delar was entrusted to a quel'dorei champion.\nEach blade transformed in the hands of its wielder, molding its magic to its master's strengths..." },
    ["item_ancient_inscription"] = { "The Shrine of Mel'Thandris\n\n\"May the light of Elune shine upon this vale eternal and illuminate the ways of the forest as it has for time immemorial.\"" },
    ["item_ancient_tablet"] = { "The Mallet of Zul'Farrak\n\nTo create the Mallet of Zul'Farrak, one must first travel to the Altar of Zul and obtain the sacred mallet from a troll Keeper.\n\nNext, one must bring the sacred mallet to the altar atop of the troll city of Jintha'alor.\n\nUsing the sacred mallet at the altar will infuse it with power, and transform it into the Mallet of Zul'Farrak." },
    ["item_annals_of_darrowshire"] = { "The Annals of Darrowshire Darrowshire, named from the Darrowmere Lake to its west, is a village tucked into the southern foothills of Lordaeron. Known for humble yet hardworking residents, Darrowshire stayed in the background of Lordaeron history until the Second War. Heroes were made during that war. And heroes were lost.", "The Battle of Darrowshire The Battle of Darrowshire took place in the middle of the Second War, when scourge forces rampaged across Lordaeron. Darrowshire was cut off from the bulk of Alliance forces, but the town was bolstered by a company of troops, a contingent of paladins of the Silver Hand, and a staunch group of local militia led by Captain Joseph Redpath.", "The Scourge's first assaults on Darrowshire were sparse. Small groups of marauding skeletons and corpses wandered the outskirts of the village and were repelled. But the Scourge were not balked by the defender's tenacity, and responded in kind; soon after the first wave of attacks a second wave emerged. Champion ghouls, servants of the ghoul lord Horgus, screamed down from the hills and clashed with beleaguered Darrowshire defenders.", "The Defenders weakened, but were relieved by paladins, disciples of the Silver Hand. Their leader, Davil Crokford, was a native of Darrowshire. He brought his followers to the village when he heard of the impending attack, and together with the defenders they held back the servants of Horgus. When Horgus himself entered the battle, he met with Davil. For many minutes they fought and Davil eventually prevailed, but he suffered a mortal wound and died soon after defeating the ghoul lord.", "The battle continued, and Captain Redpath led his militia bravely. And it might have been won, had the captain not been corrupted by the death knight Marduk the Black. In the middle of the fray Marduk rode up to Redpath, and with black magic he tore loose Redpath's spirit, twisting it into an evil shadow of the brave captain.", "The corrupted Captain Redpath then spread his evil taint among the defenders of Darrowshire, who betrayed their allies and slaughtered them. They then turned on the town of Darrowshire and killed all who hid in their homes. The remaining scourge army, along with the corrupted spirit of Captain Redpath, then left the ravaged village of Darrowshire and tore into Lordaeron, adding to the pain and death of the Second War." },
    ["item_another_clue_to_sanders_treasure"] = { "Now from this here barrel, face ye North. Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs. If ye poke around that jug, ye just might find what you're lookin' for." },
    ["item_aquatic_wonders"] = { "DAILY FEEDING DEMONSTRATION$b$bAsk a friendly staff member for feeding times and directions to our gift shop!$b$bDID YOU KNOW? Lion Seals are named for their fearsome roar, similar to that of the common Land Lion. We believe that their captivity has made them shy, however, so they no longer roar.$b$bThis is why conservation efforts are so important. Your small donation to the Menagerie can ensure we expand our exhibits in the millenia to come!" },
    ["item_arathor_and_the_troll_wars"] = { "As the high elves fought for their lives against the trolls' fierce onslaught, the scattered, nomadic humans of Lordaeron fought to consolidate their own tribal lands. The tribes of early humanity raided each other's settlements with little heed for racial unification or honor.", "Yet one tribe, known as the Arathi, saw that the trolls were becoming too great a threat to ignore. The Arathi wished to bring all of the tribes under its rule so that they could provide a unified front against the troll warbands.", "Over the course of six years, the cunning Arathi outmaneuvered and outfought the rival tribes. After every victory, the Arathi offered peace and equality to the conquered people; thus, they won the loyalty of those they had beaten. Eventually the Arathi tribe came to include many disparate tribes, and the ranks of its army grew vast.", "Confident that they could hold their own against the troll warbands or even the reclusive elves if need be, the Arathi warlords decided to construct a mighty fortress city in the southern regions of Lordaeron. The city-state, named Strom, became the capital of the Arathi nation, Arathor. As Arathor prospered, humans from all over the vast continent traveled south to the protection and safety of Strom.", "United under one banner, the human tribes developed a strong, optimistic culture. Thoradin, the king of Arathor, knew that the mysterious elves in the northlands were under constant siege by the trolls, but refused to risk the safety of his people in defense of reclusive strangers. Many months passed as rumors of the elves' supposed defeat trickled down from the north. It was only when weary ambassadors from Quel'Thalas reached Strom that Thoradin realized how great the troll threat truly was.", "The elves informed Thoradin that the troll armies were vast and that once the trolls had destroyed Quel'Thalas, they would move on to attack the southlands. The desperate elves, in dire need of military aid, hastily agreed to teach certain select humans to wield magic in exchange for their help against the warbands.", "Thoradin, distrustful of any magic, agreed to aid the elves out of necessity. Almost immediately, elven sorcerers arrived in Arathor and began to instruct a group of humans in the ways of magic.", "The elves found that although humans were innately clumsy in their handling of magic, they possessed a startling natural affinity for it. One hundred men were taught the very basics of the elves' magical secrets: no more than was absolutely necessary to combat the trolls. Convinced that their human students were ready to aid in the struggle, the elves left Strom and traveled north alongside the mighty armies of King Thoradin.", "The united elf and human armies clashed against the overwhelming troll warbands at the foot of the Alterac Mountains. The battle lasted for many days, but the unflagging armies of Arathor never tired or gave an inch of ground before the troll onslaught. The elven lords deemed that the time had come to release the powers of their magic upon the enemy.", "The hundred human magi and a multitude of elven sorcerers called down the fury of the heavens and set the troll armies ablaze. The elemental fires prevented the trolls from regenerating their wounds and burned their tortured forms from the inside out.", "As the troll armies broke and attempted to flee, Thoradin's armies ran them down and slaughtered every last one of their soldiers. The trolls would never fully recover from their defeat, and history would never see the trolls rise as one nation again. Assured that Quel'Thalas was saved from destruction, the elves made a pledge of loyalty and friendship to the nation of Arathor and to the bloodline of its king, Thoradin. Humans and elves would nurture peaceful relations for ages to come." },
    ["item_archbishop_alonsus_faol"] = { "Archbishop Alonsus Faol\n\nBenevolent patron of the Church of Light.\n\nThough he began his good work in Stratholme, Lordaeron, Archbishop Faol was a great friend to the people of Stormwind. In the dark days after the Second War, he helped to reform the Brotherhood of Northshire and raised vast funds to rebuild Stormwind city itself.\n\nThis Cathedral stands not only as a bastion of the Holy Light, but as a lasting testament to one man's noble spirit and generosity." },
    ["item_archimondes_return_and_the_flight_to_kalimdor"] = { "Once Kel'Thuzad was whole again, Arthas led the Scourge south to Dalaran. There the lich would obtain the powerful spellbook of Medivh, and use it to summon Archimonde back into the world. From that point on, Archimonde himself would begin the Legion's final invasion. Not even the wizards of the Kirin Tor could stop Arthas' forces from stealing Medivh's book, and soon Kel'Thuzad had all he needed to perform his spell.", "After ten thousand years, the mighty demon Archimonde and his host emerged once again upon the world of Azeroth. Yet Dalaran was not their final destination. Under orders from Kil'jaeden himself, Archimonde and his demons followed the undead Scourge to Kalimdor, bent on destroying Nordrassil, the World Tree.", "In the midst of this chaos, a lone, mysterious prophet appeared to lend the mortal races guidance. This prophet proved to be none other than Medivh, the last Guardian, miraculously returned from the Beyond to redeem himself for past sins. Medivh told the Horde and the Alliance of the dangers they faced and urged them to band together.", "Jaded by generations of hate, the orcs and humans would have none of it. Medivh was forced to deal with each race separately, using prophecy and trickery to guide them across the sea to the legendary land of Kalimdor. The orcs and humans soon encountered the long-hidden civilization of the Kaldorei.", "The orcs, led by Thrall, suffered a series of setbacks on their journey across Kalimdor's Barrens. Though they befriended Cairne Bloodhoof and his mighty tauren warriors, many orcs began to succumb to the demonic bloodlust that had plagued them for years. Thrall's greatest lieutenant, Grom Hellscream, even betrayed the Horde by giving himself over to his baser instincts.", "As Hellscream and his loyal Warsong warriors stalked through the forests of Ashenvale, they clashed with the ancient night elf Sentinels. Certain that the orcs had returned to their warlike ways, the demigod Cenarius came forth to drive Hellscream and his orcs back. Yet Hellscream and his orcs, overcome with supernatural hate and rage, managed to kill Cenarius and corrupt the ancient forestlands.", "Ultimately, Hellscream redeemed his honor by helping Thrall defeat Mannoroth, the demon lord who first cursed the orcs with his bloodline of hate and rage. With Mannoroth's death, the orcs' blood-curse was finally brought to an end.", "While Medivh worked to convince the orcs and humans of the need for an alliance, the night elves fought the Legion in their own secretive ways. Tyrande Whisperwind, the immortal High Priestess of the night elf Sentinels, battled desperately to keep the demons and undead from overrunning the forests of Ashenvale. Tyrande realized that she needed help, so she set out to awaken the night elf druids from their thousand-year slumber.", "Calling upon her ancient love, Malfurion Stormrage, Tyrande succeeded in galvanizing her defenses and driving the Legion back. With Malfurion's help, nature herself rose up to vanquish the Legion and its Scourge allies.", "While searching for more of the hibernating druids, Malfurion found the ancient barrow prison in which he had chained his brother, Illidan. Convinced that Illidan would aid them against the Legion, Tyrande set him free. Though Illidan did aid them for a time, he eventually fled to pursue his own interests.", "The night elves braced themselves and fought the Burning Legion with grim determination. The Legion had never ceased in its desire for the Well of Eternity, long the source of strength for the World Tree and itself the heart of the night elf kingdom. If their planned assault on the Tree was successful, the demons would literally tear the world apart." },
    ["item_archive_of_the_tirisgarde"] = { "<HTML><BODY>\n<H1 align=\"center\">Archive of the Tirisgarde</H1>\n<IMG src=\"Interface\\Common\\spacer\" align=\"center\" width=\"1\" height=\"27\"/>\n<IMG src=\"Interface\\Pictures\\artifactbook-mage-cover\" align=\"center\" width=\"230\" height=\"230\"/>\n<IMG src=\"Interface\\Common\\spacer\" align=\"center\" width=\"1\" height=\"27\"/>\n<p align=\"center\">Penned by Tirisgarde Researcher Edirah.</p>\n</BODY></HTML>", "<HTML><BODY>\n<p></p>\n<IMG src=\"Interface\\Pictures\\artifactbook-mage-aluneth\" align=\"center\"/>\n<IMG src=\"Interface\\Common\\spacer\" align=\"center\" width=\"1\" height=\"160\"/>\n<H3 align=\"center\">Aluneth</H3>\n<BR/>\n<P>\nAzeroth is filled with legendary relics and artifacts, but none compare to Aluneth. For hundreds of years, Guardian Aegwynn used this greatstaff to defend Azeroth from the Burning Legion.\n<BR/><BR/>\nYet that alone is not what makes this weapon unique. An entity of pure arcane energy known as Aluneth is bound to the greatstaff. Harnessing this unruly being and its power requires tremendous precision and focus. An ordinary mage could never hope to control Aluneth. \n<BR/><BR/>\nFortunately, you are no ordinary mage.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part One</H2>\n<HR/>\n<P>\nThe wise and mirthful blue dragons were the first creatures on Azeroth to discover Aluneth. While manipulating the fabric of reality, they tapped into another realm of existence and made contact with the strange arcane entity. \n<BR/><BR/>\nThe blue dragons loved unraveling mysteries and delving into the secrets of the universe. They were so intrigued by Aluneth's existence that they summoned the entity into the world for further study. \n<BR/><BR/>", "Aluneth immediately went on a rampage through the blue dragons' lair, the Nexus. The arcane presence destroyed countless rare artifacts and tomes of power before finally being contained. The dragons were not angry about what had happened--they were delighted by Aluneth's capricious nature.\n<BR/><BR/>\nAfter years of conducting harmless experiments on Aluneth, the blue dragons satisfied their curiosity and sent the entity back to its own realm.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Two</H2>\n<HR/>\n<P>\nFrom chapter forty-three of Ancient Magic and How to Wield It Without Destroying the World:\n<BR/><BR/>\n\"And so we come to the story of the Highborne named Meitre and the source of his power, Aluneth. Few subjects are as hotly debated. Last year alone, five magi were treated for severe burns after their discussion of Meitre escalated into a fiery brawl. Let us put the rumors to rest and focus on the facts.\n<BR/><BR/>", "\"Meitre lived during the height of the night elf empire, and he was one of his race's most gifted sorcerers. As the story goes, he spent years exploring the world in search of knowledge. His extensive travels brought him into contact with an unknown blue dragon, from whom Meitre discovered the existence of the arcane being named Aluneth and the otherworldly plane where it dwelled.\n<BR/><BR/>\n\"The sorcerer never enslaved Aluneth--the being was far too strong and unwieldy for that. Yet Meitre found a way to draw power from the entity, thereby using its energies to enhance his own spells.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Three</H2>\n<HR/>\n<P>\nFrom chapter fifty of Ancient Magic and How to Wield It Without Destroying the World, concerning the Burning Legion's first invasion of Azeroth:\n<BR/><BR/>\n\"Most Highborne sorcerers sided with the Burning Legion and used their powers to help the demons invade the world. Meitre did not. He joined the night elf resistance and fought to defend the world. It was during these troubling years that Meitre mastered his connection with Aluneth.\n<BR/><BR/>", "\"In one battle, he and a group of night elf defenders found themselves surrounded by an overwhelming force of demons. Death was imminent, but Meitre did not abandon hope. He called on Aluneth's energies and wove a mass teleportation spell that transported him and his comrades to safety.\n<BR/><BR/>\n\"Let this be a lesson that what makes magi great is not only their ability to destroy but their ability to save lives. True wisdom is knowing the right time to use one instead of the other.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Four</H2>\n<HR/>\n<P>\nFrom chapter sixty-one of Ancient Magic and How to Wield It Without Destroying the World, concerning the aftermath of the War of the Ancients:\n<BR/><BR/>\n\"Following their victory over the Legion, the night elves outlawed the use of arcane magic. They believed that the sorcerous arts were not safe and that wielding them would only lead to another disaster like the War of the Ancients.\n<BR/><BR/>\n\"Meitre could not give up magic. Doing so would mean breaking his connection with Aluneth. The sorcerer quailed at the thought of losing his ability to draw on the entity's power. Perhaps he lacked confidence in his own skills. Whatever the case, Meitre retreated from society and became a recluse.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Five</H2>\n<HR/>\n<P>\nNo one knows exactly what became of Meitre, but he left behind a wealth of scrolls that would form the basis of modern magic. His writings included a number of spells that the sorcerer had created himself.\n<BR/><BR/>\nEven thousands of years after the War of the Ancients, high elf and human magi continued learning from Meitre's knowledge. The ability to cast spells from his scrolls was seen as an important milestone in a young apprentice's education, and a measure of a pupil's aptitude.\n<BR/><BR/>\nThough many magi delved into Meitre's scrolls, no one knew of Aluneth. The entity that had played such a critical role in the sorcerer's life was forgotten... until the time of Guardian Aegwynn.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Six</H2>\n<HR/>\n<P>\nAegwynn was the Guardian of Tirisfal, a sorceress imbued with extraordinary power and charged with protecting Azeroth from the Burning Legion.\n<BR/><BR/>\nLike all magi of her era, Aegwynn was familiar with Meitre and his scrolls. During her apprenticeship, she had mastered the ancient elf's spells much earlier than the other students.\n<BR/><BR/>\nSomething had always perplexed Aegwynn about Meitre. While studying his writings, she realized that the elf had wielded immense power-more than any regular sorcerer should have been capable of. After Aegwynn inherited the mantle of Guardian, she became obsessed with finding out how.\n<BR/><BR/>\nAegwynn discovered a series of lost scrolls written by Meitre. They described Aluneth in detail, and even included spells the elf had used to tap into the being's power.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Seven</H2>\n<HR/>\n<P>\nGuardian Aegwynn believed she could use Aluneth as a formidable weapon against the Burning Legion. Yet unlike Meitre, she would not simply tap into the entity's energies; she would bring the being into Azeroth and bind it to her will.\n<BR/><BR/>\nAegwynn summoned Aluneth with ease, but it would not obey her commands. The fickle creature thrashed against the Guardian's containment magics and nullified her spellwork. Aegwynn reveled in the challenge of taming Aluneth. \n<BR/><BR/>\nAfter many setbacks, Aegwynn finally bound the entity to an enchanted greatstaff. The task of containing Aluneth was done, but it would take the Guardian years to truly harness its power.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Eight</H2>\n<HR/>\n<P>\nAn excerpt from Fire in the North: The Battle between Aegwynn and Sargeras, by the historian Llore:\n<BR/><BR/>\n\"Of all the trials Aegwynn faced, of all the foes she fought, none rivaled Sargeras. In the frozen wastes of Northrend, the Guardian confronted the ruler of the Burning Legion. \n<BR/><BR/>\n\"This was not Sargeras in his true form, only an avatar containing a portion of his strength. Even so, Aegwynn's opponent was powerful beyond measure.\n<BR/><BR/>", "\"Aegwynn raised Aluneth high and called down a storm of arcane magic to annihilate Sargeras. Nothing happened. The entity bound to Aegwynn's weapon resisted her command. As she struggled to assert her will over Aluneth, Sargeras launched a furious assault against the Guardian.\n<BR/><BR/>\n\"Ultimately, Aegwynn put Aluneth aside and opted for a more reliable weapon. She summoned Atiesh, a mighty staff passed from Guardian to Guardian, and renewed her attack against Sargeras.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Nine</H2>\n<HR/>\n<P>\nThough Aegwynn defeated Sargeras, the battle changed her forever. \n<BR/><BR/>\nUnbeknownst to the Guardian, the Legion's ruler had transferred a portion of his spirit into her soul. Aegwynn's demeanor darkened. As the years passed, she grew suspicious of the Council of Tirisfal, the order of magi that had imbued her with power and given her the mantle of Guardian. \n<BR/><BR/>\nTo distance herself from the council, Aegwynn used Aluneth to forge a secret refuge. \n<BR/><BR/>\nAtop a nexus of magical ley lines that coursed through Azeroth, the Guardian crafted her spell. She harnessed the full potential of Aluneth's energies, and reality warped and shifted around Aegwynn. \n<BR/><BR/>\nLegend has it that a great tower then rose from the earth. It would become known as Karazhan.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Ten</H2>\n<HR/>\n<P>\nFor centuries, Aegwynn strengthened her control over Aluneth. She dispatched the Legion's demons with ease and secured Azeroth's safety for generations. \n<BR/><BR/>\nAegwynn eventually gave birth to a boy named Medivh, who would become the next Guardian. In time, Aegwynn planned to bequeath Aluneth to her son, but that day would never come.\n<BR/><BR/>\nThe spirit of Sargeras had passed from Aegwynn to Medivh. Over many long years, the demon lord twisted the new Guardian's thoughts. Sargeras used Medivh to help the mighty orcish Horde invade Azeroth and bring war to the world.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Aluneth, Part Eleven</H2>\n<HR/>\n<P>\nAn excerpt from The Fate of Aegwynn, by the historian Llore:\n<BR/><BR/>\n\"When Aegwynn learned of Medivh's actions, she confronted him. Mother and child unleashed the full fury of their magics upon each other in a battle that would decide Azeroth's future. \n<BR/><BR/>\n\"Even with Aluneth at her command, Aegwynn could not best Medivh. She only narrowly survived her encounter with the corrupted Guardian.\n<BR/><BR/>", "\"Medivh was later vanquished, but that brought Aegwynn little solace. She was tormented by what had become of her son-by the darkness that she had unwittingly passed to him. For a time, Aegwynn retreated from society, and she entrusted Aluneth to the Kirin Tor of Dalaran.\n<BR/><BR/>\n\"To prevent anyone from abusing Aluneth's power, the Kirin Tor locked the greatstaff away. For years, it would remain in an enchanted vault, under the watchful eyes of blue dragons.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<p></p>\n<IMG src=\"Interface\\Pictures\\artifactbook-mage-felomelorn\" align=\"center\"/>\n<IMG src=\"Interface\\Common\\spacer\" align=\"center\" width=\"1\" height=\"130\"/>\n<H3 align=\"center\">Felo'melorn</H3>\n<BR/>\n<P>\nFelo'melorn. Flamestrike. Sword of kings. Bane of trolls. Its legend stretches back through the millennia. It stands as a symbol of hope, loss, and power-of destruction and renewal.\n<BR/><BR/>\nThose who have wielded Felo'melorn have forever etched their names into history. Will you do the same?\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part One</H2>\n<HR/>\n<P>\nThough it is not known for certain, rumors that have passed down through generations suggest that a young Dath'Remar Sunstrider, who would one day become king of the high elves, dreamed of the weapon Felo'melorn. In that dream, the arcane blade burned like the sun and dispatched so many enemies that it created a swift-flowing river of blood. \n<BR/><BR/>\nDath'Remar would later recount the specifics of the blade's appearance to the renowned magesmith Luminarian as he crafted the weapon on his arcane forge.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Two</H2>\n<HR/>\n<P>\nFrom the personal writings of Serena Everwind, night elf priestess during the War of the Ancients:\n<BR/><BR/>\n\"Dath'Remar wielded Felo'melorn, Flamestrike, like an elf possessed. He was an unstoppable force, at once majestic and graceful yet savage and deadly. The runes of the blade seemed to pulse in rhythm with the pounding of Dath'Remar's fierce heart as he separated limb from body and head from shoulders. \n<BR/><BR/>\n\"When the fighting was done, Dath'Remar stood painted in demon blood. As night fell, we knew that more battles remained, and yet, with this elf and this blade among us, we held out hope that victory did not lie beyond our grasp.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Three</H2>\n<HR/>\n<P>\nIn the hands of Anasterian Sunstrider, great-grandson of the high elf king Dath'Remar, Felo'melorn became a legendary troll-killer. \n<BR/><BR/>\nAmong the trolls, whispers spread of a spellbound blade, empowered by arcane magic not only to slay the most formidable and cunning of its enemies, but also to cut through superior numbers and irrigate battlefields with their blood. \n<BR/><BR/>\nTroll witch doctors set about casting hexes and curses against the infamous weapon, but history bears out that even the darkest voodoo did little to negate the effectiveness of Felo'melorn during the Troll Wars.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Four</H2>\n<HR/>\n<P>\nAn account of the battle between the death knight Arthas and Anasterian Sunstrider during the attack on Quel'Thalas, from the personal writings of the former priestess Liadrin:\n<BR/><BR/>\n\"All fighting came to a halt. Silence fell over the battlefield. I watched from a distance, helpless as the former prince Arthas cast a spell freezing Anasterian in a coat of ice. The king cast a counterspell, freeing himself as the death knight advanced. Felo'melorn and Frostmourne met, the strident clash of their impact rolling out over the ice and across the blood-drenched tiles.\n<BR/><BR/>", "\"The force of their meeting cleaved Felo'melorn, Flamestrike, in half. Arthas's swing continued, severing the right leg of our aged, beloved king. Even as Anasterian dropped to his remaining knee, he struck out, burying his broken blade in the death knight's thigh. Arthas whirled Frostmourne up, over, and down, thrusting it to the hilt behind Anasterian's collarbone and deep into his chest.\n<BR/><BR/>\n\"The death knight yanked his blade free; Anasterian pitched forward onto the ice. \n<BR/><BR/>\n\"The great king of the high elves was dead. And for many of us that day, our hopes and our hearts died with him.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Five</H2>\n<HR/>\n<P>\nExcerpt from the journal of Lor'themar Theron, concerning Prince Kael'thas's return in the immediate wake of Quel'Thalas's destruction:\n<BR/><BR/>\n\"Our fallen king, Anasterian, lay upon a table in the tavern hall; his broken blade, Felo'melorn, rested upon his chest, the two pieces joined. I told our prince that the weapon had been shattered in the battle with the death knight Arthas.\n<BR/><BR/>\n\"Kael'thas walked to his father's body and ran his finger over the fracture, remarking that he did not believe it possible for Flamestrike's blade to be sundered. \n<BR/><BR/>\n\"I was left wondering what legacy, if any, awaited our people and the legendary blade that now symbolized not strength or dominance, but fallibility.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Six</H2>\n<HR/>\n<P>\nIn the time following the devastating Scourge attack on Quel'Thalas, Prince Kael'thas renamed the high elf survivors the sin'dorei, or blood elves. While the prince and a band of blood elves assisted the human troops of Grand Marshal Garithos against the remaining undead forces, it was rumored that Kael'thas kept the pieces of his father's sword, Felo'melorn, on a sideboard in his dilapidated quarters. \n<BR/><BR/>\nKael'thas dreamed of making Flamestrike's blade whole again so that it might serve once more as a symbol of hope, to show his people that even in the face of overwhelming hardship, the blood elves would not be broken.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Seven</H2>\n<HR/>\n<P>\nIn time, Prince Kael'thas Sunstrider realized his dream of rejoining the broken pieces of Felo'melorn.\n<BR/><BR/>\nIt is said that the sword was reforged with \"magic, and hatred, and a burning need for revenge.\"\n<BR/><BR/>\nThere are some who speculate that the sword was taken to a descendant of Luminarian, the magesmith who originally created the weapon on his legendary arcane forge before the War of the Ancients. This assertion has never been independently verified.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Eight</H2>\n<HR/>\n<P>\nAn account of Kael'thas Sunstrider's battle with the death knight Arthas, from the personal writings of Kael'thas:\n<BR/><BR/>\n\"The death knight charged, his blade, Frostmourne, arcing down. I blocked with my staff, but it was no use; the stave shattered. It was then that I revealed my surprise...\n<BR/><BR/>\n\"Felo'melorn. Flamestrike, mended, made whole once again. It burned with righteous fury as our two swords clashed. Each of us held steady, blades pressed tight. I smiled and asked Arthas if he remembered Felo'melorn.\n<BR/><BR/>\n\"He snidely replied that he saw it snap beneath Frostmourne in the instant before he slew my father. When he shoved me back, I told him that I had found the blade, had it reforged...\n<BR/><BR/>", "\"'Broken swords are weak where they are mended, elf,' the despicable former prince said.\n<BR/><BR/>\n\"'Human swords, perhaps,' I replied. And I knew... that day I knew this one thing at least: I might not win, but Felo'melorn would not be broken again. \n<BR/><BR/>\n\"Filled with renewed purpose, I attacked.\" \n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Nine</H2>\n<HR/>\n<P>\nFrom the journal of Lyandra Sunstrider, distant relative of King Anasterian:\n<BR/><BR/>\n\"Today, at last, my efforts to uncover the location of my birthright have borne fruit.\n<BR/><BR/>\n\"It is now made known to me that the sword of my ancestors, Felo'melorn, Flamestrike, resides within the Lich King's stronghold of Icecrown Citadel. \n<BR/><BR/>\n\"It was there that the blade was taken to after leaving the possession of the traitor Kael'thas Sunstrider. \n<BR/><BR/>\n\"At last, I shall validate my claim to the Sunstrider throne. I shall seek out Flamestrike, and I shall realize my destiny.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Ten</H2>\n<HR/>\n<P>\nLast journal entry of Lyandra Sunstrider, distant relative of King Anasterian:\n<BR/><BR/>\n\"Icecrown Citadel, I curse your name.\n<BR/><BR/>\n\"Along empty halls I made my way, through a twisting labyrinth of black saronite, until I beheld a warm, red glow pouring from a room at the end of a dismal passage. \n<BR/><BR/>\n\"I entered and saw... Felo'melorn. Flamestrike, mounted upon a dais. At last, the sword that would solidify my claim to the Sunstrider throne! I approached, awestruck, reached out...\n<BR/><BR/>\n\"And the door slammed shut behind me. The prize I had so long sought was at last within my grasp...\n<BR/><BR/>\n\"But now... I am trapped. Surely death awaits me. Or perhaps... something worse.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Felo'melorn, Part Eleven</H2>\n<HR/>\n<P>\nExcerpt from a speech given by Aethas Sunreaver:\n<BR/><BR/>\n\"My brothers, in the time since the Sunreavers' expulsion from the Kirin Tor, we have endeavored to secure readmission. I tell you now that the key to our salvation exists... it exists within the frozen black halls of Icecrown Citadel, in the possession of a fallen elf--Lyandra Sunstrider.\n<BR/><BR/>", "\"She dwells there now as a reanimated shell of her former self, but I have learned that it is Lyandra who holds the infamous blade of kings, Felo'melorn. Flamestrike. It has been trusted to remain in her keeping by the Lich King himself, to aid in battle against the Legion. Lyandra was obsessed with the blade while she was among the living, and when she ventured to Icecrown to claim it, that obsession proved to be her downfall. However, Lyandra's tragic misstep provides us with an opportunity...\n<BR/><BR/>\n\"An opportunity for the Sunreavers to retake our rightful place... among the Kirin Tor!\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<p></p>\n<IMG src=\"Interface\\Pictures\\artifactbook-mage-ebonchill\" align=\"center\"/>\n<IMG src=\"Interface\\Common\\spacer\" align=\"center\" width=\"1\" height=\"120\"/>\n<H3 align=\"center\">Ebonchill</H3>\n<BR/>\n<P>\nThe half-elf Alodi wielded Ebonchill during his long tenure as the first Guardian of Tirisfal. He infused the greatstaff with his extraordinary power, and he began a tradition of passing the weapon down from mage to mage. For thousands of years, this practice continued uninterrupted. Some of Azeroth's mightiest spellcasters used Ebonchill to hunt down and vanquish the Burning Legion's wicked agents. \n<BR/><BR/>\nWhen the Legion stole Ebonchill, the tradition put in place by Alodi was broken... but only for a time. Now, in your hands, the greatstaff can once again fulfill its purpose to safeguard Azeroth.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part One</H2>\n<HR/>\n<P>\nThe tale of Ebonchill begins with a half-elf mage named Alodi. Though he did not create the staff, he made it into the legendary weapon it is today.\n<BR/><BR/>\nAlodi never knew his real parents. From infancy, he was raised in an orphanage for magically gifted children in Dalaran. His only connection to his parents was Ebonchill, which they had left with the boy when they abandoned him at the school.\n<BR/><BR/>\nHis dubious parentage and mixed ancestry made life difficult for Alodi. Most magi pitied him, but others treated him with scorn. No one believed he would rise to greatness. They were mistaken.\n<BR/><BR/>\nIn time, the orphan would become the first Guardian of Tirisfal, one of the most powerful magi to have ever lived.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Two</H2>\n<HR/>\n<P>\nAlodi became Guardian at a dire time for the Council of Tirisfal. This secret order of magi was created to protect Azeroth from demons. For many years, its members succeeded in their quest.\n<BR/><BR/>\nThen a dreadlord named Kathra'natir changed everything. The demon infiltrated Dalaran and thwarted the council's attempts to stop him. Kathra'natir sowed unrest in the streets, threatening to engulf the city in turmoil.\n<BR/><BR/>\nTo defeat Kathra'natir, the Council of Tirisfal's magi took drastic measures. Through a complex ritual, they infused all of their power into Alodi. It was an act of great trust and faith.\n<BR/><BR/>\nKathra'natir was no match for the newly empowered Alodi. The Guardian unleashed his astonishing power on the demon and banished him from the world in short order.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Three</H2>\n<HR/>\n<P>\nFrom his early days in the Dalaran orphanage, Alodi had been fascinated with frost magic. This was due in part to the icy enchantments woven into Ebonchill. With the staff, Alodi learned how to freeze water and manipulate air temperature, often to the chagrin of the orphanage headmaster.\n<BR/><BR/>\nShortly after Alodi became Guardian, he honed his mastery of frost magic and imbued Ebonchill with his own powers. A wintry aura enveloped the staff. Much to the astonishment of Alodi's companions on the Council of Tirisfal, the weapon never felt cold to the touch. Ebonchill contained only a sliver of Alodi's might, but even that was more than most magi could ever hope of wielding.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Four</H2>\n<HR/>\n<P>\nDuring Alodi's tenure as Guardian, he used Ebonchill to hunt down every demon that stalked the lands of Azeroth. Many records tell of him calling down vicious ice storms to overwhelm his enemies, or encasing the Legion's agents in solid blocks of ice before exiling them from the world.\n<BR/><BR/>\nNear the end of Alodi's one hundred years of service as Guardian, he turned his attention to his apprentices. He had trained and tutored many young magi in the ways of the arcane. They had become the family that he had never had, and he treated them all as his own sons and daughters.\n<BR/><BR/>", "Alodi decided to pass on Ebonchill to one of these learned apprentices. He did not choose the most powerful. More important to Alodi were compassion, wisdom, and comradery. After much consideration, he entrusted his greatstaff to the apprentice who most embodied these traits.\n<BR/><BR/>\nSo began a tradition of bequeathing Ebonchill that would endure for millennia.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Five</H2>\n<HR/>\n<P>\nAll was well with the Council of Tirisfal until the rise of Guardian Aegwynn. The gifted mage grew suspicious of the order. She believed that the council was abusing its power by manipulating the politics of human kingdoms. At the end of her one hundred years of service, she refused to step down as Guardian.\n<BR/><BR/>\nAegwynn's disobedience eventually forced the council's hand. It formed the Tirisgarde, a group of talented magi charged with hunting down and subduing the wayward Guardian. \n<BR/><BR/>\nAmong the Tirisgarde was a promising but arrogant young spellcaster named Tarthen. His aging master had long ago inherited Ebonchill, and he was in the process of choosing which apprentice would take it up next.\n<BR/><BR/>", "Tarthen fully expected to receive the greatstaff. He eclipsed his fellow apprentices in raw power and potential. But Tarthen's master put little weight in such things. \n<BR/><BR/>\nWhen the day of the ceremony came, the elderly mage gave Ebonchill to another apprentice--one who embodied the qualities of compassion, wisdom, and comradery.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Six</H2>\n<HR/>\n<P>\nAfter his master passed on Ebonchill to a different apprentice, Tarthen wallowed in anger and bitterness. He believed he had been wronged, and he was determined to prove himself.\n<BR/><BR/>\nTarthen stole Ebonchill from its new owner, taking great care to cover up evidence of his crime. In secret, he practiced with the greatstaff and learned to wield its extraordinary energies. \n<BR/><BR/>\nOnly a handful of Tarthen's most trusted Tirisgarde allies knew of his theft. They alone witnessed him bending Ebonchill's magics to his will, and they were in awe of the power at his fingertips. \n<BR/><BR/>\nOnce he was confident he had mastered Ebonchill, Tarthen set out to do what no other Tirisgarde had thus far managed--he would defeat Aegwynn and forever etch his name in the histories.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Seven</H2>\n<HR/>\n<P>\nAn excerpt from a missive sent to the Council of Tirisfal:\n<BR/><BR/>\n\"We have studied the residual magics at the battle site. Here is our assessment of what transpired.\n<BR/><BR/>\n\"Tarthen confronted Aegwynn in Stranglethorn Vale. In terms of the power used by the two magi, the duel that ensued was one of the greatest to have ever occurred between a Tirisgarde and the renegade Guardian. But it was also one of the shortest. \n<BR/><BR/>", "\"Tarthen bore Ebonchill in battle--the greatstaff reported stolen some months ago. When he unleashed the weapon's stored power on Aegwynn, she immediately turned the energies back on him with a counterspell. A storm of frost magic surged over Tarthen, encasing him in a layer of diamond-hard ice.\n<BR/><BR/>\n\"Despite the hot weather in the region, Tarthen was still frozen solid when we found him. It took considerable effort to thaw his corpse and free Ebonchill from his lifeless hand.\"\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Eight</H2>\n<HR/>\n<P>\nThe Council of Tirisfal magi who recovered Ebonchill returned the greatstaff to its owner. Over the following years, the tradition of handing down the weapon from master to apprentice continued. Many of these magi used Ebonchill to protect Azeroth from demons, but not the human named Arrexis.\n<BR/><BR/>\nArrexis was a lover of knowledge. For days on end, he would lock himself in his personal archives, poring over ancient tomes and scrolls. When Ebonchill passed to him, he decided to study the greatstaff rather than wield it in battle. Arrexis knew well the weapon's history and deadly potential. \n<BR/><BR/>", "From his examinations, Arrexis believed that he could employ Ebonchill as a catalyst to power great spells--feats of magic that normally only a Guardian would be capable of. Over time, he harnessed the weapon's energies and used them to research new types of warding spells.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Nine</H2>\n<HR/>\n<P>\nArrexis lived in a time of upheaval and turmoil for the Council of Tirisfal. The current Guardian was named Medivh, and he was the son of Aegwynn. Like his rebellious mother, he shunned the council and largely kept to himself. \n<BR/><BR/>\nUnbeknownst to the council and the rest of the world, a great evil stirred in Medivh's soul. Sargeras, leader of the Burning Legion, had possessed the Guardian.\n<BR/><BR/>\nDue to Sargeras's manipulation, Medivh forged a pact with the orcish Horde and began paving the way for its invasion of Azeroth. To prevent the Council of Tirisfal from meddling in his affairs, the darkened Guardian secretly assassinated some of its members.\n<BR/><BR/>\nMedivh's gaze soon fell upon Arrexis and Ebonchill.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Ten</H2>\n<HR/>\n<P>\nIn pursuit of his studies, Arrexis gathered his apprentice magi and established a research camp near Medivh's domain, the tower of Karazhan. The structure was built atop a nexus of potent ley lines. The energies that coursed through Karazhan sometimes warped reality in the region.\n<BR/><BR/>\nArrexis and his followers experimented with their warding magics outside Karazhan, attempting to neutralize the tower's strange powers. The records indicate that Guardian Medivh visited the magi at this time and offered his advice. He suggested that Arrexis could apply his warding spellwork in new ways, specifically to prevent demons from clawing into the world.\n<BR/><BR/>\nThough some members of the Council of Tirisfal distrusted him, Arrexis did not. He welcomed Medivh's support. \n<BR/><BR/>\nArrexis's trusting nature would be his downfall.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Ebonchill, Part Eleven</H2>\n<HR/>\n<P>\nNo one knows for sure what Medivh did during his visit with Arrexis. The details are shrouded in mystery and hearsay. Some rumors claim that the Guardian altered Ebonchill so that it would disrupt Arrexis's warding spells and destroy the venerated mage. \n<BR/><BR/>\nWhatever the truth, it is known that Arrexis heeded Medivh's advice. The elderly mage and his followers conducted a great ritual to protect an area from demonic incursions. The spell was only meant to be a test, but it had disastrous consequences.\n<BR/><BR/>", "When the magi began their casting, they inadvertently opened a path between Azeroth and the realm of demons, the Twisting Nether. Arrexis and all of his followers were ripped through the gateway and were never seen again. One account states that within the Twisting Nether, a handful of demons fell upon the shocked magi and slaughtered them to the last.\n<BR/><BR/>\nThe demons were led by an eredar known as Balaadur. He took Ebonchill as a trophy of his bloody victory, and the ancient tradition of passing the greatstaff from master to apprentice died alongside Arrexis and his doomed protege.\n</P>\n</BODY></HTML>", "<HTML><BODY>\n<H2 align=\"center\">Note from the Author</H2>\n<HR/>\n<P>\nResearch efforts press on! There's more information to be uncovered in these texts. The only thing that can hold me back is time!\n<BR/><BR/>\nCome back after further research has been completed and I will continue to expand this tome.\n</P>\n<BR/>\n<P align=\"right\">\n- Head Researcher Edirah\n</P>\n</BODY></HTML>" },
    ["item_archmage_khadgar_of_the_kirin_tor"] = { "Archmage Khadgar of the Kirin Tor\n\nFormer apprentice of Medivh. Supreme Commander of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.\n\nNever did one so selflessly delve into the dark heart of magic and warfare. We wish you well, bold wanderer. Wherever you are.\n\n- Antonidas - Archmage of Dalaran" },
    ["item_arellas_fireleaf"] = { "Arellas Fireleaf\nHigh Wizard of the Scarlet Crusade\nCitizen of Quel'Thalas\nLocked in eternal combat with the Necromancer Diesalven" },
    ["item_arthorns_research"] = { "Since your departure from the Evergrove, I've continued my studies of the Book of the Raven and I've discovered some information that will help you defeat the raven god.\n\nFreeing the spirits has bound them to you, so I expect they will freely offer their assistance in the fight against the raven god.\n\nWhen you first unleash the spirits, they will be dormant, as they have been for centuries. Using your heal-over-time spells, you can infuse them with energy, bringing them to life and gaining their aid in combat. When the magic fades, they will return to their slumber.\n\nWhat follows is a collection of my notes on each bird spirit:", "The Falcon Spirit\n\nThe spirit of the falcon is imbued with incredible speed and agility, highly regarded among the arakkoa for its keen hunting skills. It will lend you a measure of its speed in spellcasting and melee combat if you energize the spirit with a heal-over-time spell.", "The Eagle Spirit\n\nArakkoa tradition holds that the eagle spirit was not as fast as its falcon brother, but possessed the greatest skill in the hunt. The eagle spirit will use its skills against your enemies if you use a heal-over-time spell to awaken it from its slumber.\n\n.", "The Hawk Spirit\n\nThe tablet speaks highly of the hawk, as though he might have once been in league with the raven. An ancient arakkoa symbol for vengeance, the hawk spirit was often invoked by victims of wrongdoing. Using a heal-over-time spell to awaken the spirit will allow you to share in its power, damaging those who do harm to you." },
    ["item_assassination_note"] = { "This remnant from the Second War serves as a stirring reminder of just how perilously close the Horde came to conquering Ironforge Mountain." },
    ["item_attention_geists"] = { "I warned the lot of you that the next campaign on which I spent more time cleaning my boots than kicking infants, heads would roll! Dung cleanup shifts are henceforth doubled in length and number for all geists!\n\n--Instructor Razuvious" },
    ["item_avarice"] = { "Avarice.\n\nThis medallion bestows the wielder authority over the Catacombs Ward. There let those afflicted with this burden be sealed away until long after the time they believed they would be remembered. \n\nLet them fade away to be forgotten, the memory of their \"great deeds\" be measured against the unending weight of eternity." },
    ["item_baelogs_journal"] = { "I have found a method to enter the Chamber of Khaz'mul!\n\nTake the Medallion of Gni'kiv from my chest.\n\nDefeat the trogg Revelosh in the chamber before the map room and retrieve the Shaft of Tsol.\n\nJoin the medallion and the shaft into the Staff of Prehistoria.\n\nUse the staff in the map room to unlock the door to the Chamber of Khaz'mul.\n\nDo these things, and the chamber will be yours!\n-Baelog" },
    ["item_barely_readable_diary"] = { "Pa set me taking care of Ol' Bess again. I think he likes watching her try to kick me to pieces. It's not my fault that she doesn't like me as much as the others - it was only the once that I ate the apple intended for her. I don't even know how she knew." },
    ["item_bathrahs_parchment"] = { "Below you will find that which is needed for my spell to summon the great Cyclonian. May fortune go with you.\n\n--Bath'rah the Windwatcher", "Liferoot:\n\nThis may be gathered from the wilderness, or gained from the Withervine Beasts of Dustwallow Marsh. It's power will be necessary to draw the life essence of Cyclonian to this world.", "Bloodscalp Tusks:\n\nThe tusks of the Bloodscalp Trolls in Stranglethorn Vale have a rare quality. The depravation of the Bloodscalps is concentrated in their tusks, and if ground into powder their vile powers may be unleashed.", "Essence of the Exile:\n\nThis essence is gained through the fusion of the three charms of the elemental exiles of the Arathi Highlands. Gather Thundering, Burning and Cresting Charms from the elementals, then place eight of each in my cauldron.\n\nFrom the charms, the essence of the exile will form." },
    ["item_bear_witness_the_watchers_code"] = { "Bear Witness: The Watcher's Code\n\nFirst Verse\n\nThe first virtue will come naturally to the denizens of Bastion. Compassion for what was, is, and will be. \n\nThe soul knows itself, and its deeds, though it is with a gaze of compassion that the Kyrian will know them.\n\nForgive small slights, and give praise to the great sacrifices.\n\n<The scroll continues on for fifty-seven more verses.>" },
    ["item_beginnings_of_the_undead_threat"] = { "The undead's beginnings upon Azeroth did not truly begin with the corruption of Prince Arthas-it began long before that event. The events that brought downfall of Lordaeron were long set in motion before that point; it began with the coming of the orcish clans and the Burning Legion.", "The orcs of Draenor (the world which they originally came from) were noble and shamanistic. They were powerful warriors, strong of body and will. It was for these reasons that the Burning Legion sought them out. Kil'jaeden, a demon of great power among the Legion, wished to enslave the orcish clans and use them as his army against the worlds the Burning Legion had yet to conquer.", "Kil'jaeden came to the leader of the clans, a powerful shaman named Ner'zhul. He promised Ner'zhul untold mystical power and knowledge if he made a pact with the demon that would enslave the clans to the Burning Legion. This pact sealed not only their fate, but that of their world forever.", "As time passed, Ner'zhul realized the fate of the clans at the hands of the Burning Legion, and the orc shaman began to defy Kil'jaeden. The demon, angered by Ner'zhul, turned to the shaman's own apprentice, Gul'dan, who was far more corruptible than Ner'zhul.", "It was Gul'dan who was responsible for the decline of shamanism throughout the clans. The promise of power and control over one's enemies made his offers even more tempting. With Kil'jaeden's help, Gul'dan began his manipulation of the clans. The orcs, once noble, became corrupt, mindless savages. With the introduction of demon blood into their bodies, the orcs were even more ruthless and barbaric.", "Even though Kil'jaeden had corrupted Gul'dan after his failure with Ner'zhul, Kil'jaeden hated the shaman and vowed to enforce their original pact. Kil'jaeden captured Ner'zhul and began an incredibly slow physical torture on the shaman. While Ner'zhul begged for death, Kil'jaeden reminded Ner'zhul that their original pact was still binding. Kil'jaeden killed the orc, but only physically. Kil'jaeden held the orc shaman's spirit fast before it could find its way to the Twisting Nether.", "Kil'jaeden placed Ner'zhul's spirit within a block of ice gathered from the Twisting Nether. While it was trapped within the ice, he infused into it even more power. The loss of his body and the introduction of such incredible power was the defining line in Ner'zhul's transformation.", "Kil'jaeden hurled the block of ice through dimensions back to Azeroth, where it landed in the continent of Northrend, introducing this great evil to our world. Ner'zhul was gone forever; in his place was a throne of ice and hatred. The once respected shaman leader had become the incredibly powerful Lich King.", "Because Kil'jaeden did not trust the Lich King, he sent his dread lords to watch over the spirit and ensure that the Lich King followed his orders. The vampiric servants came to Azeroth willingly, drawn to the destruction and power of the Lich King and the potential genocide of a planet's entire race.", "Over a decade passed. During this time, the Lich King used his vast powers to gain control over the minds of the creatures of Northrend, whom he commanded to erect a great citadel over his frozen throne. Now that all of Northrend was under his domination, the Lich King knew he needed to begin his infiltration of Lordaeron. Trapped within the ice, the former orc shaman began seeking more minds to manipulate and control. His call reached out across the continents.", "The Lich King's summons did not go unnoticed, especially by a small handful of powerful individuals. Among them was the Archmage Kel'Thuzad, who was a powerful member of the ruling body of Dalaran, the Kirin Tor. His pursuit of all types of magic violated the Kirin Tor's policies against learning dark magics. Kel'Thuzad abandoned the Kirin Tor and all his ties to conventional thought and vowed to learn as much as he could from the Lich King.", "A pact was struck between the two. Kel'Thuzad would receive immortality and immense power in return for servitude to the Lich King. Kel'Thuzad's first task was to use his wealth and influence in Lordaeron to found the Cult of the Damned. The Cult promised equality and eternal life to all its members as long as they swore an oath to Ner'zhul, the god of the Cult of the Damned.", "Ner'zhul then created artifacts that were designed to spread the plague among the human civilizations of Lordaeron. He gave them to Kel'Thuzad, and ordered the wizard to spread them across the land. His Cult followers were to protect the artifacts at all costs.", "Once in place, the plague began to seep into the land and affect its ignorant citizens. As Kel'Thuzad watched, the Lich King's army grew quickly and he soon gained control over large portions of the land. This army became known as the Scourge, for its sole purpose was to scour humanity from all of Azeroth." },
    ["item_belamoores_research_journal"] = { "Kegan Darkmar, leader of the small group of undead who came to us in search of asylum from their \"brethren,\" defies our common attitudes toward his kind. His skin may be rotting and blood may have long stopped flowing through his veins, but he acts very nobly and seems to care more for his compatriots' safety than his own.\n\nIndeed, there is a humanity within him that, I confess, I sometimes see lacking in the humans around me.", "But why do I mention this? I do so to give credence to what I am about to write, for these words came from Kegan's lips and it is my hope that my colleagues will, upon reading this journal, know why I believe what he said:\n\n\"Remnants of the Old Gods still linger in the deep hollows of the world. New forces seek to harness that ancient power, and those who succeed will have a terrible weapon against their enemies.\"", "That is what Kegan uttered as he handed his bloodstone pendant to me, and there was fear, and maybe reverence, in his eyes as he did so. And as his hands met with mine they lingered, as if reluctant to give up the pendant. Revulsion swept through me, yet to this day I know not if I reviled against his dead flesh pressed to mine, or if the pendant itself made my skin crawl.\n\nFor I felt a power within it. A deep, hidden, hungry power. And one yearning for release.", "Although my colleagues in Dalaran were cautious to study the bloodstones that Kegan and his followers brought with them, instead quarantining the four refugees and leaving the bloodstones on their persons, the sincerity of Kegan obliged me to study his bloodstone pendant.", "My hopes were to verify for my colleagues that this type of stone did possess magical properties, and if we wizards of Dalaran did not wish to exploit the power of bloodstones, we should at the least learn their properties, since our foes may one day use them against us.\n\nAnd so my studies began.", "I started my tests with the assumption that bloodstone was a type of rock, like quartz or obsidian. So I began a series of procedures to determine: what minerals were contained within bloodstone, what forces were applied to produce its color and hardness, and other properties common to rocks and ore. But the bloodstone pendant, to my frustration, did not react to my procedures as would normal ore.", "In fact, it often acted in precisely the opposite fashion as expected! It was almost as if the pendant was deliberately fouling my experiments.\n\nLike it was thinking, and alive.\n\nAngered but not discouraged, I switched from assuming the pendant was an inert piece of rock, to assuming it was a living thing.\n\nBut again, I failed.", "None of my new tests brought to light any revelations of the origin of bloodstone. At the time the only riddle I solved was that bloodstone was neither living, nor dead!\n\nBut it was then, at the brink of failure, that a breakthrough was made. My latest test involved a glass beaker whose brim was chipped, leaving a small, jagged space along its edge. When the test was over, again revealing nothing, I went to clean my worktable and cut myself on the beaker.", "The cut was not deep but nevertheless bled fiercely. Before I could wrap my injured finger in a bandage, a good deal of my blood had spilled on my worktable.\n\nAnd as I was cleaning up this new mess, I noticed the strangest thing...", "The blood that had spilled near the bloodstone pendant was slowly moving toward the piece of jewelry, as if gravity had somehow bent itself toward the bloodstone. The blood that touched the pendant seemed to disappear, and the red color of the stone deepened as it drank more of my blood.", "After seeing this my head grew light, perhaps from my recent injury (though I did not believe I had lost that much blood) or perhaps because I had finally, after so much frustration, uncovered one of the bloodstone's properties. I reached behind me for my work stool and sat down, pondering. Thoughts and questions raced through my head, dizzying and threatening to topple me.\n\nDoes bloodstone drink blood? Does it crave blood? Does it attract blood?", "Or, is bloodstone made of blood? And if so, then whose blood? Mine? The blood of any human? Any animal?\n\nOr maybe bloodstone is the blood of some unknown thing, the very thing that Kegan had both feared and revered when he handed me his pendant.\n\nThat is the question that must be answered. It is the key.", "Fire rekindled within me, I then dove back into my experiments. This time I made no assumptions, methodically performing every test at my disposal. This increased my required efforts tremendously, but I would be more likely to make discoveries.\n\nAnd, although my lab here is small and I have no subordinates to spare to aid, I did find one more intriguing quality of bloodstone...", "In addition to blood, there are elemental forces fused within the stone. Fire, water, thunder and rock are mixed with the blood (but again, the blood of what?), and although this mixture is outwardly inert, all these forces seem to rage inwardly against each other. So many more questions were then raised about this amazing, and foreboding material.", "But to answer those questions, more studies and experiments must be performed on the pendant, and I fear that the Lordamere Interment Camp cannot marshal the manpower nor the equipment for the task. So I sent the bloodstone pendant with a courier to Dalaran with specific instructions on how to test it, so they may avoid my earlier frustrations.", "As I waited for the results of these tests, I spent my time speaking to Kegan. Although I constantly pressed him for what he knew about bloodstones, he never told me more than what he said the day he gave me his pendant. And he did not often speak of his time within the fold of what he called \"the Forsaken,\" which is the name he calls his clan of undead.", "But Kegan was very eager to speak on other subjects, particularly his time growing up in Lordaeron before its fall.\n\nHe still holds much love for that lost kingdom, even though it is now ruined, and dead.\n\nMy growing fondness for Kegan gave me patience as I waited for my test results.", "But after weeks of no news my patience faltered, and upon further inquires to Dalaran I learned that the bloodstone never reached my colleagues. My courier was somehow lost on the way, and the bloodstone pendant was lost with him!\n\nThis is grave news, for although Kegan and his followers still have bloodstone specimens with which we may experiment, I fear the pendant may fall into unsavory hands.", "I have sent another messenger to Dalaran, and hear that even now they are scouring for the pendant, in the ruins outside our protective sphere.\n\nI only hope we're not too late." },
    ["item_beldugurs_note"] = { "The Star of Xil'yeh\n\nAn ogre in Alterac, Grel'borg the Miser, was the last known owner of this gem, whispered to empower its owner with the ability to commune with other worlds. Sources tell us Grelborg wanders the Ruins of Alterac in the Alterac Mountains, searching the rubble and debris for more relics.", "The Hand of Dagun\n\nDagun is a creature of the deep waters, worshipped by Murlocs in Dustwallow Marsh. They entice him to the surface with a special sea kelp, enchanted by their shamans. Hunt the Murlocs, gather their enchanted kelp, then place it on the Murloc's altar. Dagun will come, and you will be waiting.\n\nI want that hand.", "The Legacy Heart\n\nOld texts say that he who posseses the Legacy Heart fears not the grave. Perhaps this is true, for the owner of the heart, the troll Mogh, is known as Mogh the Undying. A witchdoctor of the Skullsplitter tribe, Mogh dwells in Stranglethorn in the Ruins of Zul'Mamwe.", "Bring me these items, the Star, the Hand and the Heart, and I will give you a copy of the Yagyin Digest.\n\n-The Keeper" },
    ["item_berards_journal"] = { "Through study of various fossilized creatures I have deduced that in ancient times, a great plague swept through the waters of Lake Lordamere. What caused this? We might never know. But the rate of contamination appears to be extremely high based on dense concentrations of remains distributed across the lake bed.", "In an attempt to uncover the past, I have begun to examine the creatures of the present in hopes of finding the missing clue to this mystery. The Lake Skulkers and Lake Creepers are ancient beasts who inhabit the islands in the center of Lake Lordamere. There is a moss which grows on them that resembles trace materials on some of the fossils. More research needs to be done before I can speculate as to what this connection means.", "While trying to collect moss samples I came across the scene of a bloody battle. The Vile Fin tribe of Murlocs had come under siege by a marauding band of Gnolls. There were both Gnoll and Murloc corpses littering the battlefield. As I passed a mangled Murloc body I noticed a strange hardened tumor protruding from the wound. As I began to study the tumor it became clear it held similar properties to the moss I was collecting. Unfortunately, I could find no other tumors besides the one." },
    ["item_beyond_the_dark_portal"] = { "Only a few months after Nethergarde's completion, the energies of the dark portal coalesced and opened up a new gateway to Draenor. The remaining orc clans, under the leadership of the elder shaman, Ner'zhul, charged forth into Azeroth once again. Intent on stealing a number of magical artifacts that would increase Ner'zhul's power, the orcs planned to open up new portals in Draenor that would allow them to escape their doomed red world forever.", "Convinced that Ner'zhul was planning a new offensive against the Alliance, King Terenas of Lordaeron sent his armies into Draenor to end the orcish threat once and for all. Led by Khadgar and General Turalyon, the Alliance forces clashed with the orcs across the burning landscape. Even with the aid of the elven Ranger Alleria, the dwarf Kurdran and the veteran soldier Danath, Khadgar was unable to prevent Ner'zhul from opening his portals to other worlds.", "The tremendous magical storms caused by the portals' converging energies began to tear the ravaged world apart. Ner'zhul, followed only by his most trusted servants, managed to escape through one of the portals as Khadgar fought desperately to return his comrades to Azeroth. Realizing that they would be trapped on the dying world, Khadgar and his companions selflessly decided to destroy the dark portal so that Azeroth would not be harmed by Draenor's violent destruction.", "By all accounts, the heroes were successful in destroying the portal and saving Azeroth - but whether or not they escaped the death throes of Draenor remains to be seen." },
    ["item_blood_elf_plans"] = { "Survey the extent of the islands and report back.$B$BRemember, do not get caught!$B$BDo not fail me, Candress!$B$BS." },
    ["item_blood_oath_of_the_horde"] = { "Lok'tar ogar! Victory or death - it is these words that bind me to the Horde. For they are the most sacred and fundamental of truths to any warrior of the Horde.$B$BI give my flesh and blood freely to the Warchief. I am the instrument of my Warchief's desire. I am a weapon of my Warchief's command.$B$BFrom this moment until the end of days I live and die - For the Horde!" },
    ["item_bloodsail_orders"] = { "Bloodsail Orders\n\nPay attention to these here words closely, me hearties, for we only got one shot at Booty Bay.\n\nI've sent Ol' Dunken scouting to the north and told him to wait for the signal.\n\nThe Damsel's Luck will drop anchor off the southern cape for purposes of supply. Captain Stillwater, the little shorty, is to have his crew prepare to haul up all the plundered loot. I'm sure Brutus, that blockhead, will be on top of things.", "I want Captain Keelhaul to bring The Riptide up to shore from the southeast. We'll send his crew in on foot when the signal is given.\n\nThat big lug, Salthoof, can take the men in swinging. I want the black spot placed on Revilgaz and Seahorn. Send 'em right to the bottom of the sea for all I care.\n\nYou blokes are responsible for salvaging anything that might be of use for our little project with VanCleef in the Deadmines.", "I'll give the order for Ironpatch to fire the guns. The artillery barrage will keep any Blackwater ships from leaving or entering the port.\n\nAfter The Crimson Veil has unloaded her guns, I'll bring her alongside The Riptide for support and provide reserves as needed.\n\nOnce Salthoof and his boys have fired the town and all hands are on deck, we set sail and give the Bay one more shelling from the Savage Coast for good measure.\n\n--Fleet-Master Firallon" },
    ["item_bloodstained_journal"] = { "(Only portions of the journal are legible through the stains.)\n\nUldaman, Day 3\n\nI cannot believe how foolish I was. To be blind-sided by the foul Shadowforge dwarves was a novice's feat. My wounds heal slowly; surely I am poisoned. I feel my energy sap away. I must scout ahead nonetheless...\n\n...make matters worse, the necklace the gnome made for me has been shattered! Three of the largest gems set into it have been lost. I must find them; without them the necklace is powerless...", "Uldaman, Day 4\n\n...first clue revealed itself deep within Uldaman, as one of the most savage troggs I have ever seen was brandishing about a large sapphire -- one I wager that would fit perfectly into the necklace. I overheard one of the Shadowforge dwarves mention the beasts name: Grimlok. The cadre of guardians this brute Grimlok has, however...", "Uldaman, Day 5\n\n...the trogg, then taking the topaz from his slain \"brethren\", marched into the side cave near the front of the hall...\n\n...quick to place the topaz in a large, conspicuous urn toward the back of the chamber...\n\n...of all things, dwarves! Three of them, to boot. They're barricaded against the troggs currently. Calling to them would have been a call for suicide, lest I be overran by the foul troggs in my weakened state. Once I know the third gem, however, I shall...", "Uldaman, Day 6\n\n...so very hungry. I am out of supplies, and would consider moldy bread to be a feast at this point. I witnessed a trogg's head turn into a juicy steak right in front of my very eyes...", "Uldaman, Day 7\n\n...last chance at redemtion for my failures. I believe the ruby is in the last barricaded area the dwarves have against the troggs. Their battles, no doubt over the gems and the other artifacts from this site, rage continuously. It would be just like those vile dwarves to hide it somewhere there. Regardless, I must make a move one way or another. Perhaps a mad dash to the surface is the best course..." },
    ["item_bloodvalors_notes"] = { "$N,\n\nThe creation of the blood-tempered ranseur requires a variety of rare and volatile materials, resulting in a fearsome weapon of superior craftsmanship. I will list the materials in order from easiest to most difficult to obtain.\n\nDo not forget that you must also secure your Blood Knight insignia before the materials will be accepted and the forging process can begin.", "Blood of the wrathful - In order to properly temper the metal of your weapon, it must be quenched in the blood of the wrathful. Though the blood of most demons holds a substantial amount of power, common blood is not sufficient for the forging of your ranseur.\n\nDiscreet inquiries with the warlocks of Orgrimmar have proven helpful in locating a supply of the blood. The Searing Blade cultists within Ragefire Chasm possess an orb filled with the kind of blood we'll need for your weapon. I am told the orb is guarded by an orc calling himself Jergosh the Invoker.\n\nExercise caution, as in all your dealings with demonic powers. You can never tell what might happen when handling such a powerful substance.", "Crate of bloodforged ingots - On its own, steel is a fine metal, but a weapon forged from it is unremarkable. Bloodforged ingots represent a superior material created in a process that is a well-kept secret. Rumor has it that any smith bold enough to handle and work the metal becomes cursed, but our craftsmen have proven this false.\n\nThe metal's reputation increases its scarcity, but the Forsaken have sent word that a supply may exist within Shadowfang Keep. A skilled smith by the name of Landen Stilwell grew curious enough to smuggle a crate of ingots into the keep. It is not known where Stilwell keeps his stash, but our informant tells us the smith is being held prisoner in the keep's dungeon. Use any means at your disposal to obtain the ingots.", "A corrupted kor gem - The magisters' tomes record that these gems are used by some spell casters to hold energy for their magics, making them even deadlier. Although purified versions of the gem can be safely used by journeyman spellcasters, they are too weak for our purposes.\n\nIn the caves of Blackfathom Deeps, naga spellcasters have imbued kor gems with their own dark powers, augmenting them in a way that makes them perfect for use in your ranseur. Slay them mercilessly until you have secured the gem you will need.", "The insignia that you will wear as an adept was last carried by a brave and fearless Blood Knight from the Dawnstar family. His exemplary service is a good omen for your own life in the order.\n\nBlood Knight Dawnstar led a daring, but unsuccessful attack on the Scourge stronghold of Deatholme. His body rests where he died, locked in combat with our greatest foes. Find him, $N, and return his insignia to me. Your success will bring honor to him, to you, and to all true Blood Knights." },
    ["item_blue_punch_card"] = { "Do NOT let this information fall into enemy hands!\n\n01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010" },
    ["item_bolvars_decree"] = { "Solomon, The carrier of this decree has been granted official status as an acting deputy of Stormwind. You may use $g him:her; to find proof of the black dragonflight's involvement with the Blackrock orcs. Should such proof be found, this deputy shall return said proof to me in Stormwind, at which time I shall release the order to dispense sufficient military force to aid Lakeshire. Regards, Highlord Bolvar Fordragon" },
    ["item_bonegrips_note"] = { "The Star of Xil'yeh\n\nGrel'borg the Miser has the Star. He is a greedy ogre who spends his days in the Alterac Mountains, in the Ruins of Alterac, searching for baubles. Most of his collection is useless, but one item, the Star of Xil'yeh, has valuable properties.", "The Hand of Dagun\n\nAncient texts claim that claws of Dagun excrete a poison that does not kill his prey, but mutates it into something else -- a member of the old races. Its value to us is unquestioned.\n\nDagun lives in the deep sea, but is regularly enticed to the surface by a tribe of Mirefin Murlocs in Dustwallow Marsh. Their oracles summon him with an enchanted sea kelp. If you kill enough oracles you'll find the kelp. Then place it on the Murloc altar, and Dagun will come.", "The Legacy Heart\n\nMogh the Undying is a troll witchdoctor in Stranglethorn. And he posseses the Legacy Heart, said to stave off death to those who can unlock its secrets. You will find Mogh in the Ruins of Zul'Mamwe. Defeat him, if you can, and bring me the Legacy Heart.", "Bring me these three items, the Star, and Hand and the Heart, and Yagyin's Digest will be yours.\n\n-G.B." },
    ["item_book_from_svens_farm"] = { "The terror of these past few weeks is almost more than I can bear; yet, I feel that by writing down that which I've seen I will somehow be comforted. So I do it, and it is the only comfort I have these bleak days.", "It began with the finding of that cursed scythe in Roland's Doom. Before the Scythe, the terrors of this place seemed as tame as Northshire Valley.\n\nBut ever since I found the haft of the Scythe jutting from that pile of rubble in the mine and, curse me, pulled it free, Roland's Doom became a place of vile death!", "After the Scythe was freed, They came at us from everywhere, clawing from hidden holes at our feet and dropping upon us from silent perches above. Half our men fell in those first panicked minutes. The rest, including myself, tried to flee. As I ran I saw so many of my brothers taken by tooth and claw, heard so many screams cut short or gurgle to silence.", "I can only guess why I survived that night. I have always been cautious, always quick to flinch from jabs and leap free of pitfalls. My nickname comes from this trait. So perhaps it was just that knack for caution that saved me...\n\nOr maybe it was the Scythe I pulled from the rubble. It cannot be the Scythe itself, for I lost it during my frantic flight. But if it was I who brought the Worgen to Duskwood, then perhaps the Worgen afforded me a rare courtesy. Curse them.", "After surviving the flight from Roland's Doom, I hid within a barn owned by a man named Sven. I spent a few days in the barn, and such horror lingered with me that I never once made myself known to Sven or his family. But from what I saw from my hiding place, I knew these farmers were quite decent folk. Had I stepped from my concealment I think they would have taken me in, but trust is hard for me. Harder still after that shock in the mine.\n\nSo I remained hidden.", "<The rest of the book is blank>" },
    ["item_boulderfist_plans"] = { "Stupid,\n\nFind food. Blue taste good. Lantresor say it ok. Bring food back to Lump. Lump eat first then stupid eat. Ok? Go fast or Lump eat you.\n\n-Lump" },
    ["item_brazier_of_invocation_users_manual"] = { "BRAZIER OF INVOCATION: USER'S MANUAL Where to find Haunted Loci INTRODUCTION Contained within these pages are the locations of the fallen and corrupted spirits and souls involved in the Lord Valthalak's Amulet Incident. Though you have already saved these former companions of mine, it would be my conjecture that repugnant echoes of the evil that once twisted their spirits still linger at those haunted loci. Such was the malevolent power of Lord Valthalak's spirit. Additionally, the brazier can be used to summon forth Lord Valathalak, though as before, extreme caution should be taken in doing so.", "INTRODUCTION, continued... The brazier itself functions just as the Brazier of Beckoning did. Simply place it within range of any of the five haunted loci and it will invoke the spirits of the dead. As a side note, because I know that you'll be interested in knowing, the Banner of Provocation can be used in similar fashion at the arena in Blackrock Depths. Be sure to teach Theldren and his goons a lesson for me every time you get a chance when you're there. Read on should you desire further enlightment.", "ISALIEN Night Elven Priestess of the Moon When Isalien decided to take her leave of the company, she did so with the intention of making a pilgrimage to Dire Maul, the fallen, ancestral night elven city once known as Eldre'Thalas. Therein still stands a library of great knowledge, a sanctum that a small number of night elves have been able to hold back the tide from. She was intent upon finding answers both to her heritage and possibly concerning the amulet pieces. It should be noted that she was also a good friend of Falrin Treeshaper.", "ISALIEN, continued... Unfortunately, as she and her companion hippogryph, Empyrean, were entering the city, they were assailed by Alzzin the Wildshaper and his minions. There she fell, never to rise again. Perhaps it is for the best that Isalien never unlocked any further secrets from the evil magic that Lord Valthalak put into containing a portion of his essence in the amulet. The open-aired chamber where Alzzin resides is one of these haunted loci.", "MOR GRAYHOOF Tauren Druid and First to Fall Mor Grayhoof was ever a stalwart and trusted companion within The Veiled Blade. It is unfortunate that he was the first to fall to Lord Valthalak's evil minions. As we fled from Valthalak, we were being pursued by a veritable army of his spectral assassins and stalkers. The flight from Blackrock Spire was chaotic, to say the least. Unfortunately along the way, Mor somehow lost his footing, though I suspect that he was pushed. In any case, he fell down in to the recesses of the lower portion of the spire.", "MOR GRAYHOOF, continued... Later, we discovered that Mor had actually survived the fall. But there was to be no happy ending for my good friend; he was taken prisoner by the trolls of Tazz'Alaor. Not long after, as he was being tortured by War Master Voone, a group of Valthalak's assassins jumped in and finished the job. Should you seek to raise the echo of Mor Grayhoof's spirit, War Master Voone's chamber is a haunted location.", "JARIEN AND SOTHOS Siblings and would-be members of the Scarlet Crusade Jarien and Sothos were two of the most intolerant people that I knew. Yet their skills as combatants were exceptional, and they came from money, which I suppose is why Anthion, the leader of The Veiled Blade, kept them on. The siblings eventually found themselves enamored with the teachings and philosophy of the Scarlet Crusade. They had always exhibited a certain zeal in vanquishing any of the Scourge that we ran across in our travels, and it was suspected that their family had ties to the organization.", "JARIEN AND SOTHOS, continued... So it was that they found themselves facing the trials that are required of those that seek to join the Crusade. Of particular interest to them was a position of knighthood within the ranks; something that required more difficult testing apparently. For it was later discovered that Sothos actually failed his final test. Jarien would not have it though, and in open defiance she insisted that he be able to join her amongst the knights. From what we have gathered, Grand Crusader Dathrohan slew them both right on the spot in the middle of his chambers. Thus it is that another of these haunted loci is The Crimson Throne inside The Scarlet Bastion at Stratholme.", "KORMOK Two-Headed Ogre Necromancer What can be said about Kormok? He was a two-headed ogre of the caster variety who didn't used to be all that bad. When we first took him into the fold it was as a prisoner on some job we'd accepted in Burning Steppes. He proved himself invaluable in helping us to get out of a sticky situation we fell into there, however, and so he came on as one of the company's premier mages. The odd thing about him though was the completely different nature of his two heads. One was always cheerful if not a little foolish, while the other was sly, calculating and had an almost dead look to its eyes. Kind of creepy really.", "KORMOK, continued... Later, through the course of our travels, Kormok became exposed to the necromantic side of magic. Unfortunately the creepy head exhibited an affinity for raising dead spirits, and took a perverse pleasure in it, especially in summoning forth the exiled spirits of Purgation Isle to do his bidding. After the company disbanded, Kormok enrolled at the Scholomance to further his 'education'. The spectral assassins found entrance to the school all too easy, and slew him right there in front of his new master, Ras Frostwhisper. This makes Ras Frostwhisper's chamber one of the haunted locations where the brazier can be successfully utilized.", "LORD VALTHALAK Draconid Noble and former General of Blackrock Spire Before General Drakkisath, there was Lord Valthalak, a draconid warlock of immense power. It is common for the leadership of the Spire to change hands, and unfortunately for us, we were going to play a part in the latest shift in power. We'd been commissioned by a goblin smuggler-wizard out of Booty Bay, Gremnik Rizzlesprang, to steal Valthalak's spellbook. We don't know if he wanted to study it or sell it (or both), and it doesn't matter now. What does matter is that we infiltrated the upper reaches of Blackrock Spire and slew Lord Valthalak in his lair. That's when the fun really began.", "LORD VALTHALAK, continued... We had no idea of the depths of Valthalak's magical knowledge where soul-manipulation was concerned, or we probably would never have taken on the job in the first place. But take it we did, and it proved to be the last job we ever would take. Having slain Lord Valthalak, and taken his spellbook, Kormok must have sensed something about his amulet. He insisted on taking it as his share of the loot, which quickly devolved into a heated argument, and almost a fight, over the thing. We didn't know at the time that the amulet actually housed a good portion of Valthalak's spirit; we found that out later, much to our displeasure.", "LORD VALTHALAK, continued... Splitting the amulet into pieces, we fled from the newly risen ghost of Valthalak, as well his army of spectral assassins. And the noise we made fighting over the amulet had roused a number of the Spire's remaining defenders! Almost all of us made it out of Blackrock and thought we were safe. But, even from the beyond, Valthalak sent his minions at us no matter where we hid. The Veiled Blade soon broke apart after that mission, and then we were really easy pickings. As you must know, this makes Lord Valthalak's abode, what is now The Beast's chamber in Blackrock Spire, the last of the haunted locations." },
    ["item_brazies_dictionary_of_devilish_draenei_damsels"] = { "Are your tastes more exotic? \nDo you desire someone a little out of this world? \nAre hooves your thing, but succubi a little too much for you?\n\nRead on, my friend...", "I'd just arrived off the boat to Azuremyst when I stopped a group of Draenei dames around the ripe young age of 230. They were laughing and having a great time. What luck, still on the docks and I'd found exactly the type of fun, energetic Draenei women I wanted to meet on this trip. \n\nAt first a bit anxious, I breathed deeply and reminded myself, \"they too are here in Azeroth on vacation, looking to meet new people and have a great time.\"\n\nSure enough, they were delighted to see one devilishly charming Gnome like myself in the Exodar. It even turned out we were both staying near the Vault of Lights. We exchanged deep, penetrating glances into each others eyes, promising to meet again near A'dal later that night.", "The next day, I met another beautiful Draenei woman - the gleam of her horns gave only the gentlest of glimpses into her refined tastes. I asked why she was visiting the Exodar, when in shock, she told me she wasn't visiting - she lived here. \n\nThe words I spoke to myself before returned to my mind: \n\n\"She is on vacation, looking to meet amazing people and have a great time.\"  \n\nI had it all wrong, she wasn't on vacation at all! Then suddenly, the grinding gears of my mind clicked:  I'd been claiming to myself that they were so receptive because they were on vacation. What a gnollish excuse! \n\nI'm a fun, interesting guy who any sensible minded girl would love to group with, on vacation or not! Now when I meet Draenei girls, I remind myself of the simple truth:\n\n\"She too is looking to meet people and have a great time.\"", "The following 497 pages of this dictionary consistent entirely of oddly angled pictures taken from a Super Snapper FX 2000." },
    ["item_brazies_document_on_dwarven_dates_in_dun_morogh"] = { "How to date a Dwarven woman:\n\n1. Ask her to buy you a drink." },
    ["item_brazies_guide_to_getting_good_with_gnomish_girls"] = { "\"Roleplaying\"\n\nGood roleplaying skills are essential. No Genius Gnomish gal wants a giant bore. Regale her with tales of your future cross-continental adventures:\n\n  \"You and me, babe, we're gonna fly to Kalimdor, etch our names into the side of Teldrassil and spend the rest of our lives swinging from the trees in Un'goro Crater.\"\n\n\"Storytelling\"\n\nShare stores of your exciting future together! The more implausible, the better. Nothing gets a Gnomish girl excited like an ambitious plan. It also makes for great conversation starters!\n\n  \"With our brilliant minds combined, we could retake Gnomeregan. ... why haven't we retaken Gnomeregan anyways?\"", "\"Teasing\"\n\nTeasing is the art of making fun of a woman in a humorous way. Be careful, you can easily go too far. Calling her a \"Goblin Ganking Gnat\" will leave you walking home wearing that Green Gordok Grog you just bought. Try something a bit more subtle. \n\nIf she acts childish and refuses to stop jumping onto tables in the middle of the bar try:\n\n\"I hear there's an opening for star entertainer at the Stormwind orphanage.\"\n\nIf she won't stop talking about herself playfully try:\n\n\"Where's your off switch?\"\n\nIMPORTANT NOTE: Gnomish girls do NOT have an off switch. Attempting to find it may result in the loss of life, limbs or wallet." },
    ["item_brazies_handbook_to_handling_human_hunnies"] = { "There's nothing like wooing the heart of a human girl. Infinitely forgiving, endlessly caring and fantastically fun, human girls have been the downfall of countless heroes throughout the ages. (See Chapter 3: \"Jaina Proudmoore and the men who loved her\")\n\nHowever, generation after generation has proven it takes something more than just money, looks or an epic suit of armor to attract the woman of your dreams. Not even the power of Gnomish invention can help you here. \n\nTo truly charm the heart of another, you should possess these qualities.\n\n* Be Fun & Friendly\n* Be a Challenge\n* Be a Man", "Be Fun & Friendly\n\nEver have at friend who shows up at your house and brings everybody down? Yep. Everyone does. Does he get invited back to the parties? Not unless he's bringing the ale. If you want to be an attractive person, live an attractive lifestyle. \n\nYou'll find that the more you enjoy socializing with others, the more they will enjoy socializing with you! \n\nThere's no faster way to ruin a girl's night than bringing in that needy, apologetic vibe. Let it go, embrace the fun and your confidence will soar.", "Be a Challenge\n\nToo many Gnomes these days walk with their head slung low, shuffling along sadly from tavern to tavern, hopelessly holding on these limiting beliefs that no human girl would ever want them. They rush into the tavern, shower her with compliments and free drinks, then go home dejected. \n\nWell, let me be the first to tell you, friend, when you give your self away so cheaply, you diminsh the value of your unique, exquisite personality. You've been told by society that you are not the prize, that women will never acknowledge you, that you must beg for love and attention.\n\nThey are wrong. Don't give your affection away so freely. Instead of asking yourself, \"Does she like me?\" ask yourself instead, \"Do I like her?\" \n\nChallenge her - show her you're looking for a girl who offers more than a pretty face. If she can't keep up with your life, move on. If she shows she's got something to offer, you're at the beginning of a beautiful thing.", "Be a Man\n\nIn an age where we've been banished from our homes, forced to fight for our very survival and faced down horrors never before known to Azeroth, you would think that the nature of manhood would be better understood. \n\nSadly, the art of masculinity has been lost, washed away in the glitz and glamor of battle. However, all is not lost! With practice and confidence, you can come back in touch with yourself. \n\nOnce you've met the human girl of your dreams and she's shown herself to be worthy of your affections:\n\n* Take the lead - show her everything that is beautiful about your world\n* Hold her hand - develop a close, affectionate relationship\n* Show respect - for yourself, for her and for the world around you\n\nAbove all:\n\n* Be responsible", "Troubleshooting\n\nWhile everything doesn't always go the way you expect, that's what make life unpredictable and exciting. However, there's a few tips to help you a long way in improving your life. Here's some common blunders:\n\n* Don't chase\n* Don't be needy\n* Don't get stuck on someone who dislikes you\n\nThese all stem from a core belief that women you must have the woman you're talking to right now. Break free - there's many women out there in this beautiful world and if one doesn't work out, let go. You'll find you become more attractive the less clingy you are." },
    ["item_brazies_notes_on_naughty_night_elves"] = { "Let's be honest. Since the end of the Third War, Night Elf girls have heard it all.  In fact, they'd already heard it all long before you or I was born. \n\nIf you want to engage the mind of a Night Elf girl, you're going to have to stand out. Sure, we've all heard the tales of Night Elf lasses dancing on mailboxes and stripping to pay for Nightsaber training. True or not, if you want to light that lovely lady's lips up with a smile, you gotta be unique, memorable and confident. \n\nStart off by showing that you're looking for more than a gal with looks. Sure, she can bounce, she can dance, but can she hold a decent conversation?  Does she even understand the proper use of a samophlange? Does she know how to have a fun time?\n\nThere's nothing worse than bringing a Night Elf to a party, only to watch her stand awkwardly by herself, breaking conversation only to lament the loss of her Highborne sister during the War of the Ancients." },
    ["item_brocks_list"] = { "Below is the list of students who obtained a Platinum Star grade at Brock's School of Mining and Surveying, earning them an Honorary Miner's Pick:\n\nMelia Stoneshaker\nBardin Ironband\nUmi Togglevolt\nRumi Togglevolt\nVorel Steelspire" },
    ["item_call_to_arms_announcement"] = { "To all able-bodied men and women:\n\nThe Scourge have returned and we must set aside our squabbles to face this threat. The Argent Dawn will turn away none who wish to take arms against the Scourge menace.\n\nThose who would defend our lands are mustering at Light's Hope Chapel in the Eastern Plaguelands. Together, we shall prevail.\n\nKeeper of the Rolls\nThe Argent Dawn" },
    ["item_calors_note"] = { "Master Carevin,\n\nThe bearer of this note has shown $g himself : herself; to be upstanding in the Light, capable of battling the undead and demons that plague the borders of Duskwood, and willing to join the Carevin family in their cause of Light.\n\nI would thereby suggest that you give this warrior of the Light further duties--perhaps to investigate some of the townsfolk that are under suspicion of succor to the enemies of the Light.\n\nYours faithfully,\nCalor" },
    ["item_captains_documents"] = { "The Bleeding Sparrow: Manifest\n\n(20) barrels rum. Destination: Theramore\n(50) sacks flour. Destination: Theramore\n(2) crates assorted gnome tools. Destination: Ratchet\n(30) bolts cotton cloth. Destination: Theramore\n(4) crates spices. Destination: Theramore\n(3) passengers. Destination: Theramore", "Captain,\n\nI wish you fortune in your journeys. Regrettably, fortune did not favor our first abduction attempt.\n\nWhen our team made contact with the target in the Stormwind/Ironforge tunnels, they found only a decoy. It appears he showed more wisdom than we accredited him.\n\nBut our second plan is already in motion. Defias agents are prepared to intercept the target as he approaches Theramore. Soon Stormwind will feel our bite all too keenly..\n\n-M" },
    ["item_caution"] = { "- DO NOT ENTER -\n\nLegion agents have been sighted in this area.\n\nPlease report any suspicious activity to Warden Alturas in the Violet Hold immediately." },
    ["item_certificate_of_thievery"] = { "The bearer of this certificate is entitled to the respect and regard that any first rate pilferer and thief deserves." },
    ["item_charge_of_the_dragonflights"] = { "Satisfied that the small world had been ordered and that their work was done, the Titans prepared to leave Azeroth. However, before they departed, they charged the greatest species of the world with the task of watching over Kalimdor, lest any force should threaten its perfect tranquility. In that age, there were many dragonflights.", "Yet there were five flights that held dominion over their brethren. It was these five flights that the Titans chose to shepherd the budding world. The greatest members of the Pantheon imbued a portion of their power upon each of the flights' leaders. These majestic dragons (as listed below) became known as the Great Aspects, or the Dragon Aspects.", "Aman'Thul, the Highfather of the Pantheon, bestowed a portion of his cosmic power upon the massive bronze dragon, Nozdormu. The Highfather empowered Nozdormu to guard time itself and police the ever-spinning pathways of fate and destiny. The stoic, honorable Nozdormu became known as the Timeless One.", "Eonar, the Titan patron of all life, gave a portion of her power to the red leviathan, Alexstrasza. Ever after, Alexstrasza would be known as the Life-Binder, and she would work to safeguard all living creatures within the world. Due to her supreme wisdom and limitless compassion for all living things, Alexstrasza was crowned the Dragonqueen and given dominion over her kind.", "Eonar also blessed Alexstrasza's younger sister, the lithe green dragon Ysera, with a portion of nature's influence. Ysera fell into an eternal trance, bound to the waking Dream of Creation. Known as the Dreamer, she would watch over the growing wilds of the world from her verdant realm, the Emerald Dream.", "Norgannon, the Titan lore keeper and master-magician, granted the blue dragon, Malygos, a portion of his vast power. From then on, Malygos would be known as the Spell-Weaver, the guardian of magic and hidden arcanum.", "Khaz'goroth, the Titan shaper and forger of the world, bestowed some of his vast power upon the mighty black wyrm, Neltharion. The great-hearted Neltharion, known afterwards as the Earth-Warder, was given dominion over the earth and the deep places of the world. He embodied the strength of the world and served as Alexstrasza's greatest supporter.", "Thus empowered, the Five Aspects were charged with the world's defense in the Titans' absence. With the dragons prepared to safeguard their creation, the Titans left Azeroth behind forever. Unfortunately it was only a matter of time before Sargeras learned of the newborn world's existence...." },
    ["item_civil_war_in_the_plaguelands"] = { "Ner'zhul, the Lich King, knew that his time was short. Imprisoned within the Frozen Throne, he suspected that Kil'jaeden would send his agents to destroy him. The damage caused by Illidan's spell had ruptured the Frozen Throne; thus, the Lich King was losing his power daily. Desperate to save himself, he called his greatest mortal servant to his side: the death knight Prince Arthas.", "Though his powers were drained by the Lich King's weakness, Arthas had been involved in a civil war in Lordaeron. Half of the standing undead forces, led by the banshee Sylvanas Windrunner, staged a coup for control over the undead empire. Arthas, called by the Lich King, was forced to leave the Scourge in the hands of his lieutenant, Kel'Thuzad, as the war escalated throughout the Plaguelands.", "Ultimately, Sylvanas and her rebel undead (known as the Forsaken) claimed the ruined capital city of Lordaeron as their own. Constructing their own bastion beneath the wrecked city, the Forsaken vowed to defeat the Scourge and drive Kel'Thuzad and his minions from the land.", "Weakened, but determined to save his master, Arthas reached Northrend only to find Illidan's naga and blood elves waiting for him. He and his nerubian allies raced against Illidan's forces to reach the Icecrown Glacier and defend the Frozen Throne." },
    ["item_cliffwatcher_longhorn_report"] = { "Nataka, all is well in Thousand Needles. The centaur annoyance is nothing more than that...occasionally attacking, nothing substantial as a real threat. However, there does seem to be some news of centaur clans uniting. We always pondered the threat of a united ruthless race such as the centaur... I try not to dwell on such ideas, as you know... nothing could penetrate the pure hatred they have... even of each other. -Cliffwatcher Longhorn" },
    ["item_cloth_request"] = { "To the Schneiders,\n\nGood day. I trust business in the canal district is good. We are booming here in the trader's square.\n\nWe are in need of knitted cloth goods, as our supply is all but depleted. Please send the standard load as soon as you are able.\n\nGood fortune, and I hope your son Thurman's studies progress well,\n\n--Harlan Bagley" },
    ["item_commendation_elwynn_forest"] = { "Having personally known Edwin VanCleef my entire life, I can tell you that facing him as a foe is quite a daunting task.  You see, he was my childhood friend, and I personally trained him in the ways of the shadows thinking that one day he might consider a career alongside me.  If VanCleef is heading up the Defias Brotherhood, may the Light have mercy on our souls. Master Mathias Shaw Stormwind Assassin's Guild" },
    ["item_compass"] = { "The compass is old and weathered with use.\n\nIt appears to be malfunctioning - the compass arrow is erratically changing direction and never settling at true North." },
    ["item_compendium_of_fallen_heroes"] = { "Tartek the Enraged.  One of the most powerful abominations the Scourge has ever created.  Assembled by lich Amnennar the Coldbringer to assist in setting up a base at Razorfen Downs.  Tartek single-handedly felled more than 1200 quilboar before finally being overcome.  His sacrifice provided the corpses for Amnennar to quickly raise an undead quilboar army of his own, ultimately assembling the first major Scourge outpost on Kalimdor.  Some of Tartek's remains were reanimated and used to create Glutton, Amnennar's current lieutenant.", "Obrahiim, the Traveler.  Brilliant architect, pivotal in the conception of Naxxramas, and mastermind behind the creation of Acherus.  Quickly rose up the ranks from lowly skeletal peon to one of Kel'Thuzad's most trusted advisors.$B$BAlways the scholar, Obrahiim traveled the world in search of knowledge, notably taking most of his early inspiration from the architecture of the Nerubians and the magic of the orc warlocks.  He was last seen several years ago, headed west to study the Ruins of Zin-Azshari in Kalimdor.$B", "Diodor the Damned.  Human necromancer, one of the first members of the Cult of the Damned, and decorated hero of the First War.  Successfully led a contingent of Scourge to victory during the First and Second Summertide Assaults upon Scarlet Monastery.  Killed in action during the Third (and final) Summertide Assault, which was successfully repelled by Scarlet Crusade operatives that had finally figured out his modus operandi.", "Kirkessen the Zealous.  Powerful lich who reported directly to the Lich King himself.  A decorated veteran of countless battles, Kirkessen designed and led the Siege of the Sanguine, one of the largest organized assaults on Light's Hope Chapel.  Despite overwhelming odds, his attack was quickly countered, and his forces suffered enormous damages.  Kirkessen himself received a critical blow from Lord Maxwell Tyrosus, and is no longer able to assume a corporeal form." },
    ["item_compendium_of_the_fallen"] = { "With Kel'Thuzad's success in Lordaeron, the Lich King made the final preparations for his assault against human civilization. Placing his plague energies into a number of portable artifacts called plague cauldrons, Ner'zhul ordered Kel'Thuzad to transport the cauldrons to Lordaeron where they would be hidden within various cult-controlled villages.", "The cauldrons, protected by the loyal cultists, would then act as plague generators, sending the plague seeping out across the unsuspecting farmlands and cities of northern Lordaeron.\n\nThe Lich King's plan worked perfectly. Many of Lordaeron's northern villages were contaminated almost immediately. Just as in Northrend, the citizens who contracted the plague died and arose as the Lich King's willing slaves.", "The cultists under Kel'Thuzad were eager to die and be raised again in their dark lord's service. They exulted in the prospect of immortality through undeath. As the plague spread, more and more feral zombies arose in the northlands. Kel'Thuzad looked upon the Lich King's growing army and named it the Scourge - for soon, it would march upon the gates of Lordaeron...and scour humanity from the face of the world." },
    ["item_consecrated_letter"] = { "I hope this letter finds you well, $c. I say that with great pride, because not many can profess such profound faith, but also know that they are among the most elite of Azeroth's protectors. Always remember, first and foremost, it is your duty to go to battle against those who seek to harm our world and bring corruption into our homes. I have been given authority over your training for the time being. When you are ready, seek me out inside Northshire Abbey. -Brother Sammuel, Paladin Trainer" },
    ["item_consecrated_rune"] = { "Some fear our kind more than dragons. Some envy us more than the most skilled blacksmiths. Some praise our strength in battle. Others revel in our faith. Some are just jealous that we can drink them under the table! But know this, $c, you are among the most elite protectors in all of Azeroth. The Holy Light gives us strength as much as we strengthen it. I would tell you more when you've gotten acquainted with the land some. Find me inside Anvilmar above the Valley. -Bromos Grummner, Paladin Trainer" },
    ["item_control_console_operating_manual"] = { "The samophlange control console can be used to autmoatically regulate the flow of fuels, gasses, liquids, and related machinery. Once initial configuration has been completed, it should run worry free with minor maintenance.\n\nBrief listing of control console components (from left to right)\n\nI. Main Power Lever\n\nThe engaged position enables the samophlange. The control mechanism will not automatically disengage when the lever is put in the off position. This will merely", "begin the cooldown process, at which point it will take roughly one to two minutes (depending on the situation) to turn off.\n\nIMPORTANT NOTE: The main power lever can only be manipulated when the three control valves on the actual machinery have been disengaged. These valves can be shut off in any order.\n\nThe first is the MAIN CONTROL VALVE, which can be found at the base of the large, vertical smokestack. Next, the FUEL CONTROL VALVE can be found on the large pipe which leads", "from the fuel tanks (there should be three of them) to the smokestack. Finally, the REGULATOR VALVE can be found on the lower of the two large, cylindrical tanks that flow into the smokestack.\n\nII. Fuel Gauges\n\nDisplays the current pressure in the primary, secondary, and tertiary fuel tanks.\n\nIII. Flow Gauge\n\nDisplays the current rate of flow within the system.", "IV. Flow Controls\n\nIncrease or decrease the flow rates. This is automatically controlled by the samophlange control mechanism.\n\nV. Temperature Gauge\n\nDisplays the operating temperature of the system in general." },
    ["item_corpulous_mess_hall_rules"] = { "Corpulous great cook of Acherus who make good food for you. He proud to feed mighty Scourge and make stronger. No make Corpulous mad, he no feed you.$B$BRules:$B$BDeath Knight eat first, ghoul wait turn.$B$BNo eat ghoul next to you. Need clean plate first.$B$BOk add own maggots and lice to food. Corpulous not offended.$B$BGot vermin? Bring to Corpulous!$B$BOk eat human or elf. Elf other white meat.$B", "Mess part of meal. Corpulous see napkin, Corpulous hang head in shame.$B$BOk bring back food not rotten enough. Corpulous got three free armpits.$B$BOk eat with hands or swords. No eat hands or swords.$B$BZombie need try more food. Think outside the brains.$B$BNo eat self." },
    ["item_covert_ops_plans_alpha_beta"] = { "Okay, you should have your NG-5 charges and detonators ready. I've labeled them for you... Blue is for the lumber mill. Red is for Windshear Mine.\n\nI did some scouting, and there are enough explosives throughout Windshear Crag that it shouldn't be a problem at all for you to get in, plant the explosives, and then get out before detonating them.\n\nRemember, this is a distraction. Get far from the wagons before the goblins get there to check out what happened, then sneak in behind them.", "Be careful with them by the way. The Nitromirglyceronium alone could reduce you to dust. I've encased some of the liquid in copper tubes which should keep it stable and safe.\n\nThe scroll you got from Collin I used on the detonator boxes. They will now send a silent message to the NG-5 charges after you've set them. I used a simple Stalthwargon mechanism to make sure the wire conductivity is optimal and the flow of the Nitroglyceronium between the differential fluid is better than average.", "Before I get back into the details about my design, let me explain where you should place the explosives.\n\nPlan Alpha- the lumber mill:\nThere's a wagon out in front of the lumber mill (this is northeast of their deforestation and lumber collection construct). I suspect the engineering plans are inside of the lumber mill.\n\nTo plant the charge, head to the back of the wagon. Once it's set, make haste and get some distance.", "When you're ready, hit the detonator.\n\nI've ensured a strong signal by routing copper and silver wires with a Melthusian antenae array within the casing of the box. That should give you good range. Just be careful of the goblins nearby. They won't appreciate my creation if they catch you in their site.\n\nOh, just in case it wasn't obvious, don't be near the wagon when it blows... it'll hurt.", "Plan Beta- Windshear Mine:\n\nI saw the goblins using another wagon of explosives north of the mine's entrance. I think that should be a good enough place to plant NG-5 Charge (Red). After you set the charge in the back of the wagon, get some distance and hit the button.\n\nIf the goblins don't come running to check out the commotion, it's probably because the mountain came down on top of their heads.", "The Venture Co. Letters are outside the mine... I think on some crates on the bottom level.\n\nGood luck, and remember...\n\nBlue Charge: lumber mill\nRed Charge: mine\n\nOh, and destroy this letter after you've accomplished your mission. Hmm, maybe I should look into a way to make these things destroy themselves after they're read. That's not a bad idea..." },
    ["item_craftys_shopping_list"] = { "<HTML>\n<BODY>\n<BR/>\n<P>Okay, $N, this is a list of all the stuff that I'm going to need for our new super-secret, er..., super weapon. For now, let's just call it \"Crafty's Ultra-Advanced Proto-Typical Shortening Blaster\".</P>\n<BR/>\n<P>Trust me, it's going to be far more revolutionary than that old, hokey world enlarger!</P>\n<BR/>\n<P>Anyway, don't think too hard about it right now. Just get me this stuff and we'll be golden!</P>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<BR/>\n<H1 align=\"center\">My Tools</H1>\n<BR/>\n<P>First things first... I need my tools. For a project this intricate no others will do!</P>\n<BR/>\n<P>When we had to run for our lives to escape from the pumping station -- that's a whole different story -- I didn't have time to pick them up. I mean, come on, I was running for my life! But I do remember that I left them under the pumping station to the east.</P>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<BR/>\n<H1 align=\"center\">An Overcharged Capacitor</H1>\n<BR/>\n<P>Any engineering hack worth their salt should be able to whip one of these up for you if you can't create it yourself. Hell, I'd make one for you, but I'm missing my tools at the moment, remember?</P>\n<BR/>\n<P>So, do whatever it takes, but get me one. The project's going nowhere without it. If you have to, head back to the southern continents and scour the auction house!</P>\n</BODY>\n</HTML>", "<HTML>\n<BODY>\n<BR/>\n<H1 align=\"center\">A Handful of Rocknar's Grit</H1>\n<BR/>\n<P>This last bit might be a little tricky to get, but it's necessary to fashion the blaster's lens from only the finest sand. That means obtaining it from a top-notch elemental.</P>\n<BR/>\n<P>Rocknar will do nicely. He was spotted to the southeast in the Frozen Reach between Unu'pe and the Wailing Ziggurat. Go break down his icy exterior to get to his rocky core and bring me back a handful.</P>\n</BODY>\n</HTML>" },
    ["item_crate_of_horseshoes"] = { "A note is attached to the crate. It reads:\n\n\"Verner - sorry to hear Redridge is having such trouble. Here are the shoes you need. Please pay me 100 silver at your earliest convenience.\"\n\n\"Or if you like, you can pay me in underbelly scales from black dragon whelps (I hear Dragon Whelps are common in the Redridge Mountains). Because we're friends... 4 scales will be enough. Thanks --Argus\"" },
    ["item_creatures_that_owe_salsalabim_golds"] = { "(1) Raliq the Drunk: Ogre. He never leaves cantina. Mean. Ugly. Fat. Mean. Also very fat.$B$B[Next Page]", "(2) Coosh'coosh: This little annoying spore-man from Zangarmarsh has mushroom garden on border of Zangarmarsh and Terokkar. Lost many golds to Sal'salabim in game of \"What's That Smell.\" Tried to pay Sal'salabim with stupid mushroom called glowcap. Say it as good as golds! Hah!$B$B[Next Page]", "(3) Floon: Arakkoa. Lost many golds to Sal'salabim. Sal'salabim killed bird-man for not paying. Now ghost bird-man walks in northwest part of Bone Wastes.$B" },
    ["item_crude_map"] = { "<HTML>\n<BODY>\n<IMG src=\"Interface\\Pictures\\21037_crudemap_256\"/>\n</BODY>\n</HTML>" },
    ["item_crumpled_note"] = { "Fleeing from the Zanzil in that rotting boat seemed wise at the time, but I start to think death would have been a more suitable fate.\n\nI thought my ancestors had granted me a boon by allowing me to escape their wrath. But now I wonder what wisdom I shall gain if I live through my imprisonment." },
    ["item_crystal_pylon_users_manual"] = { "CRYSTAL PYLON USER'S MANUAL\n\n\"A guide to collecting and using the power crystals of Un'Goro Crater\"\n\nChapter 1: The Northern Pylon\n\nChapter 2: The Eastern Pylon\n\nChapter 3: The Western Pylon", "Chapter 1: THE NORTHERN PYLON\n\nThe Northern\n\nPylon accepts\n\nyellow, red,\n\nand green\n\ncrystals.\n\nThe Pylon focuses on the energy that can be created using yellow crystals as the main source of power.", "Northern Crystal Combinations\n\nThere are two possible effects: one that will produce damage, and one that will negate damage.\n\nCRYSTAL CHARGE: Requires red and yellow crystals.\nThis will produce a large explosion.\n\nCRYSTAL RESTORE: Requires yellow and green crystals.\nThis will provide you with a healing aura.", "NORTHERN PYLON TABLE DIAGRAM", "Chapter 2: THE EASTERN PYLON\n\nThe Eastern\n\nPylon accepts\n\nblue, yellow,\n\nand green\n\ncrystals.\n\nThe Pylon focuses on the energy that can be created using blue crystals as the main source of power.", "Eastern Crystal Combinations\n\nThere are two possible effects: one provides bonus to spirit, and one that creates a damaging shield.\n\nCRYSTAL FORCE: Requires blue and green crystals.\nThis will provide you with an increase in spirit.\n\nCRYSTAL SPIRE: Requires blue and yellow crystals.\nThis will create a shield that does damage to attackers.", "EASTERN PYLON TABLE DIAGRAM", "Chapter 3: THE WESTERN PYLON\n\nThe Western\n\nPylon accepts\n\nred, green,\n\nand blue\n\ncrystals.\n\nThe Pylon focuses on the energy that can be created using red crystals as the main source of power.", "Western Crystal Combinations\n\nThere are two possible effects: one that increases your protection from damage, and one that weakens an enemy's defenses.\n\nCRYSTAL WARD: Requires red and green crystals.\nThis will provide you with an increase to armor.\n\nCRYSTAL YIELD: Requires blue and red crystals.\nThis can lower the armor of a specific target.", "WESTERN PYLON TABLE DIAGRAM" },
    ["item_daelin_proudmoore"] = { "<HTML><BODY>\n<br/>\n<br/>\n<p align=\"center\">In Memoriam</p>\n<br/>\n<H1 align=\"center\">Lord Admiral Daelin Proudmoore</H1>\n<br/>\n<p align=\"center\">Noble leader. Beloved husband and father. Taken too soon.</p>\n<p align=\"center\">Sea to sea, ashes to ashes, tide to tide.</p>\n</BODY></HTML>" },
    ["item_damp_diary_page_day_4"] = { "Diary - Day 4 I have been stranded on the Island now for 4 days, left alone with my thoughts. Bananas are pretty tasty, but what a long climb to reach them. When I am not getting food or protecting myself from the periodic rain, all my thoughts are of rescue. I would not be so hopeful if it were not for the boxes of paper and bottles that washed ashore with me. I laugh now to think of all the time I spent on that ship cursing that I was stuck with a boatload of Alchemists and Scribes." },
    ["item_damp_diary_page_day_512"] = { "Diary - Day 512 The bananas have started talking to me and I have learned a great deal about their culture. I have ceased my senseless destruction of their homes and consumption of the young. How little I knew then of the great civilization that I was destroying. On another topic I seem to be running low on bottles and paper. When I first looked at those huge stacks of paper that washed ashore I thought they would be inexhaustible. Woe with me, my diary must end soon." },
    ["item_damp_diary_page_day_87"] = { "These months have given me time to ponder, to shuffle loose my old beliefs and bigotries. Alliance? Horde? Good? Evil? The meanings of these words, once so clear, now blur as my eyes gaze across the boundless sea. I now know what matters. The bananas are after me. Perched high in their tree, they eye me with cool malevolence. And the last one I tried to eat nearly gagged me! I could almost hear it scream as I smashed it, half bitten, on sea rocks. It's war, and I will win it." },
    ["item_danath_trollbane"] = { "Danath Trollbane\n\nMilitia Commander of Stromgarde.Tactical Advisor to General Turalyon, Force Commander of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.\n\nWe honor your memory, nephew, and your sacrifice. Since the founding of our glorious empire, the path to valor has always been drenched with the blood of heroes.\n\n- Thoras Trollbane, Lord of Stromgarde" },
    ["item_dark_iron_script"] = { "Dirty troggs are so easy to fool. Their hatred for our kin makes it that much easier to direct them and use them as pawns. Amazes me that any kind of alliance could be forged at all, but our kin pose a much greater threat to their existence... at least for now. After the attacks begin though, both sides are gonna be weakened and prone to our own onslaught. Take the homestead south of Helm's Bed Lake and await further instructions. Ironforge will be ours." },
    ["item_dastardly_denizens_of_the_deep"] = { "One of the most frightening creatures I've ever seen with my own eyes is Tethyr. I've only laid eyes on the beast once, and I count myself lucky beyond belief to have survived?$B$BIt was a dark and stormy night. Through the swirling seas and driving rain, the beacon of the Theramore's lighthouse was barely visible. We did our best to steer toward it. Suddenly, the beast burst from between the waves in front of our ship!", "The mighty creature's maw opened wide, tossing bolts of icy water toward our vessel. Those terrible jaws clamped down upon the bow of our ship, tearing it from the hull. Sailors and cargo were thrown violently into the sea as the remnants of the ship disappeared beneath the waves.$B$BThat last thing I remember was flying from the broken hull, hitting the inky waters, and plunging beneath the waves. The world went dark and I thought for certain I'd drawn my last breath. When I awoke in the Theramore's infirmary, I knew someone had to tell our story.$B" },
    ["item_deathstalker_report"] = { "Deathstalker Mission Report\n\nAgents: Rane Yorick, Quinn Yorick, Erland McKree\n\nPrimary mission: perform reconnaissance through northern silverpine, and determine threat levels of wildlife and Scourge." },
    ["item_decayed_treasure_map"] = { "Missing WDB data." },
    ["item_decoded_tablet_transcription"] = { "Day 1\nOur pilgrimage is over. We've finally reached Silithus, where we're to establish contact. We have come from many places to collaborate in what is to be a monumental undertaking.\n\nThere is a tremendous sense of excitement in the air. Tomorrow we shall devote all our energy to building that which will allow communication with THEM.\n\nTomorrow we shall construct a wind stone!", "Day 2\nThe location of the wind stone has been a subject of great debate. Not even the wisest among us can determine with great certainty where the place mentioned in the old prophecy actually refers to.\n\nI've stayed with the original northern group and time will undoubtedly prove us right. The argument that the energy lines intersect at detrimental angles at this location are foolish and naive.\n\nAlready we are gathering the necessary building materials at great speed.", "Day 15\nOur dedication has paid off. We are the first camp to finish the construction of a wind stone. If the other fools had stayed with us we would've completed the task in less than a week!\n\nTomorrow we shall begin the rituals involved in summoning Baron Kazum himself. He demanded to be the first to test the system and we couldn't contradict him as he's quick to anger.\n\nI expect he will be most pleased with us." },
    ["item_decorated_gravestone"] = { "Here lies the remains of a Peon stout hearted. He tried to fight, but only farted." },
    ["item_decorated_headstone"] = { "In loving memory of Jesse Morales" },
    ["item_decrypted_letter"] = { "Greetings, Master,\n\nForgive me for the method of sending this message. My shadow mages in Alterac are intent on their tasks, forcing me to use a foreign messenger -- conscripted from our new \"allies\" -- to bring you this report. But I have encrypted this letter with one of our most esoteric ciphers. Its words are safe from these yokels.", "Our plans progress well; as mentioned, we made an alliance with a group of humans who call themselves the Syndicate. Its leaders were once the nobles of Alterac and they crave to once again hold sway here.\n\nAnd so they have struck a bargain with us. A bargain they will regret.", "Today the Syndicate holds little power in these lands, but they know the area well and have assembled sufficient manpower for the tasks ahead. With proper guiding I am confident that soon, the Syndicate will again rule Alterac.\n\nIn addition, we have urged the Syndicate to aim for the city of Stromgarde in the nearby Arathi Highlands. The city is a battlefield between our forces, ogres and the humans of Stromgarde, but we feel that with careful tactics we will own this once great city.", "And when this is done, the next stage of our plan may begin. With a nation of our own and a base of power in this region, we may then prepare the way for the Third Host.\n\nSoon, the Legion Lords will reward our works by raining fire from the skies once again!", "The Council was wise to appoint you head of the Argus Wake, marshal of their strategies in the land of humans and dwarves. And I am honored to serve as the hand of your will in Alterac.\n\nIn Sargeras' Name,\n\nNagaz,\nArgus Heirophant" },
    ["item_deepfurys_orders"] = { "Bumbling fools!\n\nMy plans called for both bridges to be destroyed simultaneously. And what do you simple-minded thugs do? You only get half the job done and alert the entire Alliance as to our intentions. Fools I say!\n\nYou have one chance to make amends for your actions. We have a backup cache of explosives in Arathi Highlands, not far from the bridge.\n\nFinish the job if you value your measly lives!\n\n--Kam Deepfury" },
    ["item_defias_docket"] = { "Our first plan has already failed! Fist was successful in switching the guard roster for the tunnel shifts that evening, but due to some unforeseen efforts by some of the citizens of Stormwind, our target was able to flee from the scene before we could capture him. But we planned for such contingencies. Plan 2 has been set in motion and was well under way before our ambush was set off in Stormwind.", "Plan 2 is just as simple, but will require more patience on our part. Our man on the inside in Menethil has already been paid for his efforts, and he's succeeded brilliantly. We should have no problem acquiring our target and capturing him once we've set sail.", "Expect the attack to happen a few miles from their destination. That's where our??? allies??? will be laid in waiting. I'm not sure why we've been forced to form an alliance with the creatures, but I can't help but feel we're being coerced ourselves. Ultimately, it won't matter. With the target in our custody, we'll be well on our way to taking back Stormwind from those that stole it from us!" },
    ["item_defias_orders"] = { "Garn,$B$BI needn't remind you of the importance of your mission -- protect your precious cargo at any cost. As I have promised, success and discretion will be richly rewarded.$B$BKeep the tongue-wagging of your \"associates\" to a minimum, heed the crew and all will be well. I shall await word of your success." },
    ["item_defias_script"] = { "The plan is set in motion.\n\nTake that once-great bastion of faith, Heroes' Vigil, as our base camp, and we'll begin to move reinforcements to you from Westfall once you have sent word that it has been suitably prepared.\n\nThe area is all but forgotten to the citizens and soldiers of Stormwind, and should prove a perfect staging point for our attacks.\n\nThe Defias will take back Stormwind!\n\nI await your response." },
    ["item_demoniac_scryer_reading"] = { "Antonivich,\n\nFirst, let me say that your latest agent, $n, has perfromed $ghis:her; duties much to my satisfaction.  I have taken possession of $ghis:her; body and now write this with $ghis:her; own hand.  Such amusement is gives me -- I hope that one day I will have the fortune to posses you, oh might apothecary!\n\nSo, the report as you have commanded of me: Hellfire Citadel is haunted by a demon stronger than any I have encountered.  I imagine that Mannoroth -- the pit lord of the Third Great War's fame -- possessed the same strength, but very few do.  I sense, however, that there is an air of confinement around this demon.  It would not surprise me if it was acting against its will, or is perhaps imprisoned, or is under the sway of an even greater power.\n\nTime will tell...", "Time will tell, as they say, for I have also sensed a shifting of fate within the walls of Hellfire Citadel.\n\nYou, the immigrants from Azeroth -- that green, lush, horrid place where beings such as myself find a hell of Light and life -- will see that demon's face.  And you will realize that the evils within Hellfire Citadel are but the tip of -- if you will permit the metaphor -- a vast iceberg.\n\nOh, what glorious battles lay ahead!  If only I could be there to taste the pain and fear that will be wrought!\n\nAh well, I shall end my prosaic waxing and you let you chew on these words, dear Apothecary: your body may be dead, Antonivich, but your soul is still very much intact, and I shall have that soul and feast upon it with sublime relish on the day your defenses slip... and I find my way into you!\n\nI shall wait until the Fourth Day of Judgement if I must, but... you will be mine!\n\nGood evening,\n-D" },
    ["item_deprecated_book_the_history_of_stormwind"] = { "While trying to collect moss samples I came across the scene of a bloody battle.  The Vile Fin tribe of Murlocs had come under siege by a marauding band of Gnolls.  There were both Gnoll and Murloc corpses littering the battlefield.  As I passed a mangled Murloc body I noticed a strange hardened tumor protruding from the wound.  As I began to study the tumor it became clear it held similar properties to the moss I was collecting.  Unfortunately, I could find no other tumors besides the one." },
    ["item_deprecated_jkaplan_test"] = { "Miner Orwell Debt outstanding.  Payment due upon next delivery of ore from Azureload. Miner Fitzgerald Debt outstanding.  Payment due upon next delivery of ore from Azureload. Citizen Netherand All debts paid. Citizen May All debts paid. Foreman Bonds Debt outstanding.  Payment due upon next delivery of ore from Azureload." },
    ["item_deprecated_remingtons_list"] = { "And when this is done, the next stage of our plan may begin.  With a nation of our own and a base of power in this region, we may then prepare the way for the Third Host. Soon, the Legion Lords will reward our works by raining fire from the skies once again!", "The Council was wise to appoint you head of the Argus Wake, marshal of their strategies in the land of humans and dwarves.  And I am honored to serve as the hand of your will in Alterac.\n\nIn Sargeras' Name,\n	\nNagaz, \nArgus Heirophant" },
    ["item_deprecated_writ_of_lakeshire"] = { "Hello William, It's been years since we've spoken, but I trust you and your brother are well, and that your apothecary thrives. I must ask a favor of you, William.  In short, my grandson Tommy Joe has lost his heart to young Maybell Maclure.  And although they adore each other... our families, well our families have been feuding for years.", "I fear the war between the Stonefields and the Maclures will kill Tommy Joe and Maybell's blossoming romance, and in times like these - where dark news and rumors of war loom over us - youth and love must be nurtured.$b$bSo, the favor: I ask that you use your skills and concoct a potion or elixir to aid these young lovers in their quest for each other.$b$bThank you, William. And please, when you have some time away from work, come visit. We'll have a few chuckles over the past.$b$b-Mildred" },
    ["item_desire"] = { "Desire.\n\nVenthyr are mostly loyal servants but they function best when properly motivated. Why choose this eternity if it does not come with appropriate rewards?\n\nAnd so I name the Medallion of Desire to grant authority to a venthyr to manage my court and their needs. \n\nAs well as collect a savory number of special souls that my most elite and trusted of children might enjoy. May this medallion allow this Harvester to grow the Castle Ward and the aspirations of its venthyr ever higher." },
    ["item_diary_of_weavil"] = { "Dear Diary,\n\nToday, my arch-enemy, Narain Soothfancy, attempted to deceive me by sending cronies to fill his spot at the execution. HIS execution. Can you believe it? I had gone through all the trouble of devising this diabolical plan to lure him out of that damnable hut and he pulls this? Whatever... Too angry to keep writing. I'll be back later.", "Dear Diary,\n\nI left my hide-out in a rage after my last entry. Boy was I angry. I decided to redesign my minions' uniforms to better reflect my angst. I feel a little better but something is missing. I'll be right back...", "Dear Diary,\n\nOk, I'm good now. I beat one of my minions until he wept like a little girl. Hrm... I feel sort of bad now. Wait a minute! Damnit, I'm an EVIL genius! Evil, you know? I'm so disappointed in myself. Be right back.", "Dear Diary,\n\nI gave him a hug and told him to keep up the good work. I feel better now. Keep that between you and me, diary. Where was I? Oh yes, NARAIN! ARGH!!! I hate that guy. It was Narain, after all, that destroyed the curve on every exam back when we were students at the Gnomeregan Institute of Tinkering. Fail me out of school, will they? As far as I'm concerned, Gnomeregan got what it deserved! That's all for today. Sleep tight, diary!", "Dear Diary,\n\nI must be getting old. I totally forgot that I was telling you about Narain and his deception. Anyhow, I was so angry when I saw a decoy disguised as Narain instead of Narain that I commanded Number Two to destroy the fool! I got in my flying machine and began tearing away at his precious, stupid, dumb-head book on Draconic. What a show-off? Who reads Draconic? I hate him so much!", "Dear Diary,\n\nSorry, I fell asleep. So I was flying angry and throwing out chapters of that stupid book. I saw a demon below me in Darkwhisper and decided to make the first chapter form a magical tornado of paper and shred its body into a million pieces! It was liberating. Magic + paper = fun. That made me pretty happy so I decided to fly to the Eastern Kingdoms. My first stop was the Molten Core. Narain always talked about that place! \"Molten Core this and Ragnaros that...\"", "Well you know what? If he likes it so much, maybe he'll like trying to piece his book back together by going to the Molten Core and reviving the chapter back from a pile of ash! Hah! While I was in the neighborhood, I figured some of those slavering technicians in ol' Victor Nefarius' lab might have a use for this Draconic stuff. Bombs away!", "This was starting to become a sport of sorts. I was really getting into splitting up that damned book! The next few drops were easy. Undercity, home of the fetid rotting dead and possibly the best chili I've ever had, got one chapter. Stormwind, capital of Cheese, the other. Diary, have you ever put cheese from Stormwind on Undercity chili? HELLO? That should sound some alarms.", "I was getting tired at this point so I turned the flying machine around and headed for home, but not before I would make two more stops. I gave Lord Kazzak and his demons a fly by in the Tainted Scar (he hates when I do that) and stuck another down Onyxia's chimney. Tired. Going to sleep." },
    ["item_divined_scroll"] = { "An evil force created these,\nHe sits on Dreadmist Peak at ease,\nHe laughs at thee and thy friend,\nHis elementals have no end,\n\nSoon you must confront this mage,\nFor only death will end his rage." },
    ["item_diving_log"] = { "Day 1: The human scum seem blissfully unaware of my presence here, as intended. They're ripe for bombing, and it should only be a matter of time before I've charted out their position.$B$BDay 2: Charting complete - a trivial task for such an accomplished fellow as myself. Why I got stuck with this job is beyond me - they should have J-Y C. do it. That ridiculous accent should have been justification enough. $B$BDay 3: First breath of air is finally getting a bit stale. Perhaps I should surface momentarily for another in a few days. Still bored to tears - where is that blasted signal?$B$B< The ranting continues ... >", "Day 12: Ah, sweet relief. The second breath tasted like the purest orphan tears I've ever had. The signal remains puzzlingly absent, and I could swear that one of the crabs is attempting to play drums on my big toe. $B$B< The rants grow more disassociated ... >", "Day 36: Third breath of air finally expired, and the veins in my left elbow filled with bubbles again on the way up. The drumming of the crabs is a constant companion now, a percussive backdrop to my blackened little corner of hell. Clearly, I've been forgotten by those wretches. If J-Y were down here, they wouldn't have forgotten him! They wouldn't have left Hans or Sylvia behind! Why me? $B$B< The entries trail off in a despondent scrawl ... >" },
    ["item_doctor_kohlers_orders"] = { "Doctor Kohler,\n\nThe Black Knight has not yet served his purpose. Retrieve his remains from the tournament grounds and use your arts to return him to life. We will use the strength of the crusaders and their followers against them.\n\nTake prisoners and use their souls to empower my servant. Capture Crusader Kul, called reckless by his fellows, and sacrifice him upon your altar. His spirit will imbue the Black Knight with terrible strength and power. Then, deliver the Black Knight to me." },
    ["item_dominance"] = { "Only the strongest, most courageous, most resilient of yaungol may lead the tribes. These traits are of the highest qualities in yaungol society, and are expected of all yaungol leaders.$b$bHowever, with the constant threat from the mantid to their south, the yaungol cannot afford to lose a single warrior in an internal struggle for power.$b$bA surprisingly civilized solution to this problem has been put into place. When a dispute arises between two yaungol, a banner is placed between them. They then fight one another with blunted weapons until one yields or passes out.$b$bSimilarly, new leaders are chosen in ritual combat: a yaungol who aspires to take the place of chief must place his family banner and fight any who would challenge his authority." },
    ["item_dominion"] = { "Dominion.\n\nIt is a truth that for every one of those raised to venthyr, every soul that has expunged their past deeds and faced their burdens, there is a chance of remission. \n\nTo watch the watchers, to grant dominion over the dominating, there is the Medallion of Dominion. \n\nMay this medallion grant authority over venthyr who have succumbed to the very corruption they serve to exsanguinate." },
    ["item_dorens_logs"] = { "Landfall!$b$bWe engaged a Horde fleet many times our number in a series of sporadic encounters throughout the night. Our losses were high, but we gave more than we got. We took advantage of a dense fog that cloaked our movements; no doubt they thought our numbers were much greater, hence they fled southeast by morning light.$b$bWe were astounded to discover a great cliff wall as the fog burned away. Land! It's not on any of our charts. I've messaged the Skyseeker in order to arrange for air support.", "Day 2$b$bThe Skyseeker has arrived and dispatched its gyrocopters. This is no mere uncharted island - we have discovered an entire continent! I will begin shuttling men and materials up the cliff walls immediately. From this higher ground, we will have a commanding view of the nearby seas.$b$bCommunication among the fleet is sporadic and confusing. The Horde seems to be everywhere at once; we have lost contact with Admiral Taylor's flagship, which likely engaged the Horde fleet we thumped a couple of days ago. Light help him; they were out or blood.$b$bWith no news from Stormwind, I am going to take the initiative and secure this land.", "Day 5$b$bThe Skyseeker has left behind a full complement of gyrocopters to help us construct a base. My men have claimed a series of abandoned ruins as a stronghold. The ruins and surrounding jungle are too dangerous for air traffic, we've been using some clearings to the south as a temporary airbase.$b$bThis morning we made our first contact with the natives. They are pandaren! I didn't think they were real. Could this be some sort of mythical pandaren homeland?", "Day 7$b$bThe pandaren are full of questions, but no help at all. I admit I'm feeling immensely uneasy, and I can't put my finger on why. It seems like all of my doubts are magnified here. The Horde will come back; I am certain of it. How many will come? Will they come by sea or by air? I must be ready!$b$bThe men are working double-time with half rations. The pandaren have offered food in trade but are not interested in Stormwind promissory notes and laugh at the quality of our steel. For some reason, this makes me furious. Do they know that they are about to be in the middle of a battlefield?", "Day 9$b$bThe Skyseeker reported that it picked up Horde prisoners from an engagement at sea this morning, then suddenly fell silent. I fear the worst.$b$bActually, I fear a lot of things. We're alone here. Reinforcements from Stormwind are weeks away. Taylor's flagship is missing, and now the Skyseeker is silent. Are we losing the war at sea? Doubts churn within me. I can't think straight. I swear my skin is losing color. What is wrong with me?", "Day 12$b$bEvery day I scan the horizon for Horde airships. We are not ready. Our airbase is in shambles, with a half-complete tower. Some pandaren have offered to help, and I've drafted them.$b$bYears ago, I once hunted down Colonel Kurzen when madness overtook him in Stranglethorn. I never understood his spiral into darkness until now. I am alone. At night I lie awake in the oppressive heat, and swear the shadows are whispering to me of my own demise. Must get that airbase finished. I'll clap the pandaren in manacles if I have to. The Horde... The Horde...", "Day 14$b$bWoke up to news of a signal flare from off the coast. There's a shadow moving through the fog. A horde gunship?$b$bI've dispatched a messenger to scramble the gyrocopters. They may not get here in time. Ordering everyone to the guns. This is it.$b$bI feel overpowered with anger and dread. I am not myself. Perhaps in victory I will find solace?$b$bIf it is truly a single Horde airship, then they stand no chance. We will decimate them." },
    ["item_dorgar_stoenbrow"] = { "Dorgar Stoenbrow\n\nWarrior of the Scarlet Crusade\n\nLord of the Red Caverns\n\nLast seen in the Mountains of Alterac" },
    ["item_dread"] = { "Dread.\n\nThis medallion bestows upon the wielder authority over the hunting grounds of the Forest Ward.\n\nMay those who afflicted others with this burden be subjected to their own taste of true fear." },
    ["item_ebonlockes_response_to_solomon"] = { "Your Honor--\n\nI regret to inform you that the Night Watch is unable to leave its post in Darkshire at this time. Perhaps you were unaware that Stormwind no longer provides military support in this region. The Night Watch has been formed and trained entirely by the people of the forest in order to defend Darkshire in Stormwind's absence. Without the Watch, the town would fall. I wish you luck with your plight.\n\n--Lord Ello Ebonlocke" },
    ["item_edict_dark_talons"] = { "Dark Talons\n\nWhere the enemies of the Earth-Warder tread, the Dark Talons shall harrow their skies, crush their will, and topple their leaders.\n\nDeny our enemies solace in walls and borders. For every talon in our ranks, you shall strike down ten of our foes from behind.\n\nThis weyrn, currently under the authority of Scalecommander Cindrethresh, shall train to be the elite force that shall be feared by all enemies of the black dragonflight." },
    ["item_edict_obsidian_warders"] = { "Obsidian Warders\n\nThis weyrn is charged with defending the allies of the black dragonflight and protecting its strongholds.\n\nWhether it is deployed to reinforce draconic legions or guard the skies alongside dragons, this weyrn is the embodiment of the Earth-Warder's aegis.\n\nCurrently under the authority of Scalecommander Azurathel, the Warders shall train to be the bulwark that enemy forces will break upon." },
    ["item_elemental_fire_for_the_soul"] = { "When the flames consume Azeroth, where will you be?\n\nWe know that no one wants to dwell on their impending doom, but it's worth thinking about where you'll be spending the hereafter.\n\nOur sages have predicted that the end of the world is nigh, and only the prepared will survive. We can help you survive the raging inferno that will cleanse this world of the wicked. Isn't it time you found some peace of mind?" },
    ["item_elizas_tombstone"] = { "Eliza\n\nBeloved wife, may the earth sate your hunger." },
    ["item_embracing_the_passions"] = { "While some of the more tame forest hozen have chosen to integrate with pandaren culture, they remain at their core a simple race driven by their passions. They love hunting and fishing, and often will assault anyone and everything in their hunting grounds. An unfortunate situation, since the hozen hunting grounds seldom have consistent bordering or signage. Thankfully, most hozen are often kept in check by pandaren monks." },
    ["item_empires_fall"] = { "Aside from their shadowy origins, it is clear that the night elves came to power soon after their discovery of the Well of Eternity. Despite the trolls' attempts to keep them from expanding their territories, the night elves built up a mighty empire that expanded rapidly across primordial Kalimdor. Wielding fierce magics never before imagined by the superstitious trolls, the night elves had little trouble doing what the evil aqir could never do: topple the two greatest empires in the world.", "The night elves systematically dismantled the troll's defenses and supply chains. The trolls, unable to counter the elves' destructive magics, buckled under the onslaught. The night elves proved to be every bit as cunning and bloodthirsty as the savage trolls -- incurring the latter race's eternal hatred and disdain. The Gurubashi and Amani empires fragmented within only a few short years.", "Eventually, the night elves were burned by the arcane fires they had sought to control. Their reckless use of magic had lured the demonic Burning Legion to the world. The demons crushed much of the night elves' civilization. Though there are no records to indicate that the Legion attacked either troll civilization, it is likely that battles took place across the breadth of the continent.", "At the end of this terrible conflict -- known as the War of the Ancients -- the Well of Eternity imploded. The resulting shockwave shattered the greater landmass of Kalimdor. The center of the continent was blasted beneath the sea, leaving only a small group of broken, single continents.", "Thus, great chunks of both the Amani and Gurubashi Empires still exist in the present day lands of Quel'Thalas and Stranglethorn (respectively). The Azj'Aqir kingdoms of Azjol-Nerub and Ahn'Qiraj have also survived in present day Northrend and Tanaris (respectively).\n\nBoth troll civilizations recoiled from the vast destruction of the primordial world they had known. The dauntless trolls rebuilt their ravaged cities and set about to reclaim some of their former power." },
    ["item_encrypted_letter"] = { "Never been more proud to be part of the trade as I am in these last few years. The need for assassins, spies, and scouts has never been more prevelant. You'd think war-time would have had higher demand, but suprisingly, war isn't a time we flourish like we do now--the times after peace starts to deteriorate. I was told you'd be in the area looking to learn a few things. When you have time, come see me by the stables in back of the abbey. -Jorik Kerridan, Rogue Trainer" },
    ["item_encrypted_memorandum"] = { "You were expecting this to be a normal note from your king or whoever, I'm betting. Well, let's just say that I know a thing or two about forging notes and wanted to make sure you got this one. Can't go calling attention to myself, now could I? I've holed myself up inside Anvilmar--you'll find me in the firepit area. When you're ready, come talk to me. I just want to introduce myself while we have time. -Solm Hargrin, Rogue Trainer" },
    ["item_encrypted_parchment"] = { "I send greetings, $N. I was lost in thought when it came to my attention that I needed to write to you. Many in our culture praise our shamans for being our spiritual leaders, like our great Warchief. Others think the sword and axe are even more noble pursuits, but never forget that battles--even wars--are won on the backs of those with more specialized skills. That is what I wish to speak to you about, $N. Find me deep within the Den in the Valley of Trials. -Rwag, Rogue Trainer" },
    ["item_encrypted_rune"] = { "$gBrother:Sister;, I hope this rune finds you well. I wanted to take a moment to let you know that I'm inside Anvilmar above Coldridge Valley. I know how important it is we all stick together, and in this time of strained peace it's becoming even more important to have our kind around. Look for me when you have the time. -Solm Hargrin, Rogue Trainer" },
    ["item_encrypted_scroll"] = { "Take care not to ignore my words, $N. This is the time for subterfuge and deceit throughout all nations... even our great Undercity. Everyone loyal to Sylvanas is working towards creating a new era, one controlled by the Forsaken. And even though we posses no magical skills, nor will we take up weapons along our borders, we still have our own role to play. Seek me out in the inn in Deathknell. We'll speak more then. -David Trias, Rogue Trainer" },
    ["item_encrypted_sigil"] = { "Sael'ah, my friend. I hope this sigil finds you well. I was asked to offer you my services. I too am in Shadowglen, in the great tree of Aldrassil, and I wanted you to know that if you need any training that you could seek me out. In these questionable times, I thought it prudent that those dealing in stealth remain even closer to one another. How else will we be able to protect Teldrassil and our ways? Find me when you can. -Frahun Shadewhisper, Rogue Trainer" },
    ["item_encrypted_tablet"] = { "Greetings, $gbrother:sister;. The Shattered Hand sends its regards and hopes you find the Valley a comfortable place to apply your trade. This is a time of testing for you, so do not think you are not being watched constantly. It is my duty to appraise the Hand of your skills, and to then inform them when I feel you are ready to move on to greater challenges. When you are ready, come find me deep inside the Den. I'll be waiting for you there. -Rwag, Rogue Trainer" },
    ["item_envy"] = { "Envy.\n\nGreed, the festering need for what others possess. Such souls burdened with this must be forced to confront their needs and overcome it. May they exist in squalor and desperation until their need is shattered.\n\nSo shall there be the Village Ward. May the Medallion of Envy grant its Harvester authority over this dark Ward, forever in the shadow of Castle Nathria, forever within view of something greater that can never be achieved." },
    ["item_etched_crystal"] = { "Missing WDB data." },
    ["item_etched_parchment"] = { "Ya be in good hands now, mon. Jen'shan know you be lookin' to learn da ways of da hunter, and she be ready to teach you... if you be ready to listen. Come find me in da Valley of Trials. Jen'shan start your trainin' and show you just how powerful da ways of da hunter is. -Jen'shan, Hunter Trainer" },
    ["item_etched_rune"] = { "Tamer of beasts, master marskman, proven tracker--what else ya want to accomplish in this lifetime? All those things combined takes quite a bit of intelligence and a great deal of patience. The path of the hunter ain't an easy one, that's fer sure. You're gonna need lots of training if you wanna be as good as even our lowest ranking rifleman. But that's why I'm here. Find me inside Anvilmar overlooking Coldridge Valley. I'll be waiting. -Thorgas Grimson, Hunter Trainer" },
    ["item_etched_sigil"] = { "Elune is with you, $N. The wind whispers it to me, and I'm glad I can directly take part in the shaping of our next generation of hunters. From what I have been told, you are close to Aldrassil. I would meet with you inside the great tree when you have time. Our elders have charged me with ensuring that new hunters are properly trained for the trials ahead. You being one of the newest students, it would behoove you to visit me. Until then, be well. -Ayanna Everstride, Hunter Trainer" },
    ["item_etched_tablet"] = { "It be good to hear that one of Jen'shan's $gbrothers:sisters; be comin' to da Valley to test $ghis:her; skill. Jen'shan lookin' forward to that! Me not be havin' to tell you how strong and cunning a hunter you be--you already know that. It's Jen'shan's task to tell you how to get stronger and more cunning. You find Jen'shan in da Valley of Trials. She teach you good. She teach you how to tame da greatest beasts among many other tings. -Jen'shan, Hunter Trainer" },
    ["item_exile_of_the_high_elves"] = { "As the centuries passed, the night elves' new society grew strong and expanded throughout the budding forest that they came to call Ashenvale. Many of the creatures and species that were abundant before the Great Sundering, such as furbolgs and quilboars, reappeared and flourished in the land. Under the druids' benevolent leadership, the night elves enjoyed an era of unprecedented peace and tranquility under the stars.", "However, many of the original Highborne survivors grew restless. Like Illidan before them, they fell victim to the withdrawal that came from the loss of their coveted magics. They were tempted to tap the energies of the Well of Eternity and exult in their magical practices. Dath'Remar, the brash, outspoken leader of the Highborne, began to mock the druids publicly, calling them cowards for refusing to wield the magic that he said was theirs by right.", "Malfurion and the druids dismissed Dath'Remar's arguments and warned the Highborne that any use of magic would be punishable by death. In an insolent and ill-fated attempt to convince the druids to rescind their law, Dath'Remar and his followers unleashed a terrible magical storm upon Ashenvale.", "The druids could not bring themselves to put so many of their kin to death, so they decided to exile the reckless Highborne from their lands. Dath'Remar and his followers, glad to be rid of their conservative cousins at last, boarded a number of specially crafted ships and set sail upon the seas. Though none of them knew what awaited them beyond the waters of the raging Maelstrom, they were eager to establish their own homeland, where they could practice their coveted magics with impunity.", "The Highborne, or Quel'dorei, as Azshara had named them in ages past, would eventually set shore upon the eastern land men would call Lordaeron. They planned to build their own magical kingdom, Quel'Thalas, and reject the night elves' precepts of moon worship and nocturnal activity. Forever after, they would embrace the sun and be known only as the high elves." },
    ["item_extended_annals_of_darrowshire"] = { "The Annals of Darrowshire\n\nDarrowshire, named from the Darrowmere Lake to its west, is a village tucked into the southern foothills of Lordaeron. Known for humble yet hardworking residents, Darrowshire stayed in the background of Lordaeron history until the Second War.\n\nHeroes were made during that war. And heroes were lost.", "The Battle of Darrowshire\n\nThe Battle of Darrowshire took place in the middle of the Second War, when scourge forces rampaged across Lordaeron. Darrowshire was cut off from the bulk of Alliance forces, but the town was bolstered by a company of troops, a contingent of paladins of the Silver Hand, and a staunch group of local militia led by Captain Joseph Redpath.", "The Scourge's first assaults on Darrowshire were sparse. Small groups of marauding skeletons and corpses wandered the outskirts of the village and were easily defeated.\n\nBut the Scourge sensed the defenders' tenacity, and responded in kind; soon after the first wave of attacks a second wave emerged. Champion ghouls, servants of the ghoul lord Horgus, screamed down from the hills and clashed with beleaguered Darrowshire defenders.", "The Defenders weakened, but were relieved by paladins, disciples of the Silver Hand. Their leader, Davil Crokford, was a native of Darrowshire. He brought his followers to the village when he heard of the impending attack, and together with the defenders they held back the servants of Horgus.\n\nWhen Horgus himself entered the battle, he met with Davil. For many minutes they fought and Davil eventually prevailed, but he suffered a mortal wound and died soon after defeating the ghoul lord.", "The battle continued, and Captain Redpath led his militia bravely. And it might have been won, had the captain not been corrupted by the death knight Marduk the Black.\n\nIn the middle of the fray Marduk rode up to Redpath, and with black magic he tore loose Redpath's spirit, twisting it into an evil shadow of the brave captain.", "The corrupted Captain Redpath then spread his evil taint among the defenders of Darrowshire, who betrayed their allies and slaughtered them. They then turned on the town of Darrowshire and killed all who hid in their homes.\n\nThe remaining scourge army, along with the corrupted spirit of Captain Redpath, then left the ravaged village of Darrowshire and tore into Lordaeron, adding to the pain and death of the Second War.", "The Fate of Horgus the Ravager\n\nHorgus the Ravager fell at the Battle of Darrowshire. But the evil within him was not fully spent. The victorious Scourge forces removed his skull from the battlefield of Darrowshire, carrying it with them to sow dread among the living they faced.\n\nDays later, the company of Scourge who possessed the head were defeated by Silver Hand Paladins. Horgus' head was cast into Blackwood Lake.", "The Fate of Marduk the Black\n\nMarduk survived the Second War, causing great death and suffering with his foul, rune-laden sword. Although Marduk still lives, his sword was lost in a battle near Corin's Crossing. A dwarf captain shattered the sword on his enchanted shield, forcing Marduk to flee the field and winning the day for the Alliance.\n\nMarduk's sword sank into the earth and corrupted it, eating a gorge into the land, now known as the Infectis Scar.", "The Fate of Davil Lightforge\n\nDavil Lightforge died at the Battle of Darrowshire, but his bravery inspired the Alliance throughout the war.\n\nHis book, his paladin's libram, was recovered by Scarlet Crusade troops. It now resides in the town hall of the Scarlet Crusade controlled Hearthglen, often read by crusaders eager to draw from Davil's strength.", "The Fate of Joseph Redpath\n\nJoseph Redpath was killed during the Battle of Darrowshire. His spirit was corrupted and took new shape, and this creature spread great evil in Lordaeron.\n\nAt Gahrron's Withering, east of Andorhal, the corrupted Redpath was finally defeated by Alliance forces. His shield still rests near the barn of the plagued farmstead, and Scourge minions are still drawn to the memory of his evil.", "The Fate of Carlin Redpath\n\nBrother to Captain Joseph Redpath, Carlin fell during the battle of Darrowshire. But although terribly wounded, he was not slain.\n\nDays after the battle, agents of the Argent Dawn found Carlin wandering, weak from thirst and fever, near Corin's Crossing. They tended to his wounds and brought him to the Light's Hope Chapel.\n\nGrateful for their charity, Carlin joined the ranks of the Argent Dawn and now fights a battle of revenge against the Scourge." },
    ["item_faded_photograph"] = { "<HTML>\n<BODY>\n<IMG src=\"Interface\\Pictures\\Linken_sepia_256px\"/>\n</BODY>\n</HTML>" },
    ["item_father_gustavs_report"] = { "Highlord,\n$N has successfully led the campaign against the Scourge of Scourgeholme and positioned us to march upon Icecrown.\nThe masons are equipped with the supplies that they need to begin construction of Justice Keep - thanks once again to $N for $g his:her; assistance in Crystalsong Forest.\nThere remains only one last challenge: the taking of Crusader's Pinnacle. For it is there, at the place where we have anguished most, that I wish to begin this final chapter.\nWe await your command, sir.\nLight protect you.\n-Gustav" },
    ["item_featherbeards_map"] = { "The sketch shows Shadra'Alor and its three temples, with a number of 'x' marks, corresponding to the locations of the stolen eggs. The marks appear at the southern end of the eastern temple, close to a hut to the northeast of the eastern temple, near an altar to the east of the central lake, and on the slope of the southern temple near the word 'exile.'$B$BFeatherbeard's notes indicate that he was planning on delivering this information to Falstad Wildhammer, whom he hoped would dispatch a band of warriors to rescue the eggs." },
    ["item_fel_tracker_owners_manual"] = { "The Conjuring of the Beast:\n\nTo conjure the Felhound Tracker, you must use the supplied Fel Orb.\n\nNotes:\n\nThe conjured Felhound Tracker will only remain as an entity in this world for thirty minutes.\n\nThe conjured Felhound Tracker will only assist you in finding Azsharite formations.\n\nThe conjured Felhound Tracker WILL NOT do the following: Tricks, attack anything, assist anything, dance, destroy arcane beings.\n\nNext page please...", "The Control of the Beast:\n\nFelhound Trackers only respond to beastial roars. In order to get your Felhound Tracker to track Azsharite formations, you must roar at it with vigor! (Target the Felhound Tracker and /roar).\n\nWhen the Felhound Tracker locates a formation, he will sprint to the formation with little to no regard for the entities that surround him. While you do not need to protect the Felhound, you may want to stay close so that you do not lose him.", "The Disposal of the Beast:\n\nAfter thirty minutes, the beast will return to its home in the Nether.\n\nNote:\n\nIn its fervor, the beast MAY run off cliffs or fall off a mountain. Don't mourn the loss of the Felhound Tracker, summon another one instead." },
    ["item_fellari_swiftarrow"] = { "Fellari Swiftarrow\nRanger Captain of the Scarlet Crusade\nCitizen of Quel'Thalas\nLost in the forests of Silverpine" },
    ["item_ferren_marcus"] = { "Ferren Marcus\n\nHigh Abbot of the Scarlet Monastery\n\nCitizen of Stratholme\n\nKilled defending the Scarlet Monastery at the First Summertide Assault" },
    ["item_final_clue_to_sanders_treasure"] = { "Now that ye found me ol' whiskey jug, you're almost to the treasure! Just face West from the bottle and walk down to the shore. Once ye get to the water, keep going! Swim straight west till you find the island with me treasure chest!" },
    ["item_finding_security_and_comfort_in_a_doomed_world"] = { "We live in tumultuous times. War, invasion, and famine have swept the world, but the real trial is yet to come: the end of Azeroth itself.\n\nHow will you cope with the loss and destruction of everything you hold dear? The answer is that you don't have to. Bring your friends and family to one of our gatherings and learn how you can survive the apocalypse together, with us." },
    ["item_fine_boots"] = { "These boots are in surprisingly nice condition for their age.\n\nIt's odd that they would still be left here after all these years." },
    ["item_fishing_tournament"] = { "Stranglethorn Fishing Tournament!\nSunday Afternoon - 2pm to 4pm.\n\nFish anywhere along the coast of Stranglethorn (except for Booty Bay) and look for the schools of Tastyfish that will appear along the coast! Make sure your fishing bobber lands in the school and you will be catching special fish instead of the normal Stranglethorn variety. The first person to catch forty Tastyfish can turn them into Fishmaster Bassbait in Booty Bay for a prize!\n\nEven if you are not the first person to catch forty tastyfish you can still turn them in for cash and there are special fish to be caught as well that will reward special prizes!" },
    ["item_fizzle_brassbolts_letter"] = { "Good Martek,\n\nI'm in a jam and I need your help.\n\nMy brother and I are building a racecar and we need strong pistons. Nothing I try is hard enough. Nothing can hold up to our new car's speed. And so the engine breaks down constantly!\n\nYou are an expert in crafting with metal. You must help. You are the only one who can.", "Here are the piston's specifications:\n\nLength: 32 WW\nWidth: 12 WW\nWeight: 23.5 IBG to 25.5 IBG\nConduction: 70 TC\nShear Strength: 98 or higher\nCombobule Rating: \"Super stout\" or higher\n\nIn the case you forgot gnomish measurements:\nWW = \"Whisker Width\"\nIBG = \"Itty-Bitty Grams\"\nTC = \"Toe Curls\"" },
    ["item_folded_letter"] = { "Hi!$B$BI'm not good at letters and so the matron helped me write this down for you.  I just want to say THANKS because you're a hero and maybe someday I can save people like you do.$B$BOk, I have to go play so THANKS AGAIN for being good and strong and and you're $ghandsome:pretty; too!$B$B--Your secret admirer" },
    ["item_fools_stout_report"] = { "Mr. Fizzlebub,\n\nThe beverage you gave my associate was a huge success. Not only is the drink strong, causing a huge dulling of wits, it seems to have an addictive quality. I'm sure those who have tried it will crave more.\n\nWe are indebted to you, Crank.\n\nAnd I invite you to come to Shimmering Flats, or to send a confidante, to take advantage of the new gambling opportunities we have here.\n\n--Kravel" },
    ["item_for_the_light"] = { "His name brought Light to darkest Azeroth. His valor tore the walls of mis'ry down. The Silver Hand would ne'er do better more than give the world the knight who'd give himself.", "His fame was not that which he sought to grow, nor was the lordship over his own kind. Instead he chose to fight for Lordaeron to hope his kin would have to fight no more.", "The tragic tale of this most holy knight will never end with his unholy death. We honor him, and we shall give him thanks! Uther always shall know glory and Light!" },
    ["item_foreboding_plans"] = { "L. F. has ordered increased aggression against the fools in the Alliance. Below is a list of materials needed for an important mission against Southshore:\n\n1 week travel rations for 20 men\n20 black night suits\n20 pairs new shoes\n25 new swords\n30 throwing knives\n20 black masks\n10 vials inflammatory oil\n50 doses paralytic poison\n5 stolen Southshore guard uniforms, if available\n100 silver coins\n\n--Baron V.\nQuartermaster" },
    ["item_forestlord_and_the_first_druids"] = { "In time, the child, Cenarius, grew to the stature of his proud father. A brother to both the trees and the stars, the great hunter roamed the far places of the world, singing the harmonious songs of the dawning. All creatures bowed before his grace and beauty - there were none so cunning as the son of the moon and the white stag.", "Eventually, Cenarius befriended the Shu'halo and spoke to them of the turning world. The children of the earth knew him as brother and swore to help him care for the fields of life and the favored creatures of their great Earthmother.", "Cenarius taught the children of the earth to speak to the trees and plants. The Shu'halo became druids and worked great deeds of magic to nurse the land to health. For many generations the Shu'halo hunted with Cenarius and kept the world safe from the shadows that stirred beneath it." },
    ["item_forors_compendium_of_dragon_slaying"] = { "Foror's Compendium of Dragon Slaying is a thick book full of writing. Unfortunately the text appears to be garbled and makes no sense to you." },
    ["item_fossilized_egg"] = { "Found in the sweltering wastes of the Tanaris desert, this peculiar egg remains a mystery to modern ecologists. Dating tests suggest the egg could be up to a thousand years old. Though certain elements denote insectoid structure, its true origins cannot be discerned. The species that lays such distinct eggs still remains to be discovered." },
    ["item_from_the_desk_of_lord_victor_nefarius"] = { "To Whom It May Concern,\n\nHow I love these games that we play.\n\nI can only assume that if you are reading this letter, you have somehow, through miracle or divine intervention, managed to vanquish me. Preposterous, I know, but stranger things have happened in the history of this world.", "As with all things in life, there is a glorious, silver lining of tragedy, chaos, and evil to this sorrowful tale. While you have slain me, you have done so in such a slow and disorderly fashion that I have had time enough to write this letter AFTER I destroyed your only hope of saving this world. The crushed red crystal powder is all that is left of your scepter shard.", "Enjoy the Nemesis and Stormrage armaments that you may find in my treasure trove. Believe me when I tell you this: I take great pleasure in knowing that I did what my father could not...\n\nSincerely,\n\nLord Victor Nefarius\n\"Nefarian\"" },
    ["item_fur_blanket"] = { "The bedding in the tent has been undisturbed for quite some time." },
    ["item_furens_instructions"] = { "In the following pages, you'll find a list of the materials necessary to make fire-hardened armor. Good luck, warrior.\n\n-Furen Longbeard", "Scorched Spider Fangs: The incendicite ore that is found in a cave near the vicinity of Thelgen Rock has scorched the spiders that dwell there. The venom in their fangs boils and reacts with the fangs themselves to create a very tough substance.", "Charred Horns: Much like the scorched spider fangs, the charred horns of the chimaera that reside in the Charred Vale, in the Stonetalon Mountains on Kalimdor, possess a much-prized quality. Pounded flat and properly treated, they become extremely resilient to physical stress.", "Galvanized Horn: The rare galvanized horn's toughness is the lynchpin of the entire piece of armor I will create, and so it too must be procured. It may be gained from the rare chimaera matriarch in the Charred Vale.", "Vial of Phlogiston: The last stage of creating the armor will require an extremely hot forge. To produce the needed level of heat I must have a vial of phlogiston. The only known maker of this substance is the fabled Quilboar, Roogug, and he will not give it up without a fight. Roogug dwells deep in Razorfen Kraul in the southern Barrens." },
    ["item_furlbrows_deed"] = { "This is a deed to an expanse of land within the region of Westfall. It entitles the persons below with ownership rights of the designated area, as well as all items produced and any structures built within its borders.\n\nThe document is signed by:\n\nTheodore Furlbrow\nVerna Furlbrow", "[The words below were quickly scrawled on the back of the deed]\n\nWe leaned on Furlbrow and got his deed. Thought it might be handy if you wanted to forge one of these for your own place. The Furlbrows won't give us trouble. Last I saw them they were on their way out of Westfall, stuck with a broken wagon." },
    ["item_galaens_journal"] = { "I watched as they beat him without mercy. Their ruthless lieutenant acted as if such cruelty was an act of normalcy. Through the savage beatings, I could feel myself breaking.$B$BAs I watched Vindicator Saruan take their blows, I began to weep. Not out of fear... I wept out of sadness. To see a draenei of the Triumvirate treated in such a manner. If only I could have broken free of my bonds. If only...$B", "After what seemed an eternity, the Vindicator lost consciousness. The torture was too much, even for him. The cruel one - Matis as I found out he was called - attempted to wake Saruan by splashing contagion laced water across his ravaged body. But Saruan did not wake.$B", "I wanted to scream but only a low gasp escaped my lips. I was promptly beaten for this act of rebellion. As I lay on the ground, I could see Matis pacing in front of Saruan's body. He seemed visibly concerned. He stated that Sironas or Sirona or some such entity would have his flesh flayed from his bones if Saruan had perished in the beatings.", "That the Sironas entity had plans for Saruan...$B$B<The writing stops abruptly and a long line scrolls off the page. This draenei died while making the entry.>$B" },
    ["item_gatruls_logs"] = { "Day 12$b$bHonorable Warchief-$b$bI have assumed command of the fleet after Krug fell during battle with the Alliance flagship. He died with great honor, and did not choke his last breath until he learned of the Alliance defeat. $b$bThe battle has taken a heavy toll on the fleet, but one by one our scattered vessels are arriving victoriously to the shores of this strange land. It is not on any of our charts.$b$bI have tasked our peons with the construction of a safe harbor from which we can make repairs.", "Day 13$b$bA fat race of bear-creatures calls this land home. They are the \"pandaren.\" Dalgan tells me that a pandaren was present at the founding of Orgrimmar, but he is always full of grog and lies.$b$bThese pandaren do not appear to be a threat, but they have supplies which will be useful to our campaign: food, wood, stone... If this indicates the wealth of this new land, then it will make a fine prize for the Horde.", "Day 14$b$bScouts have discovered ancient, unclaimed ruins backed up against the mountains that overlook the cove. It is an ideal stronghold. I do not anticipate reinforcements from Orgrimmar for several weeks. For this reason I have opened the ancient texts and commanded our warlocks to begin summoning demonic forces to bolster our army. This show of force will no doubt intimidate the pandaren into aiding our cause.$b$bAn entire battalion of Forsaken forces swam ashore in the dead of night, survivors from the battle at sea. It seems they are impossible to drown. The stench is overwhelming, but they may have their uses.", "Day 15$b$bBy now news of our victory at sea and discovery of this new land will have reached Orgrimmar. No doubt reinforcements are on the way. Our lookouts have spotted Alliance scout ships snooping around the debris field marking the location of the sea battle - they will likely come looking for their own. We will be ready.$b$bThe pandaren have proven to be useless to our cause. They are not interested in the goods we have for trade: they turned up their black noses at even the most powerful of fel artifacts. My troops will need food, we cannot eat the corpses of drowned sailors like the disgusting undead. Pandaren arrogance is making my blood boil. I cannot seem to escape my rage.", "Day 17$b$bThe Alliance is coming. I can feel it. I do not know why - I have an overpowering sense of unease and dread. Something about this land is eating away at me. I have ordered my warlocks to summon a demonic observer so that we can watch the shores. They insist we will not be able to control it. I am surrounded by cowards in my time of need. Why do I feel such doubt? I swear my very skin is losing color.", "Day 19$b$bThe pandaren sent an envoy to ask us to stop cutting down their trees. I told him that his people should've listened to my request for more wood, and sent him back with scars. Releasing my anger felt good.$b$bThe Alliance is coming, and my time grows short. I must find a way to make the pandaren listen. Perhaps if I took something they valued, that would both show our strength and give us something to bargain with? Bellandra of the Forsaken had the interesting notion of taking their cubs.", "Day 21$b$bAlliance gunship spotted south of our position. I have ordered our grunts to the guns. I will see to the defense of Garrosh'ar Point personally.$b$bI feel a great darkness inside me. The spilling of Alliance blood should bring relief. I am ready." },
    ["item_general_turalyon"] = { "General Turalyon\n\nFormer Lieutenant to Lord Anduin Lothar. Knight of the Silver Hand. High General of the Alliance Expedition that marched into the orc homeworld of Draenor. Presumed deceased.\n\nEsarus thar no'Darador' - By Blood and Honor We Serve.\nYou were the right hand of justice and virtue, old friend. Your name will be honored in our halls always.\n\n- Lord Uther the Lightbringer - Knight of the Silver Hand" },
    ["item_geru_strider"] = { "The largest of the plainstrider birds, the Geru are few in number and rarely encountered." },
    ["item_give_to_the_church_and_the_light_will_provide"] = { "From the desk of High Abbot Landgren: BBIt may seem that in dark times of strife and turmoil that one must turn inward, protecting family and loved ones to the exclusion of all else. But these feelings are false - without the beacon of hope that is the Church, despair will quickly inundate the very pores of your family's soul. All the full stomachs, warm toes, and happy smiles that worldly goods may purchase will not save your family from the creeping inner emptiness that shirking your fiduciary responsibilities to the Light will induce.", "Give to the church. The hardships endured through lack of worldly goods act as a forge for the soul, burning out impurities and raising you up to a higher plane of being. Be not ashamed at the rumbling of an empty stomach, the bite of a sharp rock upon your bare foot, or the chill of the winter wind. These are but means by which the Light communicates its inspiration to the soul. These sacrifices ensure that the arching, gold-appointed paeans to the Light which so inspire you at worship are well-maintained. $B$BEschew the comforts of the flesh, and come ever closer to the Light." },
    ["item_glyphic_letter"] = { "There are four rules to magic: Magic is powerful. Magic is corrupting. Magic is addicting. Magic draws the denizens of the Twisting Nether to those who wield the arcane. Those rules you can always guarantee. Those rules will govern your destiny if you chose to continue down the path as a mage. If you're foolish enough to ignore this warning, then come speak to me inside the library wing of the abbey in Northshire. I'll be waiting for you upstairs. -Khelden Bremen, Mage Trainer" },
    ["item_glyphic_memorandum"] = { "To: New Students of the Arcane Arts: You are required to seek out and study under the gnome Marryk Nurribit until such time comes that you are called upon to aid your people in re-establishing themselves in a new habitation. Please, without trepidation, prepare yourself for rigorous testing procedures and a difficult acclimation process as you find a domicile and/or any form of companionship with the local denizens. Questions regarding your duties and abilities should be directed to Marrek Nurribit." },
    ["item_glyphic_scroll"] = { "The corruption and evil that rumor says travels with the arcane is nothing compared to the pain we've already felt. We are no longer victims, $N. We are the ones who control our fate. Sylvanas has paved the way for us--she has proven that our will is our own; that we are no longer thralls to that bastard Arthas. Seek me out in the church, I shall instruct you further... if that is your desire. - Isabella, Mage Trainer" },
    ["item_glyphic_tablet"] = { "Welcome to your awakening, mon. Da secrets of da arcane be wit'in your grasp if you be strong enough to hold onto dem. You find Mai'ah when you be ready. She teach you much about magic and da spells you need to destroy those dat stand against you. Mai'ah be near da Den in da Valley of Trials. You come, you find her, den you be strong. Den you show other mages how magic bends to your will... not de other way 'round." },
    ["item_goblin_rumors"] = { "The goblin Nazz Steamboil is really the son of a goblin merchant prince (Which prince? The price of that information is high).\n\nIt seems he much rather enjoys spending the money his family makes than he does earning it himself. So he stole a small fortune from his family's hoard and is now hiding in the Shimmering Flats.\n\nIf his father knew where he was, he'd be sure to seek him out and drag him back home... minus a toe for his insolence." },
    ["item_goodsteel_ledger"] = { "Greetings and Salutations, Adventurers!\n\nI, Krinkle Goodsteel, have need of those willing to put themselves at risk in order to complete some of my most arduous tasks. Because of my many duties and the workload I've managed to take upon myself, I ensure that anyone brave enough to complete this list of items and return them to me intact will be paid handsomely.\n\nThe list is contained on the following pages...", "Solid Crystal Leg Shafts -\n\nThe Glassweb spiders of Searing Gorge are made of an incredible crystal-like material. Their legs, if not damaged when they're killed, make for a wonderful conductor in some of my companions' engineering experiments.\n\nI will need a number of them to test upon. The spiders having eight possible legs themselves should be no problem for a stalwart warrior or practiced mage.", "An Overdue Package -\n\nI hired someone who I thought was a reliable pilot to bring me a package from Theramore. I was apparently wrong. And even though the pilot lived to tell the tale, he left his entire zepplin and all of its cargo behind to save his own neck.\n\nWell, I need that package back. From what Beezil tells me, he crashed just west of the bay in Dustwallow Marsh. It went down just after he crossed the hills along the water's edge.\n\nHmmm... never did tell me what caused him to crash...", "Goodsteel's Balanced Flameberge -\n\nFinally, I want one of my finest works of blacksmithing to date. This flameberge was an incredible sword that I bestowed upon what I thought was a very honorable and great warrior. Well, he was trounced by a murloc named Jarquai? Something like that.\n\nIt was while he was traveling along the coast of the Swamp of Sorrows when he thought to attack the creature. He failed and apparently fled, but not before leaving the weapon behind for this murloc to take.", "Find me these items and return to Gadgetzan with them all, along with this ledger, and I will reward you." },
    ["item_gordawgs_imprint"] = { "<HTML>\n<BODY>\n<IMG src=\"Interface\\Pictures\\24475_gordawg_256\"/>\n</BODY>\n</HTML>" },
    ["item_gramma_stonefields_note"] = { "Hello William,\n\nIt's been years since we've spoken, but I trust you and your brother are well, and that your apothecary thrives.\n\nI must ask a favor of you, William. In short, my grandson Tommy Joe has lost his heart to young Maybell Maclure. And although they adore each other... our families, well our families have been feuding for years.", "I fear the war between the Stonefields and the Maclures will kill Tommy Joe and Maybell's blossoming romance, and in times like these - where dark news and rumors of war loom over us - youth and love must be nurtured.\n\nSo, the favor: I ask that you use your skills and concoct a potion or elixir to aid these young lovers in their quest for each other.\n\nThank you, William. And please, when you have some time away from work, come visit. We'll have a few chuckles over the past.\n\n-Mildred" },
    ["item_grand_admiral_daelin_proudmoore"] = { "Commander of the Alliance Fleets\n\nFriend of Stormwind" },
    ["item_grape_manifest"] = { "Brother Neals,\n\nMy grapes are saved! $N, the bearer of this manifest, braved my thug-infested vineyard and gathered the grapes that I could not. Although the Defias still roam across the river, nearly my entire crop has been salvaged.\n\nYou may add a full load of grape bushels to your stores.\n\nMay the Light protect us,\n-Milly Osworth" },
    ["item_greatmothers_list_of_herbs"] = { "The Olemba root is a fairly common root found in the Terokkar Forest. Search near the Olemba trees that comprise the bulk of Terokkar's forests for upturned roots.\n\nThe marshberry only grows in Zangarmarsh. It can only be found at the Ango'rosh Stronghold, located in the northwestern region of the marsh. Beware the ogres that fervently guard the precious berries.\n\nThe Telaari frond is perhaps the most easily attainable of the herbs on this list. South of Garadar in the Talaari basin, you will find the fronds. They grow near the water.\n\nThe last herb on the list is unique to the Blade's Edge mountains. You will find Blade's Edge north of Zangarmarsh. Dragonspine grows upon the ends of the jagged rock formations that guard the canyons of Blade's Edge. You will know what I speak of when you first see Blade's Edge. The rock formations look like row upon row of sharp and pointed teeth." },
    ["item_green_hills_of_stranglethorn"] = { "The Green Hills Of Stranglethorn By Hemet Nesingwary" },
    ["item_green_hills_of_stranglethorn_chapter_i"] = { "Our first day went as well as one can expect first days to go. Most of our time was preoccupied with making the necessary arrangements to establish a base camp. I located an ideal setting by a freshwater river inlet. Judging by the old, abandoned docks nearby, this site was inhabited sometime ago. As for the original inhabitants, only time can tell that tale.", "For this expedition I have assembled Ajeck Rouack and Sir S. J Erlgadin, along with my trusted servant, Barnil Stonepot. I fought alongside Ajeck's father's side in many battles in defense of the Alliance. Seeing her grown is quite special. Her father schooled her well in the ways of weaponry. Her skills with a bow make me wonder if there is elven blood running through those veins.", "Sir S. J. Erlgadin comes from human aristocracy. His father, Count Erlgadin, was renowned for his generosity. It was the Count who lobbied for improved working conditions for the Stonemasons' Guild during the restoration of Stormwind after the Second Great War.", "In the years that followed, after Stormwind betrayed the Stonemasons' Guild, Sir Erlgadin grew bitter about the role of the nobles within the Kingdom. He no longer wished to uphold the position that his father's bloodline had earned for him in the House of Nobles. But I digress. The purpose of this story is not to act as a political treatise or a biography. This is the account of my experiences hunting big game in the green hills of Stranglethorn.", "We rose with the sun. Barnil began to prepare the morning meal. I noticed Ajeck's attention was somewhat distracted. The day's trek would be long and our hunt would bring us close to danger. A lack of focus could easily lead to an errant mishap. Yet Ajeck seemed unable to divert her gaze from Barnil who stood by the edge of the river rinsing out his mess kit.", "Just as I was about to question Ajeck's lack of interest in the day's hunting strategy, she reached for her quiver, drew an arrow and unleashed a shot right towards poor Barnil. But it was not Barnil that Ajeck was shooting at. For when Barnil stepped aside, mouth agape, a large river crocilisk floated to the surface with Ajeck's arrow perfectly placed between his two large eyes.", "We set out toward the west, through the thick overgrowth of the tangled jungle. Moving with slow, deliberate steps we paced through thick foliage in search of prey. The morning passed in frustrated silence. Nothing was stirring in the Vale, not even a breeze. By the afternoon, the expedition had grown restless Barnil no longer strode with the cautious steps of a predator tracking prey. Rather he clumsily clomped along the path often stepping noisily on dried leaves or fallen branches.", "During one such misstep, Erlgadin laid a heavy hand on Barnil's shoulder. Ajeck and I gave a casual glance, assuming the man was simply giving Barnil a much-needed scolding for his carelessness. Erlgadin, however, gestured slowly with his head toward a nearby fallen tree. Gazing back at us were two piercing black eyes just above a mouthful of razor sharp fangs." },
    ["item_green_hills_of_stranglethorn_chapter_ii"] = { "The beast was a male Stranglethorn Tiger. Before I could cock my rifle, Erlgadin raised his crossbow and fired upon the beast. The bolt missed its mark and caught the beast heavily in the left flank. The tiger made a futile attempt to flee but its wound was too grave. The beast stumbled for a few tragic seconds until Barnil finished the kill with a thrown axe.", "The kill brought about a festive mood amongst the expedition. Barnil poured mead for all to enjoy. But our festivities were short-lived. As we were preparing the corpse for transport back to base camp we were all caught off guard by a horrendous growl. In all my years I have never heard anything so blood curdling.", "On a rocky precipice above, silhouetted by the setting sun, I could make out the largest cat of prey I have ever laid eyes upon. I was able to loose one clumsy volley with my rifle, but the cat held his ground. He growled once again, this time louder than the first, and vanished.\n\nWe gathered our belongings and headed solemnly back to camp.", "I had promised the expedition that we would spend the next day hunting panthers, as their furs are in high demand throughout Azeroth. It only makes sense that such demand should exist with all of the able-bodied hunters, trappers and fur-traders off giving their lives so valiantly in the name of the Alliance.", "Ajeck and Sir Erlgadin were anxious to learn how to hunt effectively with a Dwarven Rifle. I had the two humans leave their primitive range weapons at base camp. Barnil and I outfitted them with some of Ironforge's finest firearms.", "On this day we ventured to the south, following some fresh panther tracks. Soon we reached a ravine spanned by a tremendous rope bridge. I could not help but to think of Brann's descriptive writings of this region when I saw the engineering marvel. So often it was assumed that the native Trolls were a primitive and uneducated race yet as I gazed upon the master craftsmanship of the bridge I was able to recognize the skill with which the Troll builders overcame the seemingly impossible feat.", "Before long, Ajeck tracked the panther to the southwest. We walked quietly, guns at the ready, in anticipation of our prey. A snapping of twigs from a nearby copse of trees drew our attention immediately. Something was in there. One stern glance at Barnil was enough to convey my thoughts. Barnil slowly lowered his rifle. This kill was not for us; it was for our Human companions. Countless panthers had lost their lives in front of our smoking barrels. This kill would be for the Humans.", "Both Ajeck and Sir Erlgadin stood poised, guns leveled at the bristling overgrowth at the base of the swaying trees. The midday sun beat heavily upon us. A slow trickle of perspiration trailed down from Elrgadin's temple as he pulled the pin back. Upon the sound of the click, the thick flora parted and a large black panther -- a beautiful specimen -- darted out onto the plain." },
    ["item_green_hills_of_stranglethorn_chapter_iii"] = { "The Humans trained their sites on the panther as it ran along the edge of the tree line. The barrels of their guns moved in perfect parallel tandem. Barnil gave me an urging glance but I shook my head no. This hunt was for the Humans, not Barnil or me. Erlgadin fired a booming shot, missing the panther altogether. Apparently he was unprepared for the violent kickback of the rifle blast.", "His gun tossed back violently in his arms. The barrel swooped sideways and came up beneath Ajeck's rifle. Ajeck had chosen that exact moment to pull her trigger. The rifle, the aim now knocked clumsily toward the tree line, went off with a distinct boom. A flock of birds screamed out of the canopy, scattering in every direction. A plume of smoke rose from the tree. We watched in awe as a tremendous branch fell squarely on the fleeing panther, breaking its back.", "As the weeks passed our stockpile of panther and tiger skins grew immense. I decided it was time for the expedition to shift our focus to a new challenge: Raptors.\n\nThe Humans, while appreciative of the training Barnil and I offered, decided to refrain from hunting with firearms. Ajeck was much more comfortable with a finely strung bow and Sir Erlgadin never left camp without his sturdy crossbow.", "We set out at first light, heading south past the Tkashi Ruins. Barnil voiced concern that we might encounter members of the Bloodscalp Tribe. I reminded Barnil that the Bloodscalps were more concerned with destroying their tribal enemy, the Skullsplitters. Needless to say, Barnil was not comforted in the least. I, however, had a loaded rifle, a satchel full of gunpowder and three deadly hunters with me to ease any concerns of an unfriendly ambush.", "I've stood before a towering Infernal on the battlefield, the army of the Burning Legion advancing from all directions. An unruly band of Trolls seems as harmless as a jackrabbit in the hills of Dun Morogh.\n\nWe passed the Tkashi Ruins without event, much to Barnil's relief. The party proceeded to head westward, toward the Great Sea, skirting the Ruins of Zul'Kunda just to the south. As we ascended the high sea bluffs we spotted our first Raptor.", "The beast never so much as detected our presence. In fact, the only greeting he received from the expedition was a bullet between the eyes. Sir Erlgadin let out a hearty *hurrah* as Ajeck nodded toward me with keen approval. I sifted through my pack in search of my pipe, hoping to enjoy a celebratory smoke. Barnil began to scurry up the hillside to retrieve the Raptor's corpse. I stared at the fallen beast with the satisfaction that accompanies every big kill.", "But I could not bask in the glory of the kill for long. For when I turned my eyes toward the horizon, several silhouettes appeared cresting the hill, just above poor Barnil.\n\n*Flee, Barnil!* I shouted. Ajeck, Sir Erlgadin and myself loosed a volley of bullets, arrows and bolts over Barnil and toward the pursuing raptors. One of us landed a kill amidst the confusion.", "Our hastily aimed shots were enough to buy Barnil's escape. Barnil clamored back down the hill and rejoined the party. We scurried off into the jungle; a pack of ferocious Lashtail Raptor's stalking our every move.\n\nThe hunters were now the hunted." },
    ["item_green_hills_of_stranglethorn_chapter_iv"] = { "I led the party toward the sea, hoping the shoreline would provide refuge from the Raptors. In our haste we had drifted too far north, to a precariously high elevation. The mistake was made. The fault was mine. We stopped just short of a sheer cliff, the Raptors just a few paces behind.", "I stepped slowly forward, gun raised. I had led these brave hunters to their death. I would die defending them. Lashtail Raptors are particularly fierce, known for their unrelenting blood-thirst. They far outnumbered us. But I would be damned if I let them kill me and my comrades without shedding some of their own blood first.", "Ajeck and Sir Erlgadin readied their weapons, flanking me on either side, our backs to the sea. Barnil let out a defeated sigh and drew his axe. The Lashtails were almost upon us. Their steady stride had slowed. They were stalking their prey now for they knew they had us trapped.", "And then something miraculous happened. From off to our side we heard the distinct and terrifying roar of the great white tiger. Despite their numbers, the Raptors turned and scattered in all directions. We saw but a brief white flash as the tiger darted past us and pounced on one of the Raptors. No command needed to be given. All four members of our party knew it was time to run.", "We sprinted all the way back to base camp, never slowing. Later that night we sat quietly around the campfire, knowing our lives had been saved by a bizarre twist of fate. Such are the risks of the big game hunter. We toy with fate by delivering it. Yet each of us, at some point, will face fate's razor sharp teeth. This Dwarf is just glad that moment did not come upon the green hills of Stranglethorn." },
    ["item_green_hills_of_stranglethorn_page_1"] = { "The Green Hills of Stranglethorn\n\nOur first day went as well as one can expect first days to go. Most of our time was preoccupied with making the necessary arrangements to establish a base camp. I located an ideal setting by a freshwater river inlet. Judging by the old, abandoned docks nearby, this site was inhabited sometime ago. As for the original inhabitants, only time can tell that tale." },
